an; exitCode?: number; signal?: string; cancelled?: boolean }\n                const sid = v.sid ?? '?'\n                if (v.cancelled === true) {\n                  // 「调用方不等了」与「到点还没结束」是两件事：后者是环境的事实，前者只是你走了。\n                  // 两者都**不关会话**（理由见 execute 里那段注释）。\n                  return [{ type: 'text', text: `被调用方取消（**不是**超时，也不是命令结束）：这条命令还在会话 ${sid} 里跑着，会话也留着——内容没有丢。要接着等用 tty_expect，要看现在的输出用 tty_capture，要停掉它用 tty_close（或 tty_send 发送 C-c）。尾部输出：\\n\\n${v.tail ?? ''}` }]\n                }\n                if (v.running === true) {\n                  return [{ type: 'text', text: `终端会话 ${sid} 里这条命令到点还没结束（它就是面板里的普通标签，用户看得见、可接管）：用 tty_expect 等它的就绪标记、tty_capture 读尾部，或 tty_close 关掉。\\n\\n${v.tail ?? ''}` }]\n                }\n                const how = v.signal !== undefined && v.signal !== '' ? `signal=${v.signal}` : `exitCode=${String(v.exitCode ?? '?')}`\n                const note = v.closed === true\n                  ? '会话已关闭（结果都在下面这段里）。'\n                  : `会话留在只读保留态（sid=${sid}），要回看这段输出可以再 tty_capture（用 lines 读尾部——命令型会话没有「上一条命令」，last:true 会报错）。`\n                return [{ type: 'text', text: `终端会话 ${sid} 的命令已结束（${how}）。${note}\\n\\n${v.tail ?? ''}` }]\n              },\n            },\n            /* 协作式预算：本工具自己最久等 600s（timeoutSec 的钳位上限），声明略大于它。 */\n            timeoutMs: 660_000,\n            async execute(args: unknown, exec?: { signal?: AbortSignal }): Promise<{ sid: string; running: boolean; tail: string; closed: boolean; exitCode?: number; signal?: string; cancelled?: boolean }> {\n              const input = args as { command?: unknown; cwd?: unknown; timeoutSec?: unknown; keep?: unknown; lines?: unknown; cols?: unknown; rows?: unknown }\n              if (typeof input.command !== 'string' || input.command.trim() === '') throw new Error('command 必须是非空字符串')\n              const timeoutSec = clampInt(input.timeoutSec, 120, 1, 600)\n              const lines = clampInt(input.lines, 60, 1, 500)\n              const opened = await server.openAgentSession({\n                command: input.command,\n                ...(typeof input.cwd === 'string' && input.cwd.trim() !== '' ? { cwd: input.cwd } : {}),\n                cols: input.cols,\n                rows: input.rows,\n              })\n              const session = sessions.get(opened.sid)\n              if (session === undefined || session.closed) throw new Error(`会话创建后立刻退役了: ${opened.sid}`)\n              // 命令型会话的进程**就是**那条命令（D78 的 exec 链）：进程退出 = 命令结束，\n              // 与 shell 集成无关（这类会话不注入钩子，等 133;D 是等不到的）\n              const finished = await waitForSessionExit(session, timeoutSec * 1000, exec?.signal)\n              const tail = cleanAnsiTail(tailLines(session, lines))\n              /*\n               * 到点 / 被取消 → 都为 `running: true`，而且**都不关会话**。\n               *\n               * 「取消」这一档是刻意的：`exec.signal` 取消的是**这次工具调用**，不是那条命令——\n               * 关掉会话等于「因为调用方不等了，就把人家跑着的构建杀了」。决定权交回调用方\n               * （tty_close / 发送 C-c），与 `timeoutSec` 到点那条路同一处置。\n               */\n              if (finished !== 'exited') {\n                return {\n                  sid: opened.sid,\n                  running: true,\n                  closed: false,\n                  tail,\n                  ...(finished === 'cancelled' ? { cancelled: true } : {}),\n                }\n              }\n              const exited = session.exited\n              const result = {\n                sid: opened.sid,\n                running: false,\n                tail,\n                closed: false,\n                ...(exited === null || exited.code === null ? {} : { exitCode: exited.code }),\n                ...(exited === null || exited.signal === null || exited.signal === '' ? {} : { signal: exited.signal }),\n              }\n              // keep 默认 false：这条通道的语义就是「一条命令一次调用」，留着会占满\n              // 只读保留的名额（16 条）；要回看现场就显式 keep:true\n              if (input.keep === true) return result\n              await server.closeAgentSession(opened.sid)\n              return { ...result, closed: true }\n            },\n          })))\n          activeDisposers.push(registerTool(defineTool({\n            name: 'tty_stats',\n            // 只读工具：与同轮其它工具并发执行（宿主默认把未声明的工具当独占，见项目级 ROADMAP 第 4 项）\n            isConcurrencySafe: () => true,\n            description: '读取某个终端会话所在机器的实时指标（CPU / 内存 / 磁盘 / TCP 连接数 / 网速 / 温度 / 在线时长 / 1 分钟负载 / 交换分区 / SSH 连接往返）——本地会话取宿主机，SSH 会话取那台远程主机（另开一条非 PTY 通道，不影响终端）。部署、压测、排查「机器是不是满了」之前先看它。仅 Linux 远端字段齐全，Windows 远端部分字段可采，macOS/BSD 远端取不到。',\n            parameters: {\n              sid: { type: 'string', required: true, description: '会话 id（tty_list 提供）' },\n            },\n            output: {\n              schema: {\n                type: 'object',\n                additionalProperties: false,\n                properties: {\n                  sid: { type: 'string', required: true },\n                  available: { type: 'boolean', required: true },\n                  reason: { type: 'string' },\n                  target: { type: 'string' },\n                  cpuPct: { type: 'number' },\n                  cores: { type: 'number' },\n                  memPct: { type: 'number' },\n                  memUsed: { type: 'number' },\n                  memTotal: { type: 'number' },\n                  diskPct: { type: 'number' },\n                  diskUsed: { type: 'number' },\n                  diskTotal: { type: 'number' },\n                  tcpConns: { type: 'number' },\n                  rxRate: { type: 'number' },\n                  txRate: { type: 'number' },\n                  tempC: { type: 'number' },\n                  uptimeSec: { type: 'number' },\n                  load1: { type: 'number' },\n                  /*\n                   * 交换分区与连接往返（2026-11-02）：同样是「宿主帧里的可选字段」——`execute` 把\n                   * 整帧摊平进返回值，所以这里必须逐个声明。0.37.0 已经把 `swapUsed` / `swapTotal`\n                   * 返回出去了、schema 却没有（`additionalProperties: false` 直接判违约，CI 的 B33\n                   * 端到端断言拦下的正是它）；`pingMs` 一并补上——它只是当时没被那条夹具覆盖到才\n                   * 没报