      "path": "packages/tty/src/ssh.ts",
      "content": "/**\n * @hyzyn/dsh-tty — SSH 会话封装（方案 C：ssh2 原生集成）。\n *\n * 不经过本地 ssh 进程 / node-pty，直接用 ssh2 建立连接并开 shell channel，\n * 包装成与本地 PTY 完全一致的 TermHandle 形状，TtyServer 无差别调度：\n * input/resize/kill 上行，data/exit 下行，背压、环形缓冲、agent 工具全复用。\n *\n * 认证优先级由 spec.auth 决定：\n *   agent    —— ssh-agent（SSH_AUTH_SOCK），最推荐，凭证不落盘\n *   key      —— keyPath 私钥文件（~ 可省略 home），passphrase 可选\n *   password —— 密码认证，同时挂 keyboard-interactive（很多服务端只开这个）\n * password / passphrase 支持 `env:VAR` 前缀从进程环境变量取值（配合\n * dsh-env-manager 插件托管密钥，避免明文写入 settings 文件）。\n *\n * 主机密钥策略：known_hosts TOFU（trust-on-first-use）钉扎——hostVerifier 里\n * 首次连接记录 sha256 指纹（经 HostKeyStore 持久化），之后每次连接校验：\n * 指纹一致放行；指纹变更拒绝连接（防中间人冒充），用户确认安全后可在\n * 设置卡片删除该主机记录重连。未提供 hostKeyStore 时退化为 accept-and-log\n * （旧行为，测试路径用）。\n */\nimport { Client } from 'ssh2'\nimport type { ClientChannel, ConnectConfig, ShellOptions } from 'ssh2'\nimport { spawn } from 'node:child_process'\nimport type { ChildProcess } from 'node:child_process'\nimport { readFileSync } from 'node:fs'\nimport { homedir } from 'node:os'\nimport { join } from 'node:path'\nimport { Duplex, PassThrough } from 'node:stream'\nimport { StringDecoder } from 'node:string_decoder'\nimport { tmuxSocketName } from './tmux.js'\nimport { shSingleQuote } from './shell-integration.js'\nimport { StatsLineBuffer } from './stats.js'\n\n/* ------------------------------------------------------------------ *\n * 统一会话句柄：本地 PTY 与 SSH channel 共用同一形状\n * ------------------------------------------------------------------ */\n\nexport interface TermExit {\n  exitCode: number | null\n  signal: string | null\n}\n\n/** 连接往返探针的超时：一条健康链路的 RTT 是几十毫秒，5 秒没回音就不必再等。 */\nconst PROBE_RTT_TIMEOUT_MS = 5000\n\nexport interface TermHandle {\n  readonly kind: 'local' | 'ssh'\n  /** SSH 会话没有本地 pid，为 null。 */\n  readonly pid: number | null\n  /** 输出流（flowing 模式消费；pause/resume 用于下行背压）。 */\n  readonly output: PassThrough\n  /** 退出事实，恰好 resolve 一次。 */\n  readonly done: Promise<TermExit>\n  write(data: string): Promise<unknown>\n  resize(cols: number, rows: number): void\n  terminate(): Promise<unknown>\n  /** terminate 失败后的最后手段（本地 PTY：对顶层 shell 直接 SIGKILL）。 */\n  forceKill?(): void\n  /**\n   * tmux 背书会话（0.10.0 持久化）的关闭收尾：kill-session 让 pane 真正结束，\n   * 而不是只杀客户端把会话留在 tmux server 上。kill 帧路径在 forceKill 前调用。\n   */\n  tmuxTeardown?(): Promise<void>\n  /**\n   * 强制 tmux 重画该会话的全部客户端（0.10.1 跨窗口共享：新绑定连接的\n   * xterm 需要一份可见屏重画）。本地实现走本机 tmux CLI（src/tmux.ts），\n   * SSH 实现在远程连接内 exec（本机 tmux 看不到远程会话）。\n   */\n  tmuxRefresh?(): Promise<void>\n  /**\n   * 服务器状态条（0.17.0）：在同一条 SSH 连接上另开一条**非 PTY 的 exec\n   * channel**（RFC 4254 §6.5）跑常驻采集脚本，按行回调 stdout。返回句柄的\n   * stop() 关闭 channel（远端循环随之结束）。任何失败（对端拒绝 exec、\n   * MaxSessions 超限、连接断开、采集进程自己退出）只回调 onError——采集是\n   * 附加能力，调用方静默停表，绝不写 PTY、绝不弹错。\n   * 只有 SSH 实现提供：本地会话由宿主自己采（见 stats.ts 的本地采样器）。\n   */\n  statsExec?(command: string, onLine: (line: string) => void, onError: () => void): { stop(): void }\n  /**\n   * 连接往返（毫秒，2026-11-01）：在**这条连接**上开一条 exec channel，从发起到服务端\n   * 确认 channel 计时。刻意**不**等命令跑完——那会把「远端起一个 shell」的开销也算进去，\n   * 数字会比真实网络 RTT 大一截。本地会话没有这一项（没有网络对端）。\n   */\n  probeRtt?(): Promise<number | null>\n  /** spawn 后注入终端的灰字提示（如远程无 tmux 降级为普通会话）。 */\n  startupNotice?: string\n}\n\n/* ------------------------------------------------------------------ *\n * 规格与工具\n * ------------------------------------------------------------------ */\n\n/**\n * TOFU 主机指纹记录（0.19.0 起一机多指纹）：known_hosts 里同一 host:port 常\n * 同时有 ssh-rsa 与 ssh-ed25519 两行，而 ssh2 优先协商 ed25519——只留一条\n * 指纹时，RSA 行在前的老机器导入后必然「指纹不符 → 假 MITM 告警」。集合任一\n * 命中即放行；同机指纹总量有上限（防止无界增长），上限内不做算法识别。\n */\nexport interface HostKeyRecord {\n  host: string\n  port: number\n  /** hostVerifier 收到的原样 sha256 十六进制指纹（多把钥匙 = 多个）。 */\n  fingerprints: string[]\n}\n\n/** 内联 SSH 连接规格（ws 帧或连接簿条目共用）。 */\nexport interface SshSpec {\n  host: string\n  port?: number\n  username: string\n  auth?: 'agent' | 'key' | 'password'\n  keyPath?: string\n  passphrase?: string\n  password?: string\n  /** OpenSSH agent forwarding：远程可用本地 ssh-agent 的钥匙（git clone 等）。 */\n  agentForward?: boolean\n  /**\n   * TOFU 定位别名（OpenSSH `HostKeyAlias` 语义）。\n   *\n   * 为什么需要它：known_hosts 的条目按**连接地址**定位，而同一个真实主机常常经不同地址\n   * 触达——跳板机后面直接写内网 IP、或经端口转发落在 `127.0.0.1:2222`。那时「同一把钥匙、\n   * 不同记录」会让每次切换地址都判成**指纹变更**（假 MITM 告警并拒绝连接），而用户的\n   * known_hosts 里本来就只有一条（`HostKeyAlias` 正是 OpenSSH 为这种场景提供的开关）。\n   *\n   * 语义与 OpenSSH 对齐：**只影响主机密钥的存储/比对键**，不改连接地址、不改展示串；\n   * 缺省（空串）= 仍按 `host` 定位，行为与从前完全一致。端口仍参与键\n   * （`别名:port`），因为同一别名下不同端口可能真是不同服务端。\n   */\n  hostKeyAlias?: string\n  /** 经跳板机连接（ProxyJump 语义，**单跳**）；缺省 = 直连。 */\n  jump?: SshJumpSpec\n  /**\n   * 代理命令（ProxyCommand 语义）：本机执行的命令，它的 stdin/stdout 就是 SSH 传输。\n   *\n   * **单独一档信任级**：这是「设置字段驱动的本机任意命令执行」，与跳板机（只连一跳 TCP）\n   * 完全不同。因此：\n   *   - **默认关闭**（settings `allowProxyCommand`）：关着时携带它的连接一律**明确失败**，\n   *     绝不静默退回直连——直连多半也连不上，还会把「配置没生效」伪装成网络问题；\n   *   - **`~/.ssh/config` 导入永不自动带入**（`parseSshConfigDetailed` 只报数）；\n   *   - `%h` / `%p` / `%r` / `%n` / `%%` 按 OpenSSH 同义展开（见 `expandProxyCommand`），\n   *     展开值只允许 `[A-Za-z0-9._@:\\[\\]-]`，否则**拒绝执行**（防连接簿字段注入 shell）；\n   *   - 与 `jump` 同时给时按 OpenSSH 语义 **ProxyJump 优先**，并记一条 warn。\n   */\n  proxyCommand?: string\n}\n\n/**\n * 跳板机规格（ProxyJump 语义，**单跳**）。\n *\n * 与 `SshSpec` 同形但**不再嵌套**——不支持「跳板机的跳板机」；`username` / `auth` /\n * `keyPath` / `passphrase` / `password` 任一缺省都会**继承目标那一跳**（企业内网里两者\n * 通常共用同一把钥匙或同一个 agent），这也正是 v1 的界面只需要一个输入框的原因。\n *\n * 为什么不像 OpenSSH 那样只存 `user@host:port` 字符串：字符串装不下「与目标不同的凭据」，\n * 而本仓所有认证都要走 `resolveSecret`（`env:VAR` 引用 / 凭据存储层）。界面与导入可以把\n * 简写解析成这个结构。\n *\n * 凭据永不进日志与错误文案：展示串只由 `jumpTargetLabel()` 生成（`user@host:port`）。\n */\nexport interface SshJumpSpec {\n  host: string\n  port?: number\n  username?: string\n  auth?: 'agent' | 'key' | 'password'\n  keyPath?: string\n  passphrase?: string\n  password?: string\n}\n\n/** 连接簿条目（带名字，存 settings）。 */\nexport interface SshHostEntry extends SshSpec {\n  name: string\n  /** 该条目的 SSH 标签默认以 tmux 持久会话打开（仅宿主 persistence=tmux 时生效）。 */\n  persist?: boolean\n}\n\nexport interface SshSpawnOptions {\n  term: string\n  cols: number\n  rows: number\n  logger?: { info(msg: string): void; warn(msg: string): void }\n  /**\n   * known_hosts TOFU 钉扎存储：首次连接 record() 记录指纹，之后 get() 校验。\n   * 缺省时退化为 accept-and-log（仅记录指纹，无条件放行）。\n   */\n  hostKeyStore?: HostKeyStore\n  /**\n   * tmux 会话持久化（0.10.0）：远程以 `exec tmux new-session -A -s <name>` 开\n   * pty channel（专用 socket，按本机 profile 区分，见 tmuxSocketName），会话托管在远程 tmux server 上，断线/\n   * 宿主重启后按同名接回。远程无 tmux 时降级普通 shell channel，\n   * startupNotice 带提示。name 须已过 sanitizePersistName（安全字符集）。\n   */\n  persist?: { name: string }\n  /**\n   * 自定义远程命令（0.14.0）：给「开一个标签直接跑某条命令」用（如\n   * `docker exec -it <容器> sh`）。设置后走 `conn.exec(command, {pty})`，\n   * 不建登录 shell、也不做 tmux 持久化（命令的生命周期本就短）。\n   * 命令由宿主侧插件提供，单行（由帧解析保证）。\n   */\n  command?: string\n}\n\n/**\n * 主机指纹钉扎存储（宿主半体实现为 LiveConfig + settings 持久化）。\n * get 返回 undefined 表示该 host:port 从未记录；返回数组（≥1 条）时任一命中放行。\n */\nexport interface HostKeyStore {\n  /** 已记录的指纹集合（hostVerifier 收到的原样十六进制串）；未记录返回 undefined。 */\n  get(host: string, port: number): string[] | undefined\n  /** 握手时记录指纹（已存在该 host:port 的记录则并入集合）。 */\n  record(host: string, port: number, fingerprint: string): void\n}\n\n/**\n * 官方凭据服务的**最小结构面**（结构类型，不把这个包加成本插件依赖）。\n *\n * 契约见 `@deepseek-ai/dsh-credentials`：`resolve(ref)` **每次操作重新解析、不得跨操作缓存**，\n * 返回 `{ value, source }` 或 undefined。这里只声明用到的那一个方法——既不必引依赖，也能在\n * 服务缺失时静态看出\"没有它\"。\n */\nexport interface CredentialResolver {\n  resolve(ref: string): Promise<{ value: string } | undefined>\n}\n\nlet credentialsProvider: CredentialResolver | null = null\n\n/** 由 index.ts 在可选注入里挂上（服务缺失即为 null，退回 process.env）。 */\nexport function setCredentialResolver(resolver: CredentialResolver | null): void {\n  credentialsProvider = resolver\n}\n\n/**\n * 解析密钥引用（`env:NAME`）——**纯核心**，provider 由调用方给，便于离线断言。\n *\n * 顺序：官方凭据 provider **优先**（它自己叠 `file`（`$DSH_HOME/.credentials.yaml`）/ `env` /\n * `project-env` / `user-env` 各层，而且\"每次操作重新解析\"——改完下一个操作即生效，不必重启\n * 宿主）；服务不在、或它没有这个引用时，再退回 `process.env`。\n *\n * 为什么必须走 provider：凭据存储里的值**永远不会被 materialize 进环境**（provider README 原话：\n * \"a store the harness owns and never materializes into the environment\"），所以只读\n * `process.env` 等于\"存进凭据存储的值连接时根本读不到\" ✗ —— 这正是「存入凭据存储」这条链此前\n * 断掉的地方（客户端那半切好了、宿主这半没切）。\n *\n * provider 抛错**不吞**：记下来，若环境变量也没有就把两个来源一起写进错误里。否则\"凭据服务\n * 坏了\"会伪装成\"你没配\"，而那是最难查的一类。\n */\nexport async function resolveSecretVia(\n  provider: CredentialResolver | null,\n  value: string | undefined,\n): Promise<string | undefined> {\n  if (value === undefined) return undefined\n  if (!value.startsWith('env:')) return value\n  const name = value.slice(4)\n  let providerError: string | null = null\n  /** provider 明确找到了该引用（哪怕值是空串）——与「引用不存在」分开报 */\n  let providerFound = false\n  if (provider !== null && provider !== undefined && typeof provider.resolve === 'function') {\n    try {\n      const resolved = await provider.resolve(name)\n      if (resolved !== null && resolved !== undefined) {\n        providerFound = true\n        if (typeof resolved.value === 'string' && resolved.value !== '') {\n          return resolved.value\n        }\n      }\n    } catch (error) {\n      providerError = error instanceof Error ? error.message : String(error)\n    }\n  }\n  const fromEnv = process.env[name]\n  if (fromEnv !== undefined && fromEnv !== '') return fromEnv\n  // 「存在但值为空」单独报：报成「未设置」会把用户引去新建同名引用——那只会再失败一次\n  if (providerFound || fromEnv === '') {\n    const detail = providerError === null ? '' : `（凭据服务报错：${providerError}）`\n    throw new Error(`凭据 ${name} 的值是空串${detail}——请在凭据存储或环境变量里补上实际值，新建同名引用解决不了`)\n  }\n  const detail = providerError === null ? '' : `（凭据服务报错：${providerError}）`\n  const missing = provider === null ? '凭据服务不可用，' : ''\n  throw new Error(`凭据未设置：${name}${detail} —— ${missing}环境变量里也没有`)\n}\n\n/** 生产路径：用当前注入的 provider（`index.ts` 注入；没注入就是 null）。 */\nexport async function resolveSecret(value: string | undefined): Promise<string | undefined> {\n  return resolveSecretVia(credentialsProvider, value)\n}\n\nfunction expandHome(path: string): string {\n  if (path === '~') return homedir()\n  if (path.startsWith('~/')) return join(homedir(), path.slice(2))\n  return path\n}\n\n/** 供 ~/.ssh/config 导入路由使用（~ 与 ~/ 前缀展开 home）。 */\nexport { expandHome }\n\n/** 展示用目标串：user@host（非默认端口时带 :port）。 */\nexport function sshTarget(spec: SshSpec): string {\n  const port = spec.port ?? 22\n  return `${spec.username}@${spec.host}${port === 22 ? '' : ':' + String(port)}`\n}\n\n/**\n * 把 ssh2 的底层错误消息分类为人类可读诊断（0.19.0 自 probe.ts 上移至此统一\n * 导出——终端 / 隧道 / 探测三条路径共用同一套文案，不再透传原始英文）。\n * 分类串本身已含关键字段；无法识别时原样返回。\n */\nexport function classifyError(message: string): string {\n  if (message === 'Host key verification failed') {\n    return '主机密钥校验失败（TOFU 不匹配，见 hostkey 指引）'\n  }\n  if (message.includes('All configured authentication methods failed')) {\n    return '认证被拒绝：所有认证方式均失败（用户名/密码/密钥是否正确，或服务端是否允许该认证方式）'\n  }\n  if (message.includes('Timed out')) {\n    // 跳板机提示（项目级 ROADMAP 第 2 项）：企业内网主机几乎都要过 bastion，而本版本\n    // 不支持——「20s 后一句通用超时」正是原文点名的症状。导入侧已改为跳过并明说，\n    // 这里补上手工填地址那条路。\n    return '超时：主机无响应或认证协商超时（检查地址 / 端口 / 防火墙 / 网络。'\n      + '若该主机只能经跳板机访问（~/.ssh/config 里的 ProxyJump / ProxyCommand），本版本尚不支持，'\n      + '见项目级 ROADMAP 第 2 项）'\n  }\n  const lower = message.toLowerCase()\n  if (lower.includes('econnrefused')) return '连接被拒绝（ECONNREFUSED）：端口未监听或服务未启动'\n  if (lower.includes('enetunreach')) return '网络不可达（ENETUNREACH）：路由不通或主机离线'\n  if (lower.includes('ehostunreach')) return '主机不可达（EHOSTUNREACH）'\n  if (lower.includes('eai_again') || lower.includes('eai_noname') || lower.includes('enotfound')) return 'DNS 解析失败：主机名无法解析'\n  if (lower.includes('getaddrinfo')) return 'DNS 解析失败：主机名无法解析'\n  if (lower.includes('unable to exchange encryption keys') || lower.includes('encryption') || lower.includes('kex')) {\n    return '密钥交换失败：服务端可能不是 SSH 服务，或加密算法不兼容'\n  }\n  if (lower.includes('keepalive')) return '连接保活超时（keepalive）'\n  if (lower.includes('protocol')) return '协议错误：' + message\n  return message\n}\n\n/* ------------------------------------------------------------------ *\n * 连接与 channel 包装\n * ------------------------------------------------------------------ */\n\n/**\n * 构造连接配置（认证三态 + keepalive + hostHash）；spawnSsh / probeSsh / SFTP / 隧道共用。\n *\n * **async**：`env:NAME` 引用要经官方凭据 provider 解析（每操作重解析，不可缓存），见\n * resolveSecretVia —— 这是\"存入凭据存储\"的值能被连接真正用到的唯一通路。\n */\nexport async function buildConnectConfig(spec: SshSpec): Promise<ConnectConfig> {  const auth = spec.auth ?? 'agent'\n  const base: ConnectConfig = {\n    host: spec.host,\n    port: spec.port ?? 22,\n    username: spec.username,\n    readyTimeout: 20000,\n    keepaliveInterval: 10000,\n    keepaliveCountMax: 3,\n    // hostVerifier 依赖 hostHash 计算指纹；放行与否由 spawnSsh 里的\n    // TOFU 策略（HostKeyStore）决定，见文件头策略说明\n    hostHash: 'sha256',\n  }\n  if (auth === 'agent') {\n    // 预检（0.19.0）：缺 SSH_AUTH_SOCK 时 ssh2 只会报「All configured\n    // authentication methods failed」，用户根本想不到是 agent 没跑\n    if (process.env.SSH_AUTH_SOCK === undefined || process.env.SSH_AUTH_SOCK === '') {\n      throw new Error('auth=agent 需要 SSH_AUTH_SOCK（本机未运行 ssh-agent 或变量未设置）；在终端面板宿主环境起 agent，或改用 key / password 认证')\n    }\n    base.agent = process.env.SSH_AUTH_SOCK\n  } else if (auth === 'key') {\n    if (typeof spec.keyPath !== 'string' || spec.keyPath.trim() === '') {\n      throw new Error('auth=key 需要 keyPath（私钥路径）')\n    }\n    base.privateKey = readFileSync(expandHome(spec.keyPath.trim()))\n    const passphrase = await resolveSecret(spec.passphrase)\n    if (passphrase !== undefined) base.passphrase = passphrase\n  } else {\n    const password = await resolveSecret(spec.password)\n    if (password === undefined) throw new Error('auth=password 需要 password（或 env:VAR 引用）')\n    base.password = password\n    // 大量服务端（如部分路由器/堡垒机）只开 keyboard-interactive\n    base.tryKeyboard = true\n  }\n  // agent forwarding 需要 agent 通道：key/password 认证时也把 SSH_AUTH_SOCK\n  // 挂上（只用于转发，不参与认证）。@types/ssh2 的 ConnectConfig.agentForward\n  // 在缺 agent 时会直接 throw，故这里仅在 SOCK 存在时设置\n  if (spec.agentForward === true && process.env.SSH_AUTH_SOCK !== undefined && process.env.SSH_AUTH_SOCK !== '') {\n    base.agent = base.agent ?? process.env.SSH_AUTH_SOCK\n  }\n  return base\n}\n\n/** 本文件与各连接点共用的最小日志面（结构上兼容宿主 logger）。 */\nexport interface SshLogger {\n  info(msg: string): void\n  warn(msg: string): void\n}\n\n/** @types/ssh2 的 ShellOptions 未声明 agentForward（运行时支持），最小补丁类型。 */\ntype ShellOptionsWithAgentForward = ShellOptions & { agentForward?: boolean }\n\n/**\n * 记录/比对主机密钥时用的**键**（OpenSSH `HostKeyAlias` 语义）。\n *\n * 抽成一处（而不是在 terminal / SFTP / 隧道 / 探针四个连接点各写一遍）的理由与\n * `prepareSshConnect` 相同：四个点必须用**同一个键**，否则「终端里记下的指纹、SFTP 不认」\n * 这种半吊子状态就是必然。别名只在非空时生效，且**不改连接地址**——它仅决定这条连接\n * 的指纹去哪张记录里查/写。\n *\n * `port` 与原实现一致：仍按 `spec.port ?? 22`（别名不参与端口的推导）。\n */\nexport function hostKeyIdentity(spec: SshSpec): { host: string; port: number; aliased: boolean } {\n  const host = spec.host.trim()\n  const alias = typeof spec.hostKeyAlias === 'string' ? spec.hostKeyAlias.trim() : ''\n  return { host: alias === '' ? host : alias, port: spec.port ?? 22, aliased: alias !== '' && alias !== host }\n}\n\n/**\n * TOFU 主机指纹策略（hostVerifier 接线）；返回的 mismatchMessage() 供连接错误路径取人类可读拒绝原因。\n */\nexport function applyHostKeyPolicy(options: {\n  connectConfig: ConnectConfig\n  spec: SshSpec\n  store?: HostKeyStore\n  logger?: { info(msg: string): void; warn(msg: string): void }\n  target: string\n}): { mismatchMessage(): string | null } {\n  const { connectConfig, spec, store, logger, target } = options\n  const { host: keyHost, port } = hostKeyIdentity(spec)\n  const aliased = keyHost !== spec.host.trim()\n  /** 记录/比对的键带别名时，文案里点明「按别名 <名> 定位」——否则用户会去删错记录。 */\n  const where = aliased ? `${target}（HostKeyAlias ${keyHost}）` : target\n  let hostKeyMismatch: string | null = null\n  connectConfig.hostVerifier = (hash: string) => {\n    const known = store?.get(keyHost, port)\n    if (known === undefined || known.length === 0) {\n      store?.record(keyHost, port, hash)\n      logger?.info(`[dsh-tty] ssh ${where} 首次连接，已记录 host key 指纹 sha256:${hash}（TOFU）`)\n      return true\n    }\n    if (known.includes(hash)) {\n      logger?.info(`[dsh-tty] ssh ${where} host key 指纹匹配（sha256:${hash}，该主机共记录 ${String(known.length)} 把钥匙）`)\n      return true\n    }\n    const shown = known.slice(0, 3).map((f) => `sha256:${f}`).join(' / ')\n    const more = known.length > 3 ? ` 等 ${String(known.length)} 把` : ''\n    hostKeyMismatch =\n      `SSH 主机密钥指纹变更：${where} 已记录 ${shown}${more}，本次为 sha256:${hash}。` +\n      '可能是主机重装或换钥匙，也可能是中间人（MITM）冒充；确认安全后，到 插件配置 → 终端面板 → SSH 主机密钥记录 删除该主机再重连。'\n    logger?.warn(`[dsh-tty] ${hostKeyMismatch}`)\n    return false\n  }\n  return { mismatchMessage: () => hostKeyMismatch }\n}\n\n/**\n * 可用的跳板机规格；`undefined` = **真的没配**。\n *\n * 为什么要这一道，而不是只判 `spec.jump !== undefined`：`SshSpec.jump` 的类型来自 settings\n * schema，而 schemastery 给**嵌套 object 字段**的默认值是 `{}`（见 `SSH_HOST_SCHEMA.jump`），\n * 于是「没配跳板机」的条目可能带着 `jump: { port: 22, username: '', … }` 这种**没有 host 的\n * 半个对象**进入连接路径。0.33.0 的 `jumpTargetLabel` 直接 `jump.host.trim()`：\n * `Cannot read properties of undefined (reading 'trim')`——**每一条**连接簿条目都连不上，\n * 报的还是一句看不出跟跳板机有关的 TypeError（D102）。\n *\n * 判据只认 `host` 是非空字符串：其余字段（端口 / 用户 / 凭据）本来就可以继承目标那一跳。\n * 收在一处（而不是终端 / SFTP / 隧道 / 探针各写一遍）的理由与 `prepareSshConnect` 相同：\n * 四个连接点必须用**同一个**判据，否则又是「终端能连、SFTP 报错」的半吊子状态。\n */\nexport function usableJump(spec: Pick<SshSpec, 'jump'>): SshJumpSpec | undefined {\n  // 运行时数据来自 JSON 帧 / settings 存储，可能是 null（类型上不该有，但这是边界）\n  const jump = spec.jump as SshJumpSpec | undefined | null\n  if (jump === undefined || jump === null) return undefined\n  if (typeof jump.host !== 'string' || jump.host.trim() === '') return undefined\n  return jump\n}\n\n/** 跳板机展示串（`user@host:port`）；没有跳板机时返回空串。**凭据不进这里**。 */\nexport function jumpTargetLabel(spec: SshSpec): string {\n  const jump = usableJump(spec)\n  if (jump === undefined) return ''\n  const port = jump.port ?? 22\n  return `${jump.username ?? spec.username}@${jump.host.trim()}${port === 22 ? '' : ':' + String(port)}`\n}\n\n/**\n * 目标那一跳的展示串 + 跳板机 / 代理命令后缀（**给用户看的错误文案**用）。\n *\n * 为什么错误文案必须带这一句：ssh2 在两跳上共用 `readyTimeout`，报的都是\n * `Timed out while waiting for handshake`——不点名的话「跳板机不可达」会伪装成\n * 「目标超时」，用户会去查对端主机而问题在跳板机上。代理命令同理：它一旦启动失败，\n * 报出来的是「握手前连接中断」。\n *\n * **不回显命令原文**（可能含 `-i /path/key` 这类凭据）：只写「经代理命令」。\n */\nfunction targetWithJump(spec: SshSpec): string {\n  const label = jumpTargetLabel(spec)\n  if (label !== '') return `${sshTarget(spec)}（经跳板机 ${label}）`\n  if (sanitizeProxyCommand(spec.proxyCommand) !== undefined) return `${sshTarget(spec)}（经代理命令）`\n  return sshTarget(spec)\n}\n\n/**\n * 跳板机那一跳的连接规格：显式给的优先，其余**继承目标**。\n *\n * `jump` 由调用方经 `usableJump()` 取（保证 `host` 是非空字符串）——这里不再自己判空，\n * 也不接受 `spec.jump` 的原始形态：那正是「半个对象」能把 `trim()` 打到 undefined 上的入口。\n */\nfunction jumpSpecOf(spec: SshSpec, jump: SshJumpSpec): SshSpec {\n  const username = typeof jump.username === 'string' && jump.username.trim() !== '' ? jump.username.trim() : spec.username\n  return {\n    host: jump.host.trim(),\n    port: jump.port ?? 22,\n    username,\n    auth: jump.auth ?? spec.auth ?? 'agent',\n    keyPath: jump.keyPath ?? spec.keyPath,\n    passphrase: jump.passphrase ?? spec.passphrase,\n    password: jump.password ?? spec.password,\n  }\n}\n\n/**\n * 跳板机连接 + 借来的通道（目标那一跳把它当 `ConnectConfig.sock`）。\n *\n * 跳板机**自己的 TOFU 策略**在 `dialJump` 内部就接好了（指纹变更提示必须来自正确的那一跳，\n * 而握手期的错误也只有那一段能拿到），所以不往外传句柄。\n */\nexport interface JumpDial {\n  /**\n   * 跳板机连接：**它拥有通道**，目标 client 只是借用（ssh2 的 `end()`/`destroy()` 只关\n   * 借来的通道，不关跳板机传输）——谁拨的号，谁就要在收尾时 `end()` 它。\n   */\n  bastion: Client\n  sock: ClientChannel\n}\n\n/** 跳板机通道打开兜底（与 channel 打开兜底同思路：对端不回 `forwardOut` 回调时不能让 await 挂着）。 */\nconst JUMP_CHANNEL_TIMEOUT_MS = 15_000\n\n/**\n * 远端 tmux 探测：单次超时 + 补探轮数（D82）。\n *\n * 为什么补探：`command -v tmux` 是**毫秒级**命令，10s 打不满就只可能是远端忙 / 链路\n * 慢 / channel 被拒（sshd MaxSessions 之类）。原先超时与「没装」同一条降级路径，\n * 用户显式要的持久化被瞬时状况关掉，提示还写成「未安装」。补探一次把这类瞬时状况\n * 和真的没装分开；轮数封顶（spawn 路径是同步等的，不能无限等）。\n */\nconst REMOTE_TMUX_PROBE_TIMEOUT_MS = 10_000\n/** 补探**次数**上限（不是总轮数）：1 = 首探 + 补探一次，同步最坏 2×10s。 */\nconst REMOTE_TMUX_PROBE_ROUNDS = 1\n\n/**\n * 拨跳板机并借一条 `forwardOut` 通道（ProxyJump 单跳）。\n *\n * 三件事刻意做在这里：\n *   1. **失败一律点名跳板机**（见 `targetWithJump` 的理由）；\n *   2. **指纹策略单独一份**：TOFU 的键是 `(host, port)`，跳板机与目标撞 host:port\n *      （NAT 后的 `127.0.0.1:22` 很常见）时不能共用句柄，否则会出现假「指纹变更」；\n *   3. **失败路径自己关连接**：抛出去之前 `end()` 掉，否则每次重试都会漏一条\n *      keepalive 一直养着的连接。\n */\nexport async function dialJump(options: {\n  spec: SshSpec\n  store?: HostKeyStore\n  logger?: SshLogger\n  /** 覆盖跳板机那一跳的握手超时（探针路径要短；缺省沿用 buildConnectConfig 的 20s）。 */\n  readyTimeoutMs?: number\n}): Promise<JumpDial> {\n  /*\n   * 跳板机规格只从 `usableJump()` 取（判据：host 是非空字符串）。`dialJump` 是**导出**的，\n   * 调用方可能拿着半截 `jump`（如配置层物化出来的 `{ port: 22 }`）直接走进来——在那里抛一句\n   * 点名的错，好过让 `jump.host.trim()` 抛 TypeError（用户只看到「Cannot read properties」）。\n   */\n  const jump = usableJump(options.spec)\n  if (jump === undefined) throw new Error('跳板机配置缺少 host（jump.host 为空）——请在连接簿里重新填写跳板机地址')\n  const jumpSpec = jumpSpecOf(options.spec, jump)\n  const label = jumpTargetLabel(options.spec)\n  const destination = sshTarget(options.spec)\n  const bastion = new Client()\n  const closeQuietly = (): void => {\n    try {\n      bastion.end()\n    } catch {\n      /* 已断开 */\n    }\n  }\n  let connectConfig: ConnectConfig\n  try {\n    connectConfig = await buildConnectConfig(jumpSpec)\n  } catch (error) {\n    // 预检类错误（缺 SSH_AUTH_SOCK / keyPath 读不到 / 引用解析不到）也要点名跳板机\n    throw new Error(`跳板机连接失败（${label}）：${error instanceof Error ? error.message : String(error)}`)\n  }\n  if (options.readyTimeoutMs !== undefined) connectConfig.readyTimeout = options.readyTimeoutMs\n  const policy = applyHostKeyPolicy({ connectConfig, spec: jumpSpec, store: options.store, logger: options.logger, target: `跳板机 ${label}` })\n  await new Promise<void>((resolve, reject) => {\n    let settled = false\n    const fail = (error: Error): void => {\n      if (settled) return\n      settled = true\n      closeQuietly()\n      reject(error)\n    }\n    bastion.once('ready', () => {\n      if (settled) return\n      settled = true\n      resolve()\n    })\n    bastion.on('error', (error: Error) => {\n      fail(new Error(policy.mismatchMessage() ?? `跳板机连接失败（${label}）：${classifyError(error.message)}`))\n    })\n    bastion.once('close', () => {\n      fail(new Error(`跳板机连接已关闭（${label}）：目标连接尚未建立`))\n    })\n    if ((connectConfig as { tryKeyboard?: boolean }).tryKeyboard === true) {\n      const password = (connectConfig as { password?: string }).password ?? ''\n      bastion.on('keyboard-interactive', (_name, _instructions, _lang, _prompts, finishKb) => {\n        finishKb([password])\n      })\n    }\n    try {\n      bastion.connect(connectConfig)\n    } catch (error) {\n      fail(new Error(`跳板机连接失败（${label}）：${error instanceof Error ? error.message : String(error)}`))\n    }\n  })\n  const sock = await new Promise<ClientChannel>((resolve, reject) => {\n    let settled = false\n    const timer = setTimeout(() => {\n      if (settled) return\n      settled = true\n      closeQuietly()\n      reject(new Error(`跳板机通道打开超时（${label} → ${destination}，${String(JUMP_CHANNEL_TIMEOUT_MS / 1000)}s 无响应）：跳板机可能不允许转发或不响应`))\n    }, JUMP_CHANNEL_TIMEOUT_MS)\n    timer.unref?.()\n    bastion.forwardOut('127.0.0.1', 0, options.spec.host, options.spec.port ?? 22, (error: Error | null | undefined, channel: ClientChannel) => {\n      if (settled) return\n      settled = true\n      clearTimeout(timer)\n      if (error !== undefined && error !== null) {\n        closeQuietly()\n        reject(new Error(`跳板机通道打开失败（${label} → ${destination}）：${error.message}`))\n        return\n      }\n      resolve(channel)\n    })\n  })\n  options.logger?.info(`[dsh-tty] ssh ${destination} 经跳板机 ${label} 已建立转发通道（ProxyJump）`)\n  return { bastion, sock }\n}\n\n/* ------------------------------------------------------------------ *\n * ProxyCommand：单独一档信任级（默认关闭 + 显式开关 + 导入永不自动带入）\n * ------------------------------------------------------------------ */\n\n/** 代理命令长度上限：与自定义命令标签同量级（它是一条命令行，不是脚本文件）。 */\nexport const PROXY_COMMAND_MAX = 2000\n/** 保留的子进程 stderr 上限（错误文案里只截一小段，避免把用户的日志整片吞进来）。 */\nconst PROXY_STDERR_KEEP = 2048\n/** 错误文案里展示的 stderr 片段上限。 */\nconst PROXY_STDERR_SHOWN = 300\n/** 代理命令 SIGTERM 之后的 SIGKILL 兜底（毫秒）。 */\nconst PROXY_KILL_GRACE_MS = 2000\n/**\n * `%h` / `%r` 等展开值允许的字符集。\n *\n * 为什么不是「先转义再代入」：代理命令最终交给 `sh -c`（Windows 是 `cmd /c`），\n * 而两边的转义规则不同（单引号在 cmd 里无效）。改为**白名单**：主机名 / 用户名本就\n * 只该由这些字符组成，含别的字符就直接拒绝执行——比「按平台各写一套转义」既短又稳。\n */\nconst PROXY_VALUE_SAFE = /^[A-Za-z0-9._@:\\[\\]-]+$/\n\n/** 关着闸门时携带代理命令的连接报什么错（导出供单测与客户端文案对照）。 */\nexport const PROXY_COMMAND_DISABLED =\n  '代理命令（ProxyCommand）未启用：请到 插件配置 → 终端面板 打开「允许 ProxyCommand」后重试。'\n  + '未启用时携带代理命令的连接不会退回直连——直连多半也连不上，还会把配置问题伪装成网络问题。'\n\n/**\n * 宿主**没有授权**这条能力时报什么错（与「授权了但开关关着」分开报）。\n *\n * 为什么要分开：两者的「下一步动作」完全不同——前者要去宿主侧设环境变量 + 重启（界面上那个\n * 开关是点不动的），后者只是把开关打开。合成一句话会让用户对着一个点不动的开关反复点。\n */\nexport const PROXY_COMMAND_NOT_GRANTED =\n  '代理命令（ProxyCommand）未获宿主授权：'\n  + '在宿主侧设置环境变量 DSH_TTY_ALLOW_PROXY_COMMAND=1（可用 设置 → 环境变量 卡片写入 ~/.dsh/env.yml）'\n  + '并重启宿主；HTTP 侧只能关闭它、不能打开（本机任意进程都能发回环请求，配置路由若能提权，这道闸门等于没有）。'\n\n/**\n * ProxyCommand 闸门（**模块级策略，缺省「未授权 + 未启用」**）。\n *\n * 两个维度刻意分开：\n *   - `granted`：**宿主侧**授权（环境变量，进程启动时采样一次，见 kit 的 capability.js）。\n *     未授权时这个开关在 HTTP 侧点不动——那是整个「只能降不能升」约定的落点；\n *   - `enabled`：界面上那个开关（可以随时关，也可以随时开——但只有在授权为真时才可能开）。\n *\n * 为什么是模块级而不是每次调用传参：本包的建连入口有四个（终端 / SFTP / 隧道 / 探针），\n * 而它们**共用** `prepareSshConnect` ——把开关读在拨号那一处，四条路就不会各判一次\n * （漏一条就是「配了等于没配」或「关了还能用」）。写入方只有插件自己的 settings 热应用\n * （`applyPatch`），与 `setCredentialResolver` 同一个模式。\n */\nlet proxyCommandGranted = false\nlet proxyCommandEnabled = false\n\n/** 设置 ProxyCommand 闸门（插件 settings 就绪与每次热更新时调用）。 */\nexport function setProxyCommandPolicy(next: { granted: boolean; enabled: boolean }): void {\n  proxyCommandGranted = next.granted === true\n  proxyCommandEnabled = next.enabled === true\n}\n\n/** 当前是否真的会用代理命令（探针用它把「配了但没开」与「连不上」分开报）。 */\nexport function proxyCommandAllowedNow(): boolean {\n  return proxyCommandGranted && proxyCommandEnabled\n}\n\n/** 宿主侧是否授权了这条能力（探针用它选文案：未授权 vs 未启用）。 */\nexport function proxyCommandGrantedNow(): boolean {\n  return proxyCommandGranted\n}\n\n/**\n * 清洗一份代理命令输入（settings schema / 宽松清洗 / 内联融合共用）。\n *\n * 返回 `undefined` = 没配。**只做形状校验**（非空 / 单行 / 长度），命令内容本身不解释——\n * 「能不能执行」由闸门决定，不由这里猜（含 `;` `/` `|` 都是合法的 shell 写法）。\n */\nexport function sanitizeProxyCommand(input: unknown): string | undefined {\n  if (typeof input !== 'string') return undefined\n  const trimmed = input.trim()\n  if (trimmed === '' || trimmed.length > PROXY_COMMAND_MAX) return undefined\n  if (/[\\r\\n\\0]/.test(trimmed)) return undefined\n  return trimmed\n}\n\n/** 严格校验一份代理命令输入（HTTP POST 路径）；返回错误信息或清洗结果。 */\nexport function validateProxyCommand(input: unknown): { proxyCommand?: string; error?: string } {\n  if (typeof input !== 'string') return { error: 'proxyCommand 必须是字符串' }\n  const trimmed = input.trim()\n  if (trimmed === '') return {}\n  if (trimmed.length > PROXY_COMMAND_MAX) return { error: `proxyCommand 过长（≤${String(PROXY_COMMAND_MAX)} 字符）` }\n  if (/[\\r\\n\\0]/.test(trimmed)) return { error: 'proxyCommand 必须是单行（不能含换行/NUL）' }\n  return { proxyCommand: trimmed }\n}\n\n/** 展示用片段（不含凭据；控制字符清掉、单行、截断）。 */\nfunction excerpt(value: string): string {\n  const oneLine = value.replace(/[\\u0000-\\u001f\\u007f]+/g, ' ').replace(/\\s+/g, ' ').trim()\n  return oneLine.length > 60 ? `${oneLine.slice(0, 60)}…` : oneLine\n}\n\n/**\n * 展开 `%h` / `%p` / `%r` / `%n` / `%%`（与 OpenSSH 同义）。\n *\n * `%h` 目标主机、`%p` 目标端口、`%r` 目标用户名、`%n` 目标主机（如写法里给的名字——\n * 本包没有别名概念，与 `%h` 同值）、`%%` 字面 `%`。其余 `%X` **原样保留**（不报错）：\n * 用户可能是在命令里写 `printf '%s'`，替我们没实现的占位符而失败才是意外。\n *\n * 代入值必须过白名单，否则**抛错拒绝执行**（见 `PROXY_VALUE_SAFE`）。\n */\nexport function expandProxyCommand(command: string, spec: SshSpec): string {\n  const values: Record<string, string> = {\n    h: spec.host,\n    n: spec.host,\n    p: String(spec.port ?? 22),\n    r: spec.username,\n  }\n  return command.replace(/%(.)/g, (whole: string, key: string) => {\n    if (key === '%') return '%'\n    const value = values[key]\n    if (value === undefined) return whole\n    if (!PROXY_VALUE_SAFE.test(value)) {\n      throw new Error(\n        `代理命令里的 %${key} 无法代入：${excerpt(value)} 含 shell 特殊字符（只允许字母数字与 . _ @ : [ ] -）`,\n      )\n    }\n    return value\n  })\n}\n\n/** 代理命令传输：子进程 + 它的 stdio（目标那条连接把 stdio 当 `ConnectConfig.sock`）。 */\nexport interface ProxyCommandDial {\n  /**\n   * 代理命令子进程：**它拥有传输**，目标 client 只是借用——ssh2 的 `end()`/`destroy()`\n   * 只关借来的流，不会去杀子进程。\n   */\n  child: ChildProcess\n  /** 目标连接用的传输（stdin/stdout 合成的 Duplex）。 */\n  sock: Duplex\n  /** 子进程提前退出 / 出错的事实；没有则 null（错误文案里点名它，别让用户去查目标主机）。 */\n  failure(): Error | null\n  /**\n   * 已经攒到的 stderr 摘要（`；代理命令 stderr: …` 或空串）——**错误路径的兜底**。\n   *\n   * 为什么需要它（真机验收才暴露的竞态）：ssh2 一看到流断了就报错，而「子进程退出 / 传输\n   * 关闭」这两个事件比它晚 1~2ms，于是 `failure()` 那一刻还是 null，错误文案就只剩一句\n   * 「连接已关闭」——最有用的一句（命令自己说了什么）被丢掉。调用方**已经在报错**时，\n   * 手里有 stderr 就该交出去；没有 stderr 则返回空串（不制造噪音）。\n   */\n  stderrHint(): string\n  /**\n   * 等 stdio 排空（最多 `ms`）——**拼错误文案之前**调用。\n   *\n   * 为什么需要它（tty D95）：`exit` 只说明进程没了，**不保证 stderr 已经交到我们手里**——\n   * 负载下 stderr 的数据事件可能排在 `exit` / 传输 `close` 之后（真机与 CI 都实测到过：\n   * 「代理命令已退出（退出码 1）」那一刻 chunks 还是空的），于是最有用的一句（命令自己说了\n   * 什么）被丢成「传输已关闭（命令已结束）」，用户只能去猜。子进程的 `close` 事件是\n   * 「已退出**且** stdio 已关闭」的时点，数据到那时一定已经交出来了。\n   *\n   * **有界**：到点就返回（调用方照当时手里有的写），绝不为等证据把探针拖长。\n   */\n  awaitEvidence(ms: number): Promise<void>\n  /** 收尾：关传输 + 杀子进程（**幂等**；所有 teardown 路径都要调，否则漏一个常驻进程）。 */\n  dispose(): void\n}\n\n/**\n * 杀代理命令（含它拉起的子孙进程）。\n *\n * POSIX 上用 `detached: true` 让子进程自成进程组，`kill(-pid)` 一次收掉整组——代理命令\n * 常见写法是 `ssh -W %h:%p bastion` 这类**又开了一个进程**的命令，只杀 shell 会留下它。\n * 先 SIGTERM，2s 后仍活着再 SIGKILL（兜底定时器 unref，不挡进程退出）。\n */\nfunction killProxyChild(child: ChildProcess): void {\n  const pid = child.pid\n  const kill = (signal: NodeJS.Signals): void => {\n    try {\n      if (pid !== undefined && process.platform !== 'win32') process.kill(-pid, signal)\n      else child.kill(signal)\n    } catch {\n      try {\n        child.kill(signal)\n      } catch {\n        /* 已退出 */\n      }\n    }\n  }\n  kill('SIGTERM')\n  const timer = setTimeout(() => {\n    if (child.exitCode === null && child.signalCode === null) kill('SIGKILL')\n  }, PROXY_KILL_GRACE_MS)\n  timer.unref?.()\n}\n\n/**\n * 启动代理命令并把它接到目标连接上。\n *\n * 这一跳与 `dialJump` 的差别，逐条都有理由：\n *   1. **先过闸门**：关着就直接抛 `PROXY_COMMAND_DISABLED`（不 spawn、不退回直连）；\n *   2. **没有「握手」可等**：传输就是子进程的 stdio，ssh2 会在它上面跑握手——所以这里\n *      spawn 成功即返回，剩下的失败由目标连接的 error/close 路径 + `failure()` 共同呈现；\n *   3. **子进程死了要拖垮传输**：提前退出时 destroy 掉 sock，逼 ssh2 立刻报错（否则\n *      「命令一开始就失败」会伪装成 20s 握手超时）；\n *   4. **stderr 必须排空**：不排空的话命令输出一多就把管道写满、子进程卡死（经典坑），\n *      同时留一小段尾巴进错误文案——它是排查代理命令失败最直接的信息；\n *   5. **命令原文不进日志与错误文案**：它可能含凭据（如 `-i /path/key`），日志只写\n *      「已启动代理命令」与退出码。\n */\nexport async function dialProxyCommand(options: { spec: SshSpec; logger?: SshLogger }): Promise<ProxyCommandDial> {\n  const raw = sanitizeProxyCommand(options.spec.proxyCommand)\n  if (raw === undefined) throw new Error('代理命令为空（proxyCommand 需要一条非空的单行命令）')\n  if (!proxyCommandGranted) throw new Error(PROXY_COMMAND_NOT_GRANTED)\n  if (!proxyCommandEnabled) throw new Error(PROXY_COMMAND_DISABLED)\n  const destination = sshTarget(options.spec)\n  const command = expandProxyCommand(raw, options.spec)\n  const child = spawn(command, {\n    shell: true,\n    stdio: ['pipe', 'pipe', 'pipe'],\n    windowsHide: true,\n    // POSIX：自成进程组，收尾时能一次收掉命令拉起的子孙进程（见 killProxyChild）\n    detached: process.platform !== 'win32',\n  })\n  const stdout = child.stdout\n  const stdin = child.stdin\n  const stderr = child.stderr\n  if (stdout === null || stdin === null || stderr === null) {\n    killProxyChild(child)\n    throw new Error('代理命令启动失败：stdio 管道未建立')\n  }\n  const sock = Duplex.from({ readable: stdout, writable: stdin })\n  let failure: Error | null = null\n  /** 子进程「怎么结束的」（tty D95）：只记事实，文案在 `failure()` 里现拼。 */\n  let exitHow: string | null = null\n  let disposed = false\n  /**\n   * 传输是否已经关掉（子进程的输出结束）。\n   *\n   * 为什么要单独记：子进程**先结束输出、后触发 `exit`**，而 ssh2 一看到流断了就立刻报\n   * 「Connection lost before handshake」——错误文案那一刻 `exit` 还没到。只认 `exit` 的话，\n   * 最需要解释的那种失败（命令一开始就挂）反而拿不到任何解释。于是这里退一步：传输关了\n   * 就至少把**已经攒到的 stderr** 交出去（那正是排查命令失败最直接的信息）。\n   */\n  let transportClosed = false\n  const chunks: Buffer[] = []\n  let kept = 0\n  /** 已攒到的 stderr 摘要（单行、截断；没有则空串）。 */\n  const stderrExcerpt = (): string => {\n    if (chunks.length === 0) return ''\n    const text = Buffer.concat(chunks).toString('utf8').replace(/[\\r\\n\\0]+/g, ' ').replace(/\\s+/g, ' ').trim()\n    return text.slice(0, PROXY_STDERR_SHOWN)\n  }\n  const stderrTail = (): string => {\n    const text = stderrExcerpt()\n    return text === '' ? '' : `；stderr: ${text}`\n  }\n  stderr.on('data', (chunk: Buffer) => {\n    // 常驻排空（不排空会把管道写满、子进程卡死）；只留最后一小段给错误文案\n    if (kept >= PROXY_STDERR_KEEP) return\n    kept += chunk.length\n    chunks.push(chunk)\n  })\n  /** 记下失败事实并拖垮传输（提前退出时让 ssh2 立刻报错，而不是等满 readyTimeout）。 */\n  const recordFailure = (error: Error): void => {\n    // **覆盖**而不是只记第一个：传输关闭往往先触发出一个「语焉不详」的事实，\n    // 随后 exit 事件带来的（退出码 + stderr）严格更有信息量\n    failure = error\n    try {\n      sock.destroy()\n    } catch {\n      /* 已销毁 */\n    }\n  }\n  child.on('error', (error: Error) => {\n    recordFailure(new Error(`代理命令出错：${error.message}`))\n  })\n  /** stdio 全关 = 数据事件已交完；`awaitEvidence` 等的就是它（见 ProxyCommandDial.awaitEvidence）。 */\n  let stdioClosed = false\n  child.once('close', () => {\n    stdioClosed = true\n  })\n  child.on('exit', (code: number | null, signal: NodeJS.Signals | null) => {\n    // 我们自己收尾时杀的（disposed）：不是失败，别把正常关闭记成错误\n    if (disposed) return\n    /*\n     * **只记「怎么结束的」，不在这里拼文案**（tty D95）：`exit` 到达时 stderr 的数据事件\n     * 可能还排在事件循环里（实测 16B 的 stderr 比 exit 晚 100+ms 才交出来），冻在那一刻\n     * 等于把最有用的一句丢掉——`failure()` 每次**现拼**，证据晚到也能带上。\n     */\n    exitHow = signal !== null ? `被信号 ${signal} 终止` : `退出码 ${String(code)}`\n    try {\n      sock.destroy()\n    } catch {\n      /* 已销毁 */\n    }\n  })\n  /**\n   * 子进程创建失败（EACCES / 资源耗尽等）要在**这里**就抛出去：否则调用方拿到的是一条\n   * 「永远连不上」的传输，错误文案会落到目标主机头上。\n   */\n  await new Promise<void>((resolve, reject) => {\n    let settled = false\n    child.once('spawn', () => {\n      if (settled) return\n      settled = true\n      resolve()\n    })\n    child.once('error', (error: Error) => {\n      if (settled) return\n      settled = true\n      reject(new Error(`代理命令启动失败（${excerpt(command)}）：${error.message}`))\n    })\n  })\n  options.logger?.info(`[dsh-tty] ssh ${destination} 已启动代理命令（ProxyCommand）作为传输`)\n  const dispose = (): void => {\n    if (disposed) return\n    disposed = true\n    try {\n      sock.destroy()\n    } catch {\n      /* 已销毁 */\n    }\n    killProxyChild(child)\n  }\n  // 传输先关（对端消失 / ssh2 主动 destroy）时也要杀子进程：否则每次重连漏一个常驻进程\n  /*\n   * **readable 侧 end** 是关键时点：ssh2 就是看到它才判定「握手前连接中断」并发错，\n   * 而子进程的 `exit` 还在后面（实测差 1~2ms）。所以在这里就认定「传输已关」，\n   * 错误路径才能带上已经攒到的 stderr。\n   */\n  sock.once('end', () => {\n    transportClosed = true\n  })\n  sock.once('close', () => {\n    transportClosed = true\n    // 不置 disposed：那是「我们主动收尾」的标记，而这里是传输先没了——子进程该杀，\n    // 但它随后带来的 exit 事实仍要记下来（失败文案靠它）\n    if (!disposed) killProxyChild(child)\n  })\n  /*\n   * 必须挂这个监听器：`Duplex.from({readable, writable})` 销毁时会把 **AbortError**\n   * 抛给底层流，没人接就是进程级的「未捕获异常」（实测：光调 dispose() 就能触发）。\n   * 收尾途中的错误不算失败（disposed 时忽略）；在途的错误记下来，供错误文案点名。\n   */\n  sock.on('error', (error: Error) => {\n    if (disposed) return\n    /*\n     * **AbortError 直接忽略**：它不是一个诊断，而是我们自己 destroy 这条传输时 Duplex 抛给\n     * 底层流的副产品（\"The operation was aborted\"）。把它记成失败原因，用户看到的就会是这句\n     * 毫无信息量的话，而不是「命令退出了、stderr 说了什么」。\n     */\n    if (error.name === 'AbortError' || (error as { code?: string }).code === 'ABORT_ERR') return\n    recordFailure(new Error(`代理命令传输出错：${error.message}`))\n  })\n  return {\n    child,\n    sock,\n    failure: () => {\n      // 「已退出」这条**现拼**：stderr 可能刚刚才到（见 exit 处理里的 D95 注释）\n      if (exitHow !== null) return new Error(`代理命令已退出（${exitHow}）${stderrTail()}`)\n      if (failure !== null) return failure\n      // 主动收尾之后不算失败；传输自己关了且还没有 exit 事实时，先把 stderr 尾巴交出去\n      if (disposed || !transportClosed) return null\n      const tail = stderrTail()\n      return new Error(`代理命令传输已关闭${tail === '' ? '（命令已结束）' : tail}`)\n    },\n    stderrHint: () => {\n      // 主动收尾之后不再提示（那是正常结束，不是线索）；没有 stderr 也不提示\n      if (disposed) return ''\n      const text = stderrExcerpt()\n      return text === '' ? '' : `；代理命令 stderr: ${text}`\n    },\n    awaitEvidence: (ms: number) =>\n      new Promise<void>((resolve) => {\n        // 已经排空（或本来就关着）→ 立即返回；调用方因此不会为「没证据可等」付延迟\n        if (stdioClosed) {\n          resolve()\n          return\n        }\n        let done = false\n        const finish = (): void => {\n          if (done) return\n          done = true\n          clearTimeout(timer)\n          child.off('close', finish)\n          resolve()\n        }\n        // 到点就走：等不到证据也不能把探针拖长（调用方照当时手里有的写）\n        const timer = setTimeout(finish, ms)\n        timer.unref?.()\n        child.once('close', finish)\n      }),\n    dispose,\n  }\n}\n\n/**\n * 清洗一份跳板机输入（settings schema / 宽松清洗 / 内联融合共用）。\n *\n * 返回 `undefined` = **没有可用的跳板机**（`host` 为空）——调用方据此把 `jump` 整个丢掉，\n * 而不是留下一个 `host: ''` 的半个对象（那会让 `dialJump` 去连空主机名）。\n * 缺省不填的字段**不写进结果**：它们要在拨号时「继承目标那一跳」（见 `jumpSpecOf`）。\n */\nexport function sanitizeJumpSpec(input: unknown): SshJumpSpec | undefined {\n  if (typeof input !== 'object' || input === null) return undefined\n  const raw = input as Record<string, unknown>\n  const host = typeof raw.host === 'string' ? raw.host.trim() : ''\n  if (host === '') return undefined\n  const port = Number(raw.port)\n  const jump: SshJumpSpec = { host, port: Number.isInteger(port) && port >= 1 && port <= 65535 ? port : 22 }\n  if (typeof raw.username === 'string' && raw.username.trim() !== '') jump.username = raw.username.trim()\n  if (raw.auth === 'agent' || raw.auth === 'key' || raw.auth === 'password') jump.auth = raw.auth\n  if (typeof raw.keyPath === 'string' && raw.keyPath !== '') jump.keyPath = raw.keyPath\n  if (typeof raw.passphrase === 'string' && raw.passphrase !== '') jump.passphrase = raw.passphrase\n  if (typeof raw.password === 'string' && raw.password !== '') jump.password = raw.password\n  return jump\n}\n\n/** 严格校验一份跳板机输入（HTTP POST 路径）；返回错误信息或清洗结果。 */\nexport function validateJumpSpec(input: unknown): { jump?: SshJumpSpec; error?: string } {\n  if (typeof input !== 'object' || input === null) return { error: 'jump 必须是对象' }\n  const raw = input as Record<string, unknown>\n  if (typeof raw.host !== 'string' || raw.host.trim() === '') return { error: 'jump.host 必须是非空字符串' }\n  if (raw.port !== undefined && raw.port !== '') {\n    const port = Number(raw.port)\n    if (!Number.isInteger(port) || port < 1 || port > 65535) return { error: 'jump.port 必须是 1~65535 的整数' }\n  }\n  if (raw.username !== undefined && typeof raw.username !== 'string') return { error: 'jump.username 必须是字符串' }\n  if (raw.auth !== undefined && raw.auth !== 'agent' && raw.auth !== 'key' && raw.auth !== 'password') {\n    return { error: 'jump.auth 必须是 agent / key / password' }\n  }\n  for (const key of ['keyPath', 'passphrase', 'password'] as const) {\n    if (raw[key] !== undefined && typeof raw[key] !== 'string') return { error: `jump.${key} 必须是字符串` }\n  }\n  if (raw.auth === 'key' && (typeof raw.keyPath !== 'string' || raw.keyPath.trim() === '')) {\n    return { error: 'jump.auth=key 需要 jump.keyPath' }\n  }\n  return { jump: sanitizeJumpSpec(raw) }\n}\n\n/** 目标连接的传输来源（两者互斥：`jump` 优先，见 `attachSshTransport`）。 */\nexport interface SshTransport {\n  /** 需要跳板机时非 null；**调用方必须在收尾时 `end()` 它**（目标只是借用它的通道）。 */\n  bastion: Client | null\n  /** 需要代理命令时非 null；**调用方必须在收尾时 `dispose()` 它**（目标只是借用它的 stdio）。 */\n  proxy: ProxyCommandDial | null\n}\n\n/** 建连前准备的结果：目标 config（可能挂了跳板机通道 / 代理命令传输）+ 目标那一跳的 TOFU 策略。 */\nexport interface PreparedSshConnect {\n  connectConfig: ConnectConfig\n  policy: { mismatchMessage(): string | null }\n  /** 需要跳板机时非 null；**调用方必须在收尾时 `end()` 它**（目标只是借用它的通道）。 */\n  bastion: Client | null\n  /** 需要代理命令时非 null；**调用方必须在收尾时 `dispose()` 它**（目标只是借用它的 stdio）。 */\n  proxy: ProxyCommandDial | null\n  /** 展示串：带「经跳板机 X」后缀，错误文案直接用。 */\n  target: string\n}\n\n/**\n * 代理命令失败的事实 → 错误文案后缀（空串 = 没失败）。\n *\n * 为什么要它：代理命令死了之后 ssh2 只会报一句「握手前连接中断」，那会把用户支到目标主机上\n * 去查。调用方在错误分支拼上这句，用户才知道是该去看代理命令的 stderr。\n */\nexport function proxyFailureSuffix(proxy: ProxyCommandDial | null): string {\n  if (proxy === null) return ''\n  const failure = proxy.failure()\n  if (failure !== null) return `；${failure.message}`\n  /*\n   * 兜底：调用方**已经在报错**了，但「子进程退出 / 传输关闭」还没到（真机验收实测 1~2ms 的\n   * 竞态：ssh2 一看到流断就报错）。这时候手里有 stderr 就交出去——否则用户拿到的是一句\n   * 「连接已关闭」这种毫无线索的话，还得自己去猜代理命令有没有跑起来。\n   */\n  return proxy.stderrHint()\n}\n\n/**\n * 四个连接点（终端 / SFTP / 隧道 / 探针）**共用**的建连前准备。\n *\n * 为什么要有这个函数：跳板机不是「终端的特性」——SFTP、端口转发、探针各自都在建 SSH 连接\n * （`sftp.ts` / `tunnels.ts` / `probe.ts` 各有一处 `new Client()`）。把「构造 config →\n * 需要时拨跳板机 / 起代理命令 → 接上传输 → 装目标 TOFU 策略」收成一处，四条路才不会各写一份\n * （那正是这一项立项时点名的「三处各写一份必然漂」）。\n *\n * **调用方负责**：自己 `conn.connect(connectConfig)`、自己处理 ready/error/close，\n * 并在收尾（成功或失败）时对 `bastion` 调 `end()`、对 `proxy` 调 `dispose()`。\n */\nexport async function prepareSshConnect(options: {\n  spec: SshSpec\n  store?: HostKeyStore\n  logger?: SshLogger\n  /** 覆盖两跳的握手超时（探针路径要短） */\n  readyTimeoutMs?: number\n}): Promise<PreparedSshConnect> {\n  const { spec, store, logger } = options\n  const target = targetWithJump(spec)\n  const attached = await attachSshTransport(options)\n  try {\n    const policy = applyHostKeyPolicy({ connectConfig: attached.connectConfig, spec, store, logger, target })\n    return { connectConfig: attached.connectConfig, policy, bastion: attached.transport.bastion, proxy: attached.transport.proxy, target }\n  } catch (error) {\n    // 传输已经起来了、策略却装不上：这里必须自己收尾，否则漏一条连接 / 一个进程\n    try {\n      attached.transport.bastion?.end()\n    } catch {\n      /* 已断开 */\n    }\n    attached.transport.proxy?.dispose()\n    throw error\n  }\n}\n\n/**\n * 只做「构造目标 config（需要时拨跳板机 / 起代理命令并把传输接上）」这一半。\n *\n * 拆出来的唯一理由：**探针自己装 hostVerifier**（`makeHostKeyVerifier` 要收集\n * hostkey 结论，不用 `applyHostKeyPolicy`），但它同样需要跳板机 / 代理命令。返回值里的\n * `transport` 由调用方负责收尾。\n */\nexport async function attachSshTransport(options: {\n  spec: SshSpec\n  store?: HostKeyStore\n  logger?: SshLogger\n  readyTimeoutMs?: number\n}): Promise<{ connectConfig: ConnectConfig; transport: SshTransport }> {\n  const { spec, store, logger } = options\n  const connectConfig = await buildConnectConfig(spec)\n  if (options.readyTimeoutMs !== undefined) connectConfig.readyTimeout = options.readyTimeoutMs\n  /*\n   * 跳板机判据走 `usableJump()`，不是 `spec.jump !== undefined`：\n   * 「没配」可能是 `undefined`，也可能是配置层物化出来的**没有 host 的半个对象**。\n   * 后者若按「有跳板机」处理，就会去拨一个空主机名（0.33.0 更早：先在 `jumpTargetLabel`\n   * 里抛 TypeError）。这里把它当「没配」并 **warn**——不静默，否则用户以为自己走的是跳板机。\n   */\n  const jump = usableJump(spec)\n  if (spec.jump !== undefined && jump === undefined) {\n    logger?.warn(`[dsh-tty] ssh ${sshTarget(spec)} 的跳板机配置缺少 host（jump.host 为空）——本次按直连处理；请在 设置 → 插件 → 终端面板 的连接簿里重新填写跳板机`)\n  }\n  const hasJump = jump !== undefined\n  const proxyCommand = sanitizeProxyCommand(spec.proxyCommand)\n  if (hasJump && proxyCommand !== undefined) {\n    // OpenSSH 语义：两者互斥、ProxyJump 优先。**不静默**——用户以为走的是代理命令是最坏情况\n    logger?.warn(`[dsh-tty] ssh ${sshTarget(spec)} 同时配了跳板机与代理命令：按 OpenSSH 语义走跳板机（ProxyJump 优先），代理命令被忽略`)\n  }\n  if (hasJump) {\n    const dialed = await dialJump({ spec, store, logger, readyTimeoutMs: options.readyTimeoutMs })\n    connectConfig.sock = dialed.sock\n    return { connectConfig, transport: { bastion: dialed.bastion, proxy: null } }\n  }\n  if (proxyCommand !== undefined) {\n    const dialed = await dialProxyCommand({ spec, logger })\n    connectConfig.sock = dialed.sock\n    return { connectConfig, transport: { bastion: null, proxy: dialed } }\n  }\n  return { connectConfig, transport: { bastion: null, proxy: null } }\n}\n\n/**\n * 建立 SSH 连接并打开交互 shell channel，返回 TermHandle。\n * 失败（连接超时/认证被拒/host 不可达）时 reject 带人类可读信息。\n */\nexport async function spawnSsh(spec: SshSpec, options: SshSpawnOptions): Promise<TermHandle> {\n  const target = sshTarget(spec)\n  const logger = options.logger\n  // agent forwarding 预检：缺 SSH_AUTH_SOCK 时 ssh2 只会静默不转发，这里显式报错\n  if (spec.agentForward === true && (process.env.SSH_AUTH_SOCK === undefined || process.env.SSH_AUTH_SOCK === '')) {\n    throw new Error('agent forwarding 需要 SSH_AUTH_SOCK（本机未运行 ssh-agent 或变量未设置）')\n  }\n  const conn = new Client()\n  /** 跳板机连接（ProxyJump）：它拥有目标借用的通道，收尾时必须由本函数 end 掉。 */\n  let bastion: Client | null = null\n  /** 代理命令（ProxyCommand）：它拥有目标借用的传输，收尾时必须由本函数 dispose 掉。 */\n  let proxy: ProxyCommandDial | null = null\n  const output = new PassThrough()\n\n  let exitCode: number | null = null\n  let exitSignal: string | null = null\n  let settleDone!: (outcome: TermExit) => void\n  const done = new Promise<TermExit>((resolve) => {\n    settleDone = resolve\n  })\n  let finished = false\n  const finish = (): void => {\n    if (finished) return\n    finished = true\n    try {\n      output.end()\n    } catch {\n      /* 已结束 */\n    }\n    try {\n      conn.end()\n    } catch {\n      /* 已断开 */\n    }\n    // 跳板机**最后**关：顺序反了会在目标还活着时抽掉它借用的通道\n    if (bastion !== null) {\n      try {\n        bastion.end()\n      } catch {\n        /* 已断开 */\n      }\n    }\n    // 代理命令同样最后收：先关目标连接再杀子进程，写进子进程的最后一个字节才有机会被读到\n    proxy?.dispose()\n    settleDone({ exitCode, signal: exitSignal })\n  }\n\n  // 认证配置可能抛错（keyPath 读不到 / 引用解析不到）——先构造再连\n  /*\n   * 建连前准备（含跳板机 / 代理命令）：拨号失败/超时都在 dialJump / dialProxyCommand 里\n   * 点名那一跳并自我清理；成功之后它们的生死由本函数的 finish() 一并负责\n   * （目标先关、跳板机与代理命令后关）。\n   */\n  const prepared = await prepareSshConnect({ spec, store: options.hostKeyStore, logger })\n  const connectConfig = prepared.connectConfig\n  const policy = prepared.policy\n  bastion = prepared.bastion\n  proxy = prepared.proxy\n\n  /** 持久会话：远程 tmux 探测/降级提示（spawn 后由调用方注入终端）。 */\n  let startupNotice: string | undefined\n  let tmuxUsed = false\n\n  const channel = await new Promise<ClientChannel>((resolve, reject) => {\n    let settled = false\n    let watchdog: NodeJS.Timeout | null = null\n    const clearWatchdog = (): void => {\n      if (watchdog !== null) {\n        clearTimeout(watchdog)\n        watchdog = null\n      }\n    }\n    // channel 打开兜底（0.19.0）：readyTimeout 只覆盖到认证成功；对端不响应\n    // channel-open（堡垒机 / sshd 限制并发 channel）时 await 永不 settle——\n    // 连接活着、keepalive 正常，用户端「Connecting …」常驻且拿不到 handle\n    // 去取消。每个 channel 尝试挂 15s 计时（与 tmux 探测的 10s 同思路），\n    // 超时断开连接并明确报错。\n    const armWatchdog = (what: string): void => {\n      clearWatchdog()\n      watchdog = setTimeout(() => {\n        if (settled) return\n        settled = true\n        try {\n          conn.end()\n        } catch {\n          /* 已断开 */\n        }\n        reject(new Error(`SSH channel 打开超时（${what}15s 无响应）：对端可能限制了并发 channel 数或不响应，连接已断开`))\n      }, 15_000)\n      watchdog.unref?.()\n    }\n    const settleOk = (ch: ClientChannel): void => {\n      if (settled) return\n      settled = true\n      clearWatchdog()\n      resolve(ch)\n    }\n    const settleErr = (error: Error): void => {\n      if (settled) return\n      settled = true\n      clearWatchdog()\n      reject(error)\n    }\n    const openShell = (): void => {\n      armWatchdog('shell channel ')\n      // agentForward 走 per-channel 请求（@types/ssh2 的 ShellOptions 未声明，\n      // 运行时支持；仅在本机 agent 存在时生效，见 buildConnectConfig）\n      conn.shell(\n        { term: options.term, cols: options.cols, rows: options.rows, agentForward: spec.agentForward === true } as ShellOptionsWithAgentForward,\n        (error, ch) => {\n          if (error !== undefined && error !== null) {\n            conn.end()\n            settleErr(new Error(`shell channel 打开失败: ${error.message}`