*，补探一次再判——原先这几种一律按「未安装」降级，把远端忙\n      // 或链路慢说成了确定结论，用户显式要的持久化就此被瞬时状况关掉。\n      let proceeded = false\n      let rounds = 0\n      /**\n       * 探测世代号（D82 复查）：补探会**再开一条 channel**，而旧 channel 的 listener\n       * 不摘——它迟到的 `close` / `exit` 会替新一轮结算，白耗一轮补探（补探只要一次时，\n       * 更会把还在飞的那次探测直接判成降级，正好抵消 D82 要修的东西）。每轮领一个号，\n       * 事件回调先对号：不是当前世代就丢掉。\n       */\n      let generation = 0\n      /** 本轮探测的兜底计时器：结算时清掉，免得上一轮的 10s 计时器误判下一轮。 */\n      let timer: ReturnType<typeof setTimeout> | undefined\n      const clearTimer = (): void => {\n        if (timer !== undefined) {\n          clearTimeout(timer)\n          timer = undefined\n        }\n      }\n      /** 收尾降级：调用方负责 proceeded 守卫（这里只做「清计时器 + 提示 + 开 shell」）。 */\n      const fallback = (notice: string): void => {\n        clearTimer()\n        startupNotice = notice\n        openShell()\n      }\n      const settle = (code: number | null): void => {\n        if (proceeded) return\n        if (code === 0) {\n          proceeded = true\n          clearTimer()\n          openTmux()\n          return\n        }\n        if (code === null && rounds < REMOTE_TMUX_PROBE_ROUNDS) {\n          rounds += 1\n          clearTimer()\n          probe()\n          return\n        }\n        proceeded = true\n        fallback(code === null\n          ? '远程 tmux 探测超时（远端较忙或链路慢），本次以普通会话连接；重连一次即可再试持久化'\n          : '远程 tmux 不可用（未安装），本次以普通会话连接；安装 tmux 后持久会话可跨断线/宿主重启恢复')\n      }\n      const probe = (): void => {\n        const mine = ++generation\n        /** 只让**当前世代**的事件参与结算；旧 channel 的迟到事件直接丢掉。 */\n        const settleRound = (code: number | null): void => {\n          if (mine !== generation) return\n          settle(code)\n        }\n        conn.exec('command -v tmux >/dev/null 2>&1', (error, stream) => {\n          if (error !== undefined && error !== null) {\n            // channel 都打不开（远端并发上限 / 瞬态拒绝）同样属「没探明白」\n            settleRound(null)\n            return\n          }\n          stream.on('exit', (c: number | null) => { settleRound(typeof c === 'number' ? c : null) })\n          // 只有 close、没有 exit（个别 sshd 实现）：同样是「没探明白」，不是「没有 tmux」\n          stream.on('close', () => { settleRound(null) })\n          stream.on('error', () => { settleRound(null) })\n          timer = setTimeout(() => { settleRound(null) }, REMOTE_TMUX_PROBE_TIMEOUT_MS)\n          timer.unref?.()\n        })\n      }\n      probe()\n    }\n    conn.on('ready', () => {\n      // 命令标签（0.14.0）优先：不做 tmux 持久化（命令短命，attach 没意义）\n      if (options.command !== undefined && options.command !== '') openCommand()\n      else if (options.persist !== undefined) openWithPersist()\n      else openShell()\n    })\n    conn.on('error', (error) => {\n      if (!settled) {\n        const mismatch = policy.mismatchMessage()\n        if (mismatch !== null) settleErr(new Error(mismatch))\n        else settleErr(new Error(`SSH 连接失败（${targetWithJump(spec)}）: ${classifyError(error.message)}${proxyFailureSuffix(proxy)}`))\n      } else {\n        logger?.warn(`[dsh-tty] ssh ${target} 连接错误: ${error.message}`)\n        finish()\n      }\n    })\n    conn.on('close', () => {\n      // channel 建立前连接就断了：不能让 await 悬挂（0.19.0 兜底）\n      settleErr(new Error(`SSH 连接已关闭（${targetWithJump(spec)}，channel 未建立）${proxyFailureSuffix(proxy)}`))\n      finish()\n    })\n    if ((connectConfig as { tryKeyboard?: boolean }).tryKeyboard === true) {\n      const password = (connectConfig as { password?: string }).password ?? ''\n      conn.on('keyboard-interactive', (_name, _instructions, _lang, _prompts, finishKb) => {\n        finishKb([password])\n      })\n    }\n    try {\n      conn.connect(connectConfig)\n    } catch (error) {\n      settleErr(error instanceof Error ? error : new Error(String(error)))\n    }\n  })\n\n  channel.on('data', (chunk: Buffer) => {\n    output.write(chunk)\n  })\n  channel.stderr.on('data', (chunk: Buffer) => {\n    output.write(chunk)\n  })\n  channel.on('exit', (code: number | null, signal?: string | null) => {\n    exitCode = typeof code === 'number' ? code : null\n    exitSignal = typeof signal === 'string' ? signal : null\n  })\n  channel.on('close', () => {\n    finish()\n  })\n\n  // 持久会话的重画（0.10.1 跨窗口共享）：远程 list-clients + 逐个\n  // refresh-client 一条 exec 管道完成；resolve 时机 = 远程命令跑完\n  const tmuxRefresh =\n    tmuxUsed && options.persist !== undefined\n      ? (): Promise<void> =>\n          new Promise<void>((resolve) => {\n            const cmd =\n              `tmux -L ${tmuxSocketName()} list-clients -t ${shSingleQuote(options.persist?.name ?? '')} -F '#{client_name}' | ` +\n              `while IFS= read -r c; do tmux -L ${tmuxSocketName()} refresh-client -t \"$c\"; done`\n            try {\n              conn.exec(cmd, (error, stream) => {\n                if (error !== undefined && error !== null) {\n                  resolve()\n                  return\n                }\n                stream.on('close', () => resolve())\n                stream.on('error', () => resolve())\n              })\n            } catch {\n              resolve()\n            }\n          })\n      : undefined\n\n  // 持久会话的关闭收尾：kill-session 须在连接还活着时发出（连接随 channel\n  // 关闭而断开）；resolve 时机 = 远程命令跑完（stream close），调用方另有\n  // 2.5s 兜底 forceKill 防悬挂\n  const tmuxTeardown =\n    tmuxUsed && options.persist !== undefined\n      ? (): Promise<void> =>\n          new Promise<void>((resolve) => {\n            try {\n              conn.exec(`tmux -L ${tmuxSocketName()} kill-session -t ${shSingleQuote(options.persist?.name ?? '')}`, (error, stream) => {\n                if (error !== undefined && error !== null) {\n                  resolve()\n                  return\n                }\n                stream.on('close', () => resolve())\n                stream.on('error', () => resolve())\n              })\n            } catch {\n              resolve()\n            }\n          })\n      : undefined\n\n  // 背压透传：TtyServer 暂停 PassThrough 时一并暂停上游 channel，\n  // 避免高速输出（cat 大文件）在 Node 侧无界堆积\n  const nativePause = output.pause.bind(output)\n  output.pause = () => {\n    try {\n      channel.pause()\n    } catch {\n      /* channel 已关闭 */\n    }\n    return nativePause()\n  }\n  const nativeResume = output.resume.bind(output)\n  output.resume = () => {\n    try {\n      channel.resume()\n    } catch {\n      /* channel 已关闭 */\n    }\n    return nativeResume()\n  }\n\n  logger?.info(`[dsh-tty] ssh 会话就绪: ${target}${tmuxUsed ? '（tmux 持久）' : ''}`)\n  /**\n   * 服务器状态条（0.17.0）：同一条连接上的**独立** exec channel（不碰 PTY\n   * 那条）。stderr 必须消费掉——未读的 channel 数据会把远端发送窗口堵住，\n   * 采集脚本会卡在写 stdout 上；诊断内容不受我们控制，一律不进任何日志。\n   */\n  const statsExec = (command: string, onLine: (line: string) => void, onError: () => void): { stop(): void } => {\n    let stopped = false\n    let open: ClientChannel | null = null\n    const lines = new StatsLineBuffer()\n    const decoder = new StringDecoder('utf8')\n    try {\n      conn.exec(command, (error, ch) => {\n        // stop() 可能在 channel 打开前就被调用（订阅瞬断）：开了就立刻关掉\n        if (stopped) {\n          try {\n            ch.close()\n          } catch {\n            /* 已关闭 */\n          }\n          return\n        }\n        if (error !== null && error !== undefined) {\n          onError()\n          return\n        }\n        open = ch\n        ch.on('data', (chunk: Buffer) => {\n          for (const line of lines.push(decoder.write(chunk))) onLine(line)\n        })\n        ch.stderr.on('data', () => {\n          /* 丢弃：远端脚本自身的报错不进任何日志（防凭证/路径意外落到日志里） */\n        })\n        ch.on('close', () => {\n          // 主动 stop() 之外的关闭 = 采集进程自己结束（远端无 /proc、被 kill）\n          if (!stopped) onError()\n        })\n        ch.on('error', () => {\n          if (!stopped) onError()\n        })\n      })\n    } catch {\n      onError()\n    }\n    return {\n      stop: () => {\n        stopped = true\n        try {\n          open?.close()\n        } catch {\n          /* 已关闭 */\n        }\n      },\n    }\n  }\n\n  /**\n   * 连接往返的一次采样（见 `TermHandle.probeRtt` 的说明）。失败一律返回 null：\n   * 探针是附加信息，量不到就不报，绝不因为一次 exec 被拒而影响终端或采集。\n   */\n  const probeRtt = (): Promise<number | null> => new Promise((resolve) => {\n    let settled = false\n    const timer = setTimeout(() => {\n      if (settled) return\n      settled = true\n      resolve(null)\n    }, PROBE_RTT_TIMEOUT_MS)\n    timer.unref?.()\n    const started = performance.now()\n    try {\n      conn.exec('true', (error, ch) => {\n        if (settled) return\n        settled = true\n        clearTimeout(timer)\n        if (error !== null && error !== undefined) {\n          resolve(null)\n          return\n        }\n        // channel 一确认就关：`true` 在远端自己会退出，我们不需要它的输出\n        try {\n          ch.close()\n        } catch {\n          /* 已关闭 */\n        }\n        resolve(Math.round(performance.now() - started))\n      })\n    } catch {\n      if (!settled) {\n        settled = true\n        clearTimeout(timer)\n      }\n      resolve(null)\n    }\n  })\n\n  return {\n    kind: 'ssh',\n    pid: null,\n    output,\n    done,\n    probeRtt,\n    write: (data: string) => {\n      channel.write(data)\n      return Promise.resolve(true)\n    },\n    resize: (cols: number, rows: number) => {\n      try {\n        channel.setWindow(rows, cols, 0, 0)\n      } catch {\n        /* channel 已关闭 */\n      }\n    },\n    terminate: () => {\n      try {\n        channel.close()\n      } catch {\n        /* 已关闭 */\n      }\n      finish()\n      return Promise.resolve(true)\n    },\n    statsExec,\n    ...(tmuxTeardown !== undefined ? { tmuxTeardown } : {}),\n    ...(tmuxRefresh !== undefined ? { tmuxRefresh } : {}),\n    ...(startupNotice !== undefined ? { startupNotice } : {}),\n  }\n}\n"
