      "path": "packages/tty/src/assist.ts",
      "content": "/**\n * 「失败即解释」的上下文包（0.24.0）。\n *\n * 这一层的职责只有一个：把终端现场压成**模型读得懂、又淹不掉它**的一小段文本。\n * 它是这个功能真正的工程主体——`ctx.llm.stream` 那条路 rss 已经走通（连 finish 块的\n * 形状、reasoning 模型的 max-tokens 拐点都有注释留档），难的是**喂什么进去**：\n * 终端输出里全是 ANSI、\\r 覆盖行、进度条刷屏与重复日志，直接丢给模型就是垃圾进垃圾出。\n *\n * 全部导出都是**纯函数**（不碰 ctx、不碰会话对象）——这是整个功能里唯一能被确定性\n * 测住的部分，所以逻辑尽量往这里收。\n */\nimport { cleanAnsi } from './ansi.js'\n\n/** 命令输出尾部保留行数。 */\nexport const CONTEXT_TAIL_LINES = 40\n/** 上下文正文的字符上限（超出从头部丢弃，并注明丢了多少行）。 */\nexport const CONTEXT_MAX_CHARS = 6000\n/** 屏幕文本的行数上限（只在「没有命令输出」时才用屏幕兜底）。 */\nexport const SCREEN_TAIL_LINES = 30\n\n/**\n * 这个退出码值不值得摆徽标。\n *\n * 0 不弹；`null` / `undefined`（没拿到退出码 = 命令边界不可信）也不弹——\n * 宁可少弹一次，也不要在正常的提示符下摆一张「它失败了」的脸。\n *\n * **130 / 141 是刻意豁免的**：前者是 Ctrl-C（用户自己按的），后者是 SIGPIPE\n * （`… | head` 的常态）。这两个天天出现，为它们弹徽标会让用户干脆把整个功能关掉。\n */\nexport function shouldExplainExit(code: number | null | undefined): boolean {\n  if (code === null || code === undefined) return false\n  if (code === 0) return false\n  return code !== 130 && code !== 141\n}\n\n/**\n * 外发前的轻量遮盖。\n *\n * 这不是「防住攻击者」，而是**兜住常识**：终端屏幕上出现密钥、token、连接串是家常便饭，\n * 而这一段文本要离开本机。成本极低，但它决定了这个开关该怎么向用户交代。\n *\n * 只做**形态明确**的规则——宁可漏，不可错杀：把一段正常日志改成 [已遮盖] 比漏掉一个\n * 罕见格式的密钥更伤信任（用户会以为功能坏了）。\n */\nconst SECRET_RULES: Array<{ re: RegExp; to: string; why: string }> = [\n  { re: /-----BEGIN [A-Z ]*PRIVATE KEY-----[\\s\\S]*?-----END [A-Z ]*PRIVATE KEY-----/g, to: '[已遮盖私钥]', why: 'PEM 私钥块' },\n  { re: /\\bsk-[A-Za-z0-9_-]{8,}/g, to: 'sk-[已遮盖]', why: 'OpenAI 风格密钥' },\n  { re: /\\bAKIA[0-9A-Z]{16}\\b/g, to: 'AKIA[已遮盖]', why: 'AWS access key id' },\n  { re: /\\bgh[pousr]_[A-Za-z0-9]{20,}/g, to: 'gh_[已遮盖]', why: 'GitHub token' },\n  { re: /\\beyJ[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}\\.[A-Za-z0-9_-]{8,}/g, to: '[已遮盖 JWT]', why: 'JWT' },\n  { re: /(\\/\\/[^/\\s:@]+):[^/\\s:@]+@/g, to: '$1:[已遮盖]@', why: 'URL 里的密码' },\n  {\n    re: /((?:password|passwd|pwd|secret|token|api[_-]?key|access[_-]?key|authorization|密码)\\s*[:=]\\s*)([^\\s'\"]{3,})/gi,\n    to: '$1[已遮盖]',\n    why: '键值对里的秘密',\n  },\n]\n\n/** 规则表只读导出，供单测逐条枚举（新加一条规则必须同时加一条用例）。 */\nexport const SECRET_RULE_WHY: readonly string[] = SECRET_RULES.map((rule) => rule.why)\n\nexport function maskSecrets(text: string): { text: string; count: number } {\n  let out = text\n  let count = 0\n  for (const rule of SECRET_RULES) {\n    out = out.replace(rule.re, (...args: unknown[]) => {\n      count += 1\n      // 手写 $1 展开：用了回调就不能再靠 String.replace 的替换串语法\n      return rule.to.replace(/\\$(\\d)/g, (_m, d: string) => String(args[Number(d)] ?? ''))\n    })\n  }\n  return { text: out, count }\n}\n\n/**\n * 把一段终端输出压成上下文正文。\n *\n * 四步，每一步都对应一种真实的噪声：\n *   1. 剥转义（颜色/光标/进度条转义）——不剥的话模型看到的是满屏控制码；\n *   2. \\r 覆盖收敛——`npm install` 那一类会把同一行重画几百次；\n *   3. 折掉连续空行与**连续重复行**——重复日志（同一句 warning 刷 50 遍）是纯浪费预算；\n *   4. 取尾部并按字符上限硬切——报错在末尾，且开头半行要丢掉（半行命令比没有更误导）。\n *\n * 头部被丢弃时**显式注明行数**：否则模型会把「输出第一行就是报错」当成事实。\n */\nexport function compressTerminalText(raw: string, options?: { maxLines?: number; maxChars?: number }): string {\n  const maxLines = options?.maxLines ?? CONTEXT_TAIL_LINES\n  const maxChars = options?.maxChars ?? CONTEXT_MAX_CHARS\n  const lines = cleanAnsi(raw).split('\\n').map((line) => line.replace(/[ \\t]+$/, ''))\n  const kept: string[] = []\n  for (const line of lines) {\n    const prev = kept[kept.length - 1]\n    if (line === '') {\n      if (prev === '' || prev === undefined) continue\n    } else if (line === prev) {\n      continue\n    }\n    kept.push(line)\n  }\n  while (kept.length > 0 && kept[kept.length - 1] === '') kept.pop()\n  const joined = kept.join('\\n')\n  let text = joined\n  let byChars = false\n  if (joined.length > maxChars) {\n    text = joined.slice(-maxChars)\n    const nl = text.indexOf('\\n')\n    // 从一个整行开始，别把一行切成半截（半截命令会让模型编出后半段）\n    text = nl === -1 ? text : text.slice(nl + 1)\n    byChars = true\n  }\n  if (!byChars && kept.length > maxLines) {\n    text = kept.slice(-maxLines).join('\\n')\n  }\n  const shown = text === '' ? 0 : text.split('\\n').length\n  const omitted = kept.length - shown\n  return omitted > 0 ? '…（前面 ' + String(omitted) + ' 行已省略）\\n' + text : text\n}\n\n/**\n * 从模型答案里取出**一条**可直接填入的命令行。\n *\n * 只认**围栏代码块**：没有围栏就返回空串（客户端据此禁用「填入」）。刻意不去散文里\n * 猜哪一行像命令——猜错的下场是往用户的 PTY 里写进一句解释文字，比不给按钮糟得多。\n */\nexport function extractCommandFromAnswer(answer: string): string {\n  const fence = /```[A-Za-z0-9_-]*\\n([\\s\\S]*?)```/.exec(answer)\n  if (fence === null) return ''\n  for (const raw of fence[1].split('\\n')) {\n    const line = raw.trim()\n    /*\n     * 注释行**先判**。`#` 既是注释符、又是 root 提示符：反过来先剥提示符的话\n     * 「# 先看看包名」会被当成一条命令填进终端（这个坑是单测当场抓出来的——\n     * 见 test/assist-context.test.ts 的「围栏里只有空行/注释也是空串」）。\n     * 代价是 root 会话里 `# cmd` 形态的首行取不到，而系统提示本来就要求不要 $ 前缀。\n     */\n    if (line === '' || line.startsWith('#')) continue\n    return line.replace(/^[$>]\\s+/, '')\n  }\n  return ''\n}\n\n/**\n * 把模型答案变成**界面正文用的纯文本**。\n *\n * 只做「去掉标记」，**不做「解释标记」**——模型输出是不可信文本，任何 Markdown 渲染都是\n * 一条新攻击面；而原样显示又满屏是星号与围栏。所以折中成两条纯删减：\n *   - 丢掉围栏代码块：命令另有一行 `.tt_assistCmd` 专门展示（还带「填入」按钮），\n *     正文里再来一遍是重复；\n *   - 去掉 `**` 强调标记。\n * 顺带折掉连续空行（丢掉围栏后常留下整块空白）。\n */\nexport function plainAnswerText(answer: string): string {\n  const withoutFence = answer.replace(/```[A-Za-z0-9_-]*\\n[\\s\\S]*?```/g, '').replace(/```[A-Za-z0-9_-]*/g, '')\n  const kept: string[] = []\n  for (const raw of withoutFence.split('\\n')) {\n    const line = raw.replace(/\\*\\*/g, '').replace(/[ \\t]+$/, '')\n    if (line === '' && (kept.length === 0 || kept[kept.length - 1] === '')) continue\n    kept.push(line)\n  }\n  while (kept.length > 0 && kept[kept.length - 1] === '') kept.pop()\n  return kept.join('\\n')\n}\n\n/** 上下文包输入（宿主侧从会话状态取材，见 index.ts 的 buildAssistContext）。 */\nexport interface AssistPromptInput {\n  shell: string\n  cwd: string\n  /** 上一条已完成命令的命令行（拿不到时省略）。 */\n  command?: string\n  exitCode?: number | null\n  /** 上一条命令的输出（B..D 捕获窗口，未压缩）。 */\n  output?: string\n  /** 当前屏纯文本（tty_screen 产物）；只在没有命令输出时兜底。 */\n  screen?: string\n  /** 界面语言；模型据此决定用中文还是英文作答。 */\n  lang?: 'zh' | 'en'\n}\n\n/**\n * 系统提示。\n *\n * 三条硬约束写进去的原因：\n *   - **固定两节标题**：界面按节渲染，多出来的前言/总结只是噪声；\n *   - **命令放进围栏且每条一行**：客户端的「填入」按钮就是从围栏里取第一条\n *     （extractCommandFromAnswer），格式漂了这个按钮就哑了；\n *   - **不要编造路径/IP、拿不准就给一条查证命令**：终端里照着模型编的路径敲下去，\n *     比不回答更糟。\n */\nconst SYSTEM_ZH = [\n  '你是终端里的排错助手。用户刚在终端里跑了一条命令、它以非零状态结束（或屏幕上出现了报错）。',\n  '用最短的篇幅说清两件事：出了什么事、下一步该敲什么。',\n  '',\n  '输出格式（严格遵守，**纯文本**，界面不渲染 Markdown）：',\n  '第一行就以「发生了什么：」开头，一到两句，说人话。不要复述输出、不要贴日志原文。',\n  '空一行后写「下一步：」，紧接一个 SH 围栏代码块（三个反引号 + sh），里面放一到两条可以直接粘贴执行的命令，每条命令单独一行，不要 $ 前缀、不要行内注释。',\n  '然后在代码块下方用一句话说明需要用户补什么（如果需要的话）。',\n  '',\n  '规则：',\n  '- **不要用 Markdown 加粗 / 标题 / 列表符号**（星号和井号会原样出现在界面上）；只允许那个 SH 围栏代码块。',\n  '- 不要前言、不要总结、不要客套、不要问「需要我帮你做别的吗」。',\n  '- 需要用户填空的地方用 <尖括号> 标出；**不要编造具体的路径、文件名、IP、版本号**。',\n  '- 拿不准原因时直说拿不准，并给出**一条能查证它**的命令（看日志、看版本、看帮助）。',\n  '- 不要建议安装软件、不要建议改系统配置，除非错误信息明确指向它。',\n  '- 你没有执行能力：不要说自己运行了什么，也不要假设你能看到用户没给你的输出。',\n  '- 回答语言：中文。',\n].join('\\n')\n\nconst SYSTEM_EN = [\n  'You are a troubleshooting assistant inside a terminal panel. The user just ran a command that exited non-zero (or the screen shows an error).',\n  'Explain, in as few words as possible: what went wrong, and what to type next.',\n  '',\n  'Output format (strict, **plain text** — the panel does not render Markdown):',\n  'Start with \"What happened: \" on the first line, one or two sentences, plain language. Do not restate the raw output.',\n  'Then a blank line and \"Next step: \", immediately followed by one SH fenced block (three backticks + sh) with one or two commands that can be pasted directly, one command per line, no $ prefix, no inline comments.',\n  'Then one short line saying what the user still needs to fill in, if anything.',\n  '',\n  'Rules:',\n  '- **No Markdown bold / headings / bullets** (asterisks and hashes show up literally in the panel); the single SH fenced block is the only exception.',\n  '- No preamble, no summary, no pleasantries, no \"anything else I can help with\".',\n  '- Mark blanks as <angle brackets>; never invent paths, file names, IPs or versions.',\n  '- If unsure, say so and give ONE command that would verify it (check logs, version, help).',\n  '- Do not suggest installing software or changing system config unless the error clearly points there.',\n  '- You cannot execute anything: never claim you ran something, and never assume output you were not given.',\n  '- Answer language: English.',\n].join('\\n')\n\nexport function systemPromptFor(lang: 'zh' | 'en' | undefined): string {\n  return lang === 'en' ? SYSTEM_EN : SYSTEM_ZH\n}\n\n/**\n * 屏幕是否带来了输出里没有的东西。\n *\n * 判据是**尾段三行的包含关系**，不是「谁更有用」这种说不清的话：tmux 持久会话里\n * `lastCommand.output` 本来就是 capture-pane 快照（OSC 133;T），与屏幕是同一份内容，\n * 再发一遍纯属浪费 token；而普通会话里两者**互补**——输出是 B..D 精确捕获的（干净，\n * 但**不含命令回显**：zsh 的 preexec 发出的 B 标记在用户输入回显之后，实测确认），\n * 命令行只存在于屏幕上。\n */\nfunction screenAddsContext(output: string, screen: string): boolean {\n  if (screen.trim() === '') return false\n  if (output.trim() === '') return true\n  const probe = screen.split('\\n').filter((line) => line.trim() !== '').slice(-3)\n  if (probe.length === 0) return false\n  return !probe.every((line) => output.includes(line))\n}\n\n/**\n * 组装一次解释请求。\n *\n * **命令输出为主，屏幕补它缺的东西**（见 screenAddsContext）。两段各有不可替代之处：\n * 输出回答了「这条命令干了什么」，屏幕回答了「敲的是哪条命令」——后者恰恰是输出里\n * 没有的（实测：`tty_capture{last}` 的正文只有 `ls: … No such file or directory`）。\n *\n * `input.command` 目前**没有调用方会填**：shell 集成桩只发 A/B/D/T，不带命令行，\n * 所以这个字段留着等「桩改成 C 标记带命令」那一轮（见 ROADMAP）。\n */\nexport function buildFailurePrompt(input: AssistPromptInput): { system: string; user: string } {\n  const out = compressTerminalText(input.output ?? '')\n  const screen = compressTerminalText(input.screen ?? '', { maxLines: SCREEN_TAIL_LINES })\n  const lines: string[] = [\n    '[终端现场]',\n    'shell: ' + (input.shell !== '' ? input.shell : '(未知)'),\n    'cwd: ' + (input.cwd !== '' ? input.cwd : '(未知)'),\n  ]\n  if (input.command !== undefined && input.command !== '') lines.push('命令: ' + input.command)\n  if (input.exitCode !== undefined && input.exitCode !== null) lines.push('退出码: ' + String(input.exitCode))\n  const hasOut = out.trim() !== ''\n  const hasScreen = screenAddsContext(out, screen)\n  if (hasOut) lines.push('', '[命令输出]', out)\n  if (hasScreen) lines.push('', '[当前屏幕（含你敲的命令行与提示符）]', screen)\n  if (!hasOut && !hasScreen) lines.push('', '(没有拿到输出)')\n  const masked = maskSecrets(lines.join('\\n'))\n  return { system: systemPromptFor(input.lang), user: masked.text }\n}\n"
    },
    {
      "path": "packages/tty/client-src/index.js",
      "content": "/* eslint-disable */\n/**\n * @hyzyn/dsh-tty — 浏览器半体：侧边栏「终端」入口 + 大弹窗 xterm 面板。\n * 由 scripts/build-client.mjs 用 esbuild 打包为单文件 IIFE（xterm 内核随\n * bundle 分发），经 window.__ModuleLoader__.load 注册。\n *\n * v0.2 能力：\n * v0.3 能力：\n *   - 最小化/折叠：点空白处、Esc 或「—」按钮把弹窗收起，PTY 会话与输出\n *     缓冲保持存活；最小化状态合并进侧边栏「终端」入口（会话数徽标 +\n *     状态点，点击入口恢复），入口不在时才退回紧凑悬浮条；✕ 才真正关闭\n *   - 多会话标签页（每标签一个 sid 的 xterm 实例，可切换/关闭/新建）\n *   - 新标签默认在当前会话工作目录打开（注入 sessions 客户端服务）\n *   - 便利功能：终端内搜索（Ctrl+F）、可点击链接、清屏/复制/粘贴按钮\n * v0.4 能力：\n *   - 标签栏「+」改为菜单：本地终端 / SSH 连接簿（读 /api/dsh-tty/config 的\n *     sshHosts）/ SSH 连接…（host/port/username/auth 表单，可保存回连接簿）\n *   - SSH 会话：{t:'ssh'} 帧创建（name 引用连接簿或内联字段），ready 帧的\n *     target 回显到状态栏与标签标题；respawn 复用原 spawnSpec\n *   - 设置卡片维护 SSH 连接簿（列表 + 删除，随「保存」写入 tty settings）\n * v0.5 能力：\n *   - 断线保活与重连：异常断开（刷新页面/网络抖动）后会话在宿主保活\n *     reconnectGraceSec（默认 120s），客户端自动重连（指数退避封顶 5s），\n *     对存活标签发 {t:'attach'} 恢复并回放缓冲；页面刷新后从 sessionStorage\n *     恢复标签列表（未存活者自动丢弃）；✕ 关闭才真正结束全部会话\n *   - WebGL 渲染器（@xterm/addon-webgl，上下文丢失自动回退 DOM 渲染器）\n * v0.6 能力：\n *   - SSH 对话框：agent forwarding 勾选；密码/口令字段「从 env 插件变量填入」\n *     凭据引用选择器（候选来自连接簿里在用的引用名，与 env 插件解耦）\n *   - 「+」菜单连接簿条目带 ✎ 编辑：对话框编辑模式（预填全字段，可改名，\n *     「保存修改」按原名替换条目），连接照常可用\n *   - 设置卡片：从 ~/.ssh/config 导入连接簿（同名跳过）；从 known_hosts 导入\n *     主机指纹（TOFU 预填充）；shell 集成开关；连接簿行内编辑表单；\n *     Shell 路径可选可输入（自绘下拉候选来自 /api/dsh-tty/shells）\n *   - 标签双击重命名（随标签持久化，断线恢复保留）\n * v0.8 能力：\n *   - SFTP 文件浏览：文件 / 文件夹拖到对话框任意位置即上传（webkitGetAsEntry\n *     递归展开整文件夹、保留层级，逐文件进度 i/n），拖入时列表高亮可放置\n * v0.9 能力：\n *   - 紧凑头部：标签行兼作标题行（去「终端」标题文字与常态「已连接」状态\n *     文字，异常/瞬时消息才点亮；搜索/清屏/复制/粘贴改图标按钮），下方保留\n *     一条 SSH 连接栏——左侧状态点 + 目标，右侧 SFTP / 隧道等图标扩展按钮，\n *     本地终端标签整栏隐藏\n *   - SFTP 双栏风格（设置 sftpStyle 可选 dialog/dual）：左本机 / 右远程两栏，\n *     行内 ⇨/⇦ 由宿主 /api/dsh-tty/local-fs/transfer 服务端直传（目录递归、\n *     同名覆盖，字节不经过浏览器）；单窗体风格照旧\n * v0.10 能力：\n *   - 会话持久化（设置 persistence=tmux 即唯一开关）：新开的本地/SSH 标签\n *     默认持久化——spawn/ssh 帧带 persist + 稳定 persistName，宿主以\n *     `tmux -L dsh-tty new-session -A -s <名>` 托管；断线保活超时 / 宿主\n *     重启后重开标签按同名接回原现场（tmux 重画可见屏，正在跑的程序原样\n *     存活）；连接栏与 ready 帧带 tmux 持久标记；0.10.1 起持久标签规格\n *     另存 localStorage（跨窗口），新窗口经 sessions 帧的 tmux 清单确认\n *     后自动接回；reset 后以 refresh 帧请宿主 refresh-client 重画\n * v0.11 能力：\n *   - SSH 连接测试：设置卡片连接簿条目行内「测试」按钮 + SSH 连接对话框\n *     「试连」按钮——按当前填写的 host/port/认证 走宿主 /api/dsh-tty/probe\n *     做 TCP → 主机密钥（TOFU）→ 认证 逐段诊断，不建会话不占名额；连接簿\n *     测试随行展示结果（成功/失败原因 + host key 记录/匹配/变更提示）\n *   - SFTP 传输进度条：底部状态行新增细进度条 + 百分比——上传（XHR 流式，\n *     多文件带 i/n 标签）、下载（改流式读 response.body，content-length\n *     算百分比；无双栏整传走服务端直传时为不定进度脉冲）\n * v0.12 能力（视觉 overhaul）：\n *   - 样式表独立成 client-src/tty.css，并引入 --tt-* 令牌层（圆角/控件高度/\n *     间距/动效统一，颜色全部派生自 --dsw-* 皮肤 token；注意令牌声明在\n *     :where(html, body) 上——DSH 的深色主题是挂 body[data-ds-dark-theme]\n *     覆盖 --dsw-* 的，声明在 :root 会永远取到浅色值）\n *   - 面板/头部/标签/连接栏/终端区重排：投影 + 圆角 + 入场动效、活动标签强调、\n *     状态胶囊限宽省略、连接栏 tmux 持久徽标独立成 chip、终端底色与 xterm\n *     配色（光标取皮肤强调色、行高 1.35、JetBrains Mono 优先）\n *   - 图标全面矢量化为内置 SVG 常量（窗口按钮 / 菜单 / SFTP 行内操作 / 文件\n *     类型），替换 emoji 与文字符号；行内操作按钮改为悬停显现\n *   - 遮罩改为「图标 + 标题 + 可点副文案」动作卡片；toast 分 warn/error/info\n *     三态配色；SFTP 双栏每栏独立条目数；env 变量列表改为聚焦展开\n * 帧协议与宿主半体（src/index.ts）对齐：spawn/ssh/input/resize/kill/\n * sessions/attach ↔ ready/data/exit/error/sessions。\n */\nimport { Terminal } from '@xterm/xterm'\nimport { FitAddon } from '@xterm/addon-fit'\nimport { SearchAddon } from '@xterm/addon-search'\nimport { WebLinksAddon } from '@xterm/addon-web-links'\nimport { WebglAddon } from '@xterm/addon-webgl'\nimport xtermCss from '@xterm/xterm/css/xterm.css'\nimport ttyCss from './tty.css'\nimport { formatJumpShorthand, parseJumpShorthand } from './jump-field.js'\nimport { connCopyText, connDetailRows, jumpLabelOf, resolveConnSpec, sshCommandOf } from './conn-info.js'\nimport { checkedForBookName, nameForBookChecked } from './save-book.js'\nimport { resolveDockOwner, dockPaneVisible } from './dock-owner.js'\nimport { deriveWsUrl } from './ws-url.js'\nimport { asciiRefToken, derivedCredentialRef } from './credential-ref.js'\nimport { applyTunnelEdit, buildTunnelFromDraft as buildTunnelSpec, tunnelNameClash } from './tunnel-edit.js'\nimport { currentSessionCwd } from './current-session.js'\nimport { FALLBACK_COLS, FALLBACK_ROWS, usableFitSize } from './fit-size.js'\nimport { agentTabDisposition, countLiveSessions, liveSessionSids, sessionFrameIndex } from './session-live.js'\nimport { closePanelSummary } from './close-guard.js'\nimport { bulkClosePlan, panelTabCount } from './tab-bulk.js'\nimport { canHideFromAgent, hiddenMenuKey, isHiddenFromAgentSpec, withHiddenFromAgent } from './tab-hidden.js'\nimport { planResume } from './download-resume.js'\nimport { dirsToCreate, filterEntries, planDrop } from './sftp-view.js'\nimport { eventOwnsStatus, needsStatusResync, statusForTab } from './status-line.js'\nimport { SEARCH_CLOSED_DISPLAY, nextSearchOpen, searchDisplayFor } from './search-state.js'\nimport { PROC_SORT_DEFAULT, STATS_WARN_LIMIT, chartCeiling, clockText, coresLevel, formatBytes, formatRate, hasUsableStats, mergeOptionalStats, netScaleCeiling, nextProcSort, nextStatsStyle, procRows, sparklineArea, sparklinePath, statsFrameFresh, statsItemSpecs, statsItemValues, statsLevel, statsNum, statsPair, statsRateCompact, truncateMiddle } from './stats-bar.js'\nimport { statsTipModel } from './stats-tip.js'\nimport { TERMINAL_LOOK_DEFAULTS, readTerminalLook, terminalFontFamilyValue, terminalLookChanged, terminalLookDrift } from './terminal-look.js'\n\n/* ================================ CSS ================================ */\n\n// 样式表独立成 client-src/tty.css，经 esbuild 的 text loader 内联进 client.js\n// （与 xterm.css 同一条路径），便于按组件维护。\n\n/* ================================ 国际化 ================================ */\n\n/*\n * 界面文案走宿主 `@deepseek-ai/dsh-client-locale` 的目录（方案见 docs/i18n.md）。\n * **文案里不许出现字面 `**`**（D68）：浏览器半体没有 markdown 渲染器，用户看到的就是两个星号；\n * 强调用「」/ “” 或直接换行。\n * 目录**内联在 client-src/index.js**（不是单独一个模块）：本包用 esbuild 打成单文件 IIFE，\n * 多一个模块就多一层「谁在什么时候加载」的不确定性，而 docs/i18n.md 明确要求目录住在主半体里。\n *\n * **目录与本段的 `t` 声明在模块作用域，不在 module-loader 的 factory 里**——这是本包与\n * codegraph 的区别：tty 的界面代码绝大部分（连接栏 / SFTP / 状态条 / 面板骨架 / 状态行）\n * 都在 factory 之前的模块顶层函数里，只有设置卡片与 `exports.apply` 在 factory 内。声明在\n * 模块顶层，两边才都能看见同一个 `t`。sibling 模块（stats-bar / status-line / tunnel-edit）\n * **不 import 这里的 `t`**（那会成环），而是把它当参数传进去——与 codegraph 的 pure.js 同一套。\n *\n * 下面这一对目录由 `scripts/check-i18n.mjs` 静态校验：zh/en 键集一致、`{name}` 占位符两边\n * 一致、代码里 `t('…')` 用到的键必须在这里有定义。\n *\n * **模块级常量里的 `t()` 必须走 getter / 函数**：`t()` 在模块加载时求值等于把当前语言\n * 冻住（`installI18n(ctx)` 要等 apply 才跑，语言切换也不会重算）——本包的 `STATS_ITEM_SPECS`\n * 因此改成了 `statsItemSpecs(t)` 函数（见 client-src/stats-bar.js）。\n *\n * `tty_capture{last}` 这类**语法示例**里的花括号会被 `i18nFormat` 当成占位符——只在\n * 传了 params 时才会替换，这几条键的调用一律不传 params，所以原样显示。\n */\n/* ==== dsh-i18n:begin ==== */\nconst I18N_NS = 'tty'\nconst I18N_ZH = {\n  'error.credServiceMissing': '宿主未提供凭据服务（remote.credentials）',\n  'error.credServiceIncomplete': '凭据服务不完整',\n  'error.credStoreUnavailable': '宿主未提供凭据服务（remote.credentials），无法存入',\n  'error.credStoreFailed': '存入凭据存储失败：{error}',\n  'error.credClearUnavailable': '宿主未提供凭据服务（remote.credentials），无法清除',\n  'error.credClearFailed': '清除失败：{error}',\n  'error.credRefNeedsHost': '先填「主机」和「用户名」再存入——引用名由这两者派生',\n  'btn.reopen': '重新打开',\n  'btn.reopenTitle': '以原连接信息重开会话',\n  'btn.sftpTitle': '打开该连接的文件浏览（SFTP）',\n  'btn.tunnels': '隧道 {count}',\n  'btn.tunnelsTitle': '查看该连接的端口转发隧道',\n  'btn.more': '更多',\n  'btn.moreTitle': '更多操作（端口转发 / 复制连接信息…）',\n  'btn.copyConn': '复制连接信息',\n  'btn.copyConnTitle': '把目标 / 跳板机 / 认证方式复制到剪贴板（不含任何凭据）',\n  'btn.copySshCommand': '复制 SSH 命令',\n  'btn.copySshCommandTitle': '复制一条可直接执行的 ssh 命令（含端口 / 跳板机 / 代理命令，不含凭据）',\n  'msg.connCopied': '已复制连接信息',\n  'connDetail.title': '连接详情',\n  'connDetail.clickHint': '点击查看连接详情（目标 / 跳板机 / 认证 / 持久化）',\n  'connDetail.target': '目标',\n  'connDetail.book': '连接簿条目',\n  'connDetail.auth': '认证方式',\n  'connDetail.jump': '跳板机',