inejoin=\"round\" aria-hidden=\"true\"><path d=\"M12.6 8h-9\"/><path d=\"M6.8 4.8L3.6 8l3.2 3.2\"/></svg>'\nconst ICON_ARROW_DOWN =\n  '<svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 3.4v9\"/><path d=\"M4.8 9.2L8 12.4l3.2-3.2\"/></svg>'\n/*\n * 「高级」折叠区的展开图标：**逐字对齐宿主 `dsh-client-ui-primitives` 的\n * `IconChevronRightOutlineRegular` / `IconChevronDownOutlineRegular`**（viewBox 16、\n * `stroke-width: 1`、`stroke: currentColor`、无 `linecap/linejoin`、默认 14px）。\n * 官方在 provider 卡片的「自定义设置」上就是这一对：**收起 = 右尖括号、展开 = 下尖括号**。\n *\n * 本包其余 16 网格图标走 1.5 / 1.6 线宽 + 圆头（那是面板自己的语言），这里刻意不套用——\n * 用户的原话是「展开图标和 dsh 官方的图标保持一致」，而 disclosure 的图标是**宿主的**语言。\n * 判据钉在 `test/ssh-dialog-shell.test.ts`（路径逐字比对），改动前先回头对宿主那份。\n */\nconst ICON_CHEVRON_RIGHT =\n  '<svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\" aria-hidden=\"true\"><path d=\"M6 12L9.29289 8.70711C9.68342 8.31658 9.68342 7.68342 9.29289 7.29289L6 4\"/></svg>'\nconst ICON_CHEVRON_DOWN =\n  '<svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\" aria-hidden=\"true\"><path d=\"M4 6L7.29289 9.29289C7.68342 9.68342 8.31658 9.68342 8.70711 9.29289L12 6\"/></svg>'\nconst ICON_SERVER =\n  '<svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><rect x=\"2.4\" y=\"3.2\" width=\"11.2\" height=\"4\" rx=\"1.2\"/><rect x=\"2.4\" y=\"8.8\" width=\"11.2\" height=\"4\" rx=\"1.2\"/><path d=\"M5 5.2h.01\"/><path d=\"M5 10.8h.01\"/></svg>'\n// 状态 / 提示\nconst ICON_WARN =\n  '<svg viewBox=\"0 0 16 16\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 2.6l5.8 10.4H2.2z\"/><path d=\"M8 6.4v3.2\"/><path d=\"M8 11.6h.01\"/></svg>'\nconst ICON_INFO =\n  '<svg viewBox=\"0 0 16 16\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"5.6\"/><path d=\"M8 7.2v3.6\"/><path d=\"M8 5.1h.01\"/></svg>'\nconst ICON_STOP =\n  '<svg viewBox=\"0 0 16 16\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"5.6\"/><path d=\"M6 6l4 4\"/><path d=\"M10 6l-4 4\"/></svg>'\nconst ICON_POWER =\n  '<svg viewBox=\"0 0 16 16\" width=\"15\" height=\"15\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M8 2.8v5\"/><path d=\"M11.6 4.6a5.2 5.2 0 1 1-7.2 0\"/></svg>'\nconst ICON_KEY =\n  '<svg viewBox=\"0 0 16 16\" width=\"14\" height=\"14\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"5.6\" cy=\"6\" r=\"2.8\"/><path d=\"M7.8 7.9l5.4 5.4\"/><path d=\"M10.6 10.7l1.2-1.2\"/></svg>'\n\nlet sessionsService = null\nlet socket = null\nlet modalEl = null\nlet statusChipEl = null\n\n/**\n * 状态胶囊当前「讲的是哪个标签」：sid，或 null（面板级 / 宿主级消息，不属于任何标签）。\n * 切标签 / 关标签后拿它跟活动标签比，不一致就用活动标签自己记下的状态重算——\n * 否则失败标签的错误会一直挂在头上（见 status-line.js 的文件头）。\n */\nlet statusSid = null\n\n/**\n * 官方凭据引用的**浏览器侧命名空间**（`ctx.remote.credentials`）。\n *\n * 「记住密码」要落到官方凭据存储，而不是把明文写进设置文件——配置持引用、值归存储，\n * 这既是 SecureCRT「命名凭据集按标题引用」那一派，也正是 DSH 自己设置卡片的做法\n * （`describe` / `set` / `unset`，值**单向写入、没有任何读路径**）。\n *\n * 可选：老宿主没有 `remote` 时保持 null，对话框那一行会禁用按钮并说明原因。\n */\nlet credentialsRemote = null\nlet statusEl = null\nlet statusDotEl = null\nlet tabbarEl = null\n/** 标签栏溢出时才出现的「⋯」标签列表入口（0.23.0）。 */\nlet tabMoreEl = null\nlet connbarEl = null\nlet connDotEl = null\nlet connTargetEl = null\nlet connBadgeEl = null\n/** 跳板机徽标：只在 spec.jump 存在时显示（连的是哪台 bastion 不该靠记）。 */\nlet connJumpBadgeEl = null\nlet connActionsEl = null\nlet bodyEl = null\n/** 终端区 + 右侧挂载位的横向容器（openModal 建立；ttyPanel.mountPane 往这里插 pane）。 */\nlet workEl = null\nlet searchInputEl = null\nlet bodyOverlayEl = null\nlet intentionalClose = false\nlet resizeObserver = null\n/** 最小化状态：弹窗隐藏但会话保活，由右下角悬浮条（dock）恢复。 */\nlet minimized = false\nlet dockEl = null\nlet dockCountEl = null\nlet dockStatusEl = null\nlet dockDotEl = null\nlet dockActivityTimer = null\n/** 断线自动重连：指数退避（1s 起步、封顶 5s），面板开着就一直尝试。 */\nlet reconnectTimer = null\nlet reconnectDelay = 1000\n/** 标签列表持久化（sessionStorage）：页面刷新后按 sid 重连宿主保活的会话。 */\nconst PERSIST_KEY = 'dsh-tty:tabs'\n\n/** sid → 标签页 */\nconst tabs = new Map()\n/**\n * 嵌入式终端（0.15.0）：其他插件（如 dsh-docker）经 ttyTerminal.mount 把终端挂到\n * 自己的面板里。它们与标签共用同一条 WebSocket 与会话表，但**不进标签栏、不写\n * sessionStorage、也不随 tty 面板关闭而销毁**——这里单独记 sid，便于廉价判断\n * 「还有没有嵌入会话在跑」（决定关面板时要不要留连接）。\n */\nconst embeddedSids = new Set()\nconst hasEmbedded = () => embeddedSids.size > 0\n/** 连接尚未就绪时挂起的创建帧（嵌入式终端可能在 socket 打开前就挂载）。 */\nconst pendingSpawns = new Set()\nlet activeSid = null\nlet tabCounter = 0\nlet connecting = false\n/** 「+」新建菜单与 SSH 连接对话框（挂在 document.body 的浮层）。 */\nlet addMenuEl = null\n/* ---------- AI 辅助「失败即解释」（0.24.0） ---------- */\n/**\n * 配置开关（/api/dsh-tty/config 的 assistEnabled，**默认关**）。\n *\n * 关掉时连徽标都不摆：宿主侧也会拒 `/api/dsh-tty/assist`（两道闸），但界面这一侧\n * 不该出现一个点了只会报错的入口。\n */\nlet assistEnabledCache = false\n/**\n * 待处理的失败徽标：sid → { exitCode, at, dismissed }。\n *\n * 刻意**不做成 tab 字段**：`tabs.set` 有 5 处（本地/SSH/attach/agent 标签/嵌入），\n * 每处补一个字段就多 5 个漏掉的点；徽标本身也只是「这个 sid 上最近一次失败」。\n */\nconst assistHints = new Map()\n/** 已打开的答案浮层（挂在 document.body，皮肤复用 .tt_addMenu）。 */\nlet assistMenuEl = null\n/** 浮层对应的 sid：切标签/关标签时据此收起，避免答案挂到另一个终端上。 */\nlet assistMenuSid = null\n/** 在途请求的 AbortController：关浮层即取消，迟到的答案不许盖到新内容上。 */\nlet assistAbort = null\n/** 徽标 DOM（每个面板一枚；`.tt_body` 右下角）。 */\nlet assistBadgeEl = null\n/** 浮层的锚点（就是徽标本身）：内容变化后高度会变，每次重渲染都要重新定位。 */\nlet assistMenuAnchor = null\n/** 标签列表弹层（挂在 document.body，皮肤复用 .tt_addMenu）。 */\nlet tabListMenuEl = null\nlet sshDialogEl = null\n/** SSH 连接簿缓存：/api/dsh-tty/config 的 sshHosts（设置卡片保存后同步）。 */\nlet sshHostsCache = []\n/* ---------- 服务器状态条（0.17.0） ---------- */\n/** 配置开关（/api/dsh-tty/config 的 statsEnabled；关掉后整条收起且不发订阅）。 */\nlet statsEnabledCache = true\n/** 状态条 DOM（每个面板一条，跟随活动标签；挂在 .tt_body 里、终端容器之前）。 */\nlet statsBarEl = null\n/* ---------- 退出提示条（D96 / issue #7①②） ---------- */\n/**\n * 退出提示条 DOM（与状态条同级、同机制：绝对定位在 .tt_body 顶部，显隐只把 .tt_term\n * 的 top 往下推）。它取代了原来那层**铺满整个终端区**的退出遮罩——那层把输出挡住了\n * （用户上报「AI 打开的终端跑出来的结果看不清」，还得去 F12 里把 `.tt_overlay` 藏掉）。\n */\nlet exitBarEl = null\n/** 退出提示条的数据签名：同一条不重复重画（重建会丢掉刚聚焦的按钮）。 */\nlet exitBarRenderKey = ''\n/* ---------- 关面板二次确认（issue #8） ---------- */\n/**\n * 确认层 DOM（每个面板最多一个）。判据是「这一下会结束几条活会话」，不是「开了几个\n * 标签」——见 client-src/close-guard.js 的文件头。\n */\nlet confirmEl = null\n/** 显示确认层之前那个获得焦点的元素（关掉后还给它）。 */\nlet confirmReturnFocus = null\n/** 当前已向宿主订阅的 sid（可见性驱动；null = 没订阅）。 */\nlet statsSubSid = null\n/** 陈旧检测定时器：面板打开期间每秒复查（采集端静默停止时要能自己收起状态条）。 */\nlet statsStaleTimer = null\n/**\n * 状态条条目 DOM 引用（与 statsItemSpecs(t) 同序、等长；null = 还没建 / 已随面板作废）。\n * 条目**只建一次**，之后每次刷新只写真的变了的文本——整条 innerHTML 重写会丢掉 CSS\n * 过渡、把横向滚动位置弹回 0，且任何值位数变化都会推着后面所有条目横移（见 stats-bar.js\n * 文件头：用户报的「定期闪动」）。\n */\nlet statsItemEls = null\n/**\n * 按**机器能力**出现的条目（2026-11-01）：没报过就整格不画（不是显示「无」）。\n * 判据存在会话上（`tab.seenItems`），见帧到达处的注释。\n */\nconst OPTIONAL_ITEM_KEYS = new Set(['tempC', 'ping', 'swap'])\n/**\n * 空间不够时的**让位阶梯**（2026-11-01）：从「最可替代」到「最不可替代」，按这条顺序逐级藏，\n * 一不溢出就停。条宽是有限的，加到 10 项之后 1280px 的面板本来就装不下。\n *\n * 为什么只有**一条**顺序：原先是两条独立阶梯（条目区先让「核心 / 在线」，再轮到右侧那组让\n * 「时钟 → 整组」），每条都「一不溢出就返回」。于是条目区刚好吃满、右侧那组每次都被判溢出而\n * 整组藏掉——加完 Ping / Swap（10 格）之后，完整模式**在任何视口**都看不到负载 / 时钟\n * （面板宽上限就是 1280px），而只有 5 格的极简模式反而看得到。让位该按信息价值排，\n * 不该按 DOM 顺序排。\n *\n * 顺序与理由：\n *   ① `cores`（核心数）——静态的机器事实，明细卡片脚注里还有「16 核 · 平均 63%」；\n *   ② `uptimeSec`（在线时长）——同样是静态信息，`tty_stats` 里还能读到；\n *   ③ `clock`（时钟）——装饰性读数，但它是这一组的另一半；只有连静态项都让完还不够时才收；\n *   ④ `extra`（负载 + 时钟整组）——只作极窄面板的兜底。\n * 活指标（CPU / 内存 / 磁盘 / TCP / Ping / Swap / 网络 / 负载）一律不让——那是状态条存在的理由。\n *\n * ③ 为什么排在 ①② 后面（而不是像原来那样先藏时钟）：阶梯是**前缀序**，前面每一步都会挤掉\n * 后面能用的空间。先藏时钟时实测是这样收场的——时钟只值 ~60px 不够，于是还得接着藏「核心」\n * 「在线」（合计 ~135px），最后明明有空间容下时钟，它却已经被牺牲掉了：既丢了两个静态项、\n * 又没保住用户要的那半组。把它排到静态项之后，同样的空间预算下收场是\n * 「核心 / 在线 让位，负载 + 时钟都在」。\n */\nconst YIELD_ORDER = ['cores', 'uptimeSec', 'clock', 'extra']\n/**\n * 参与让位的**条目**键：从 `YIELD_ORDER` 里剔掉两个非条目档位推出来。\n * 不另写一份列表——两处各写一遍，加一格新指标时迟早会漂（见上面那段理由）。\n */\nconst YIELD_ITEM_KEYS = YIELD_ORDER.filter((key) => key !== 'clock' && key !== 'extra')\n/** 已渲染的数据签名（sid + 帧时间）：同一条数据不重复渲染（1s 陈旧检测也走 applyStatsBar）。 */\nlet statsRenderKey = null\n/** 状态条滚动容器（完整 / 极简两种呈现共用）与两个条目容器。 */\nlet statsScrollEl = null\nlet statsFullEl = null\nlet statsMinEl = null\n/** 面板头部（搜索 / 清屏旁边）的「完整 / 极简 / 隐藏」三档循环按钮。 */\nlet statsToggleEl = null\nlet statsToggleMode = null\n/** 极简模式的三个条目引用（CPU / 内存 / 网络）。 */\nlet statsMinRefs = null\n/**\n * 状态条的呈现（`full` / `minimal` / `off`）：存在 **localStorage**（浏览器本地偏好），\n * 不进 profile 配置——它是即时显示偏好，不该为一个显示形态改配置、也不该跟机器走。\n * `off` 会同时停掉当前标签的 stats 订阅（宿主采集器与远端 channel 一并停）。\n */\nconst STATS_STYLE_KEY = 'dsh-tty:stats-style'\nlet statsStyleCache = readStatsStyle()\n/**\n * 极简模式的趋势线历史：每个会话最近 60 个采样（1s/帧 ≈ 一分钟）。\n *\n * 为什么在客户端留：宿主每次只发当前帧（没有历史接口），趋势线只能自己攒。会话退出 /\n * 标签关闭即清；面板关闭整表清空（下次打开从零开始，线从左往右长）。\n */\nconst STATS_HISTORY_LEN = 60\nconst statsHistory = new Map()\n/** 极简条 SVG 渐变 id 的序号：同一文档里多个面板也不能撞 id。 */\nlet statsSparkGradientSeq = 0\n/**\n * 明细仪表盘（2026-10-31）：状态条最右端那颗「▴」展开的悬浮卡片。\n *\n * 三个卡片各管一摊：CPU 每核柱状 / 网络双向曲线 / Top 进程。数据全部来自\n * **已经在推的 stats 帧**（`cpuCores` / `procs` 是帧的可选字段），客户端不额外发起请求；\n * 趋势用本地攒的历史（与极简条同一份 `statsHistory`）。\n */\nlet statsExpandEl = null\nlet statsDashEl = null\nlet statsDashDismiss = null\n/** 卡片里的可变节点引用（只建一次，每帧改属性/文本，不重建 DOM）。 */\nlet statsDashRefs = null\n/** 上一次画图表用的签名：同一帧不重复重算路径（1s 陈旧检测也会走到这里）。 */\nlet statsDashKey = null\n/**\n * 进程卡片的排序状态（点列头切换，见 `nextProcSort`）。只存在内存里、不持久化：\n * 这是「临时看一眼」的浮层，用户重新打开时回到 CPU 降序最符合直觉。\n */\nlet statsDashSort = { ...PROC_SORT_DEFAULT }\n\nfunction readStatsStyle() {\n  try {\n    const stored = globalThis.localStorage?.getItem(STATS_STYLE_KEY)\n    return stored === 'minimal' || stored === 'off' ? stored : 'full'\n  } catch {\n    return 'full' // 隐私模式 / 存储被拒：退回完整模式，不抛\n  }\n}\n\nfunction writeStatsStyle(style) {\n  try {\n    globalThis.localStorage?.setItem(STATS_STYLE_KEY, style)\n  } catch {\n    /* 存不下就只生效这一次：显示形态不是关键数据，不打扰用户 */\n  }\n}\n/**\n * 连接栏按钮注册表（0.13.0）：内置动作（重新打开 / SFTP / 隧道）与第三方插件\n * 经客户端服务 `ttyConnbar` 注册的按钮走**同一条通道**，显示顺序 = 注册顺序。\n * 每次 renderConnbar 按当前标签调用一遍全部工厂，工厂自行决定这次要不要加按钮。\n */\nconst connbarActions = new Set()\n\n/** 注册一个连接栏按钮工厂；返回注销函数。 */\nfunction registerConnbarAction(factory) {\n  connbarActions.add(factory)\n  return () => connbarActions.delete(factory)\n}\n\n// 内置动作：与第三方扩展同一通道，因此顺序与权限完全一致（插件禁用时全部收起）\nregisterConnbarAction(({ tab, addAction }) => {\n  if (!entryVisible) return\n  if (tab.exited) addAction(ICON_RECONNECT, t('btn.reopen'), t('btn.reopenTitle'), () => respawnTab(tab.sid))\n})\nregisterConnbarAction(({ tab, addAction }) => {\n  if (!entryVisible) return\n  // 归属这个标签：切到别的标签时文件浏览跟着收起（它连的是这个标签的那台主机）\n  addAction(ICON_SFTP, 'SFTP', t('btn.sftpTitle'), () => openSftpBrowser(tab.spawnSpec, tab.sid))\n})\nregisterConnbarAction(({ bookName, addAction }) => {\n  if (!entryVisible) return\n  const count = bookName !== '' ? tunnelCountFor(bookName) : 0\n  if (count > 0) {\n    // 该连接有启用隧道：常驻按钮（带数量），一眼可见、可点开看实时状态\n    addAction(ICON_TUNNEL, t('btn.tunnels', { count }), t('btn.tunnelsTitle'), (event) => openTunnelPopover(event.currentTarget, bookName))\n  }\n  /*\n   * 「⋯」不在这里注册：它是动作区的溢出入口，恒排最后（见 renderConnbar 末尾）。放进注册通道\n   * 会按注册顺序落在第三方动作（如 dsh-docker 的「容器」）左边，而那正是它不该在的位置。\n   */\n})\n\nfunction setStatus(text, state) {\n  if (statusEl === null) return\n  /*\n   * 胶囊只放**第一句**，完整说明进 tooltip：宿主那句「会话数已达上限（4）——每个窗口的每个\n   * 标签各占一个名额：关闭不用的窗口/标签，或在设置卡片调大「并发会话上限」」有六十多字，\n   * 即使有 max-width + 省略号也会把标签条吃掉三分之一（实测截图里活动标签被挤到只剩半个）。\n   * 本仓的状态文案用 `——` 分隔「结论」与「解释」，所以按它切一刀就够。\n   */\n  statusEl.textContent = text.split('——')[0]\n  statusEl.title = text\n  statusDotEl.dataset.state = state\n  // 单行头部常态不占位：state=connected 时收起状态块，异常/瞬时消息才点亮\n  if (statusChipEl !== null) statusChipEl.style.display = state === 'connected' ? 'none' : ''\n  // 最小化时用户只看得到侧边栏入口徽标 / 兜底悬浮条，状态同步到那里\n  if (dockStatusEl !== null) dockStatusEl.textContent = text\n  if (dockDotEl !== null) dockDotEl.dataset.state = state\n  const badgeDot = document.querySelector('[data-dsh-tty-entry] .tt_sidebarBadgeDot')\n  if (badgeDot !== null) badgeDot.dataset.state = state\n}\n\n/**\n * 标签级状态：把原文记在这个标签自己身上，并且**只在它是活动标签时**才占用胶囊。\n *\n * 记下来是为了「切走再切回来」能还原同一条消息（SSH 失败原因、退出码都在里面），\n * 而不是退成一句泛泛的兜底文案；后台标签的事件只记不显示，免得它在别的主机上\n * 顶掉你正看着的那个会话的状态（见 status-line.js 的 eventOwnsStatus）。\n *\n * @param sid 这条消息属于哪个标签；宿主级消息（没有 sid）传 undefined/null。\n */\nfunction setTabStatus(sid, text, state) {\n  const owner = typeof sid === 'string' && sid !== '' ? sid : null\n  if (owner !== null) {\n    const tab = tabs.get(owner)\n    if (tab !== undefined) {\n      tab.statusText = text\n      tab.statusState = state\n    }\n  }\n  // 归属判定用归一化后的 owner（null = 宿主级），别再用原始 sid：\n  // 同一个函数里两套「空值」口径容易在后续改动里分叉\n  if (!eventOwnsStatus(owner, activeSid)) return\n  statusSid = owner\n  setStatus(text, state)\n}\n\n/** 面板级 / 宿主级状态（WebSocket 连接中、断开重连……）：不属于任何标签。 */\nfunction setPanelStatus(text, state) {\n  statusSid = null\n  setStatus(text, state)\n}\n\n/**\n * 活动标签变了（切换 / 关闭 / 恢复）之后重算胶囊。\n *\n * 这是「窗口关了，错误迟迟不消失」的修复点：只在归属 ≠ 活动标签时才动，\n * 免得盖掉刚写进去的瞬时消息（传输进度之类）。\n */\nfunction syncStatusToActiveTab() {\n  if (!needsStatusResync(statusSid, activeSid)) return\n  const tab = activeSid === null ? undefined : tabs.get(activeSid)\n  statusSid = tab === undefined ? null : activeSid\n  const next = statusForTab(tab, t)\n  setStatus(next.text, next.state)\n}\n\nfunction sendFrame(msg) {\n  if (socket !== null && socket.readyState === WebSocket.OPEN) {\n    socket.send(JSON.stringify(msg))\n  }\n}\n\n/* ============================ 服务器状态条（0.17.0） ============================ */\n\n/**\n * 建状态条条目（每面板一次，DOM 结构与 statsItemSpecs(t) 一一对应）。\n *\n * 为什么不让每次 stats 帧重建 HTML（D49）：整条 `innerHTML` 重写会（a）丢掉\n * `.tt_statsMeterFill` 的宽度过渡——元素每秒被重建，过渡永远没机会跑；（b）把横向\n * 滚动位置弹回 0（窄窗口下 0.19.0 的 D33 允许横滚着看右侧条目）；（c）任何值的位数\n * 变化都会把后面所有条目推着横移。第 (c) 条就是用户报的「状态条定期闪动」。\n * 这里的固定槽位（`min-width: Nch`，值右对齐）配上「只写变化过的文本」，\n * 让「CPU 5% → 12%」「TCP 36 → 1024」都不再改变任何条目的几何。\n */\n/**\n * 头部按钮的点击：**完整 → 极简 → 隐藏 → 完整**。\n *\n * 隐藏是本地偏好（localStorage），同时停掉当前标签的 stats 订阅——宿主采集器与远端\n * exec channel 一并停，不是只把条藏起来还在后台采。再点回完整/极简会重新订阅。\n */\nfunction onStatsToggleClick() {\n  statsStyleCache = nextStatsStyle(statsStyleCache)\n  writeStatsStyle(statsStyleCache)\n  // 切模式时强制重画一次：`applyStatsBar` 的数据签名没变（同一帧），不重置就只换了显隐、\n  // 极简条会停在上一次刷新（<1s）的值上\n  statsRenderKey = null\n  // 切呈现会换掉条目 DOM（完整 ↔ 极简），旧 anchor 即将不可见：卡片先收\n  hideStatsTip()\n  applyStatsBar()\n  // 「显示 ↔ 隐藏」改变订阅；「完整 ↔ 极简」改变条高（24 ↔ 36px）——两件事都得跟\n  syncStatsSubscription()\n  refitActiveTab()\n}\n\n/**\n * 保证状态条外壳（滚动容器 + 切换按钮）在：面板刚建时模板里有；隐藏时为了省 DOM\n * 会被整块清空，下次显示要重建——**重建的是外壳**，条目容器由 buildStatsBarDom 补。\n */\nfunction ensureStatsBarShell() {\n  if (statsBarEl === null) return false\n  if (statsScrollEl !== null && statsBarEl.contains(statsScrollEl)) return true\n  statsBarEl.textContent = ''\n  statsScrollEl = document.createElement('div')\n  statsScrollEl.className = 'tt_statsScroll'\n  bindStatsScrollEvents(statsScrollEl)\n  statsBarEl.appendChild(statsScrollEl)\n  /*\n   * 展开按钮**不随条目滚动**：它挂在滚动区外面、条的最右端。放里面会被长服务器名\n   * 一类的条目挤出可视区（用户就再也点不到了）。\n   */\n  statsExpandEl = document.createElement('button')\n  statsExpandEl.type = 'button'\n  statsExpandEl.className = 'tt_statsExpand'\n  statsExpandEl.dataset.act = 'stats-expand'\n  statsExpandEl.addEventListener('click', onStatsExpandClick)\n  statsBarEl.appendChild(statsExpandEl)\n  /*\n   * 图标 / tooltip / aria 一律走同一个入口：外壳被重建时（隐藏后重新显示）仪表盘可能\n   * 还开着，这时按钮必须画成「收起」而不是回到默认的 ▴ ——否则箭头与实际状态脱节。\n   */\n  applyStatsExpandState(statsDashEl !== null)\n  statsFullEl = null\n  statsMinEl = null\n  statsMinRefs = null\n  return true\n}\n\n/**\n * 悬浮提示的事件挂在**滚动容器**上（委托，不逐个绑条目）：条目在完整 / 极简两种呈现里\n * 各建各的，逐个绑会随重建漏绑。\n *\n * 要绑两次的原因：模板里**已经带**一颗 `.tt_statsScroll`（面板打开时直接 query 出来复用），\n * `ensureStatsBarShell` 只在「那条不在文档里」时才重建另一颗——两处都得绑，否则常见路径\n * （模板那颗）上永远收不到 pointerover。元素随面板 / 外壳一起销毁，不需要解绑。\n */\nfunction bindStatsScrollEvents(el) {\n  if (el === null) return\n  el.addEventListener('pointerover', onStatsPointerOver)\n  el.addEventListener('pointerout', onStatsPointerOut)\n  el.addEventListener('pointerdown', hideStatsTip)\n  el.addEventListener('scroll', hideStatsTip, { passive: true })\n}\n\n/** 条目 DOM 全没了（隐藏 / 兜底清空）之后，所有引用一起作废，避免往游离节点上写。 */\nfunction forgetStatsDom() {\n  statsScrollEl = null\n  statsFullEl = null\n  statsMinEl = null\n  statsMinRefs = null\n  statsExpandEl = null\n  // 右侧那组「负载 / 时钟」随条一起销毁：引用与定时器都作废\n  statsExtraEl = null\n  statsExtraRefs = null\n  stopStatsClockTimer()\n  // 仪表盘 / 悬浮提示挂在 body 上、锚在状态条上：条没了（面板关闭 / 隐藏）必须跟着收\n  closeStatsDash()\n  hideStatsTip()\n  discardStatsItems()\n}\n\nfunction buildStatsBarDom() {\n  const refs = []\n  if (!ensureStatsBarShell()) return refs\n  if (statsFullEl === null) {\n    statsFullEl = document.createElement('div')\n    statsFullEl.className = 'tt_statsFull'\n    statsScrollEl.appendChild(statsFullEl)\n  }\n  const fragment = document.createDocumentFragment()\n  for (const spec of statsItemSpecs(t)) {\n    const item = document.createElement('span')\n    item.className = 'tt_statsItem'\n    const label = document.createElement('span')\n    label.className = 'tt_statsLabel'\n    label.textContent = spec.label\n    item.appendChild(label)\n    let meter = null\n    let fill = null\n    // 有迷你进度条的条目：CPU（纯百分比）与 内存/磁盘（百分比 + 已用/总量合并项）\n    if (spec.kind === 'pct' || spec.kind === 'pctpair') {\n      meter = document.createElement('span')\n      meter.className = 'tt_statsMeter'\n      fill = document.createElement('span')\n      fill.className = 'tt_statsMeterFill'\n      meter.appendChild(fill)\n      item.appendChild(meter)\n    }\n    const value = document.createElement('span')\n    value.className = 'tt_statsValue'\n    item.appendChild(value)\n    fragment.appendChild(item)\n    // slot 先记 null（而不是 spec.slot）：网络条的槽位随「有没有速率」变（0 / 23），\n    // 首帧必须按实际值设一次，不能想当然套用 spec 里的默认值\n    refs.push({ key: spec.key, item, value, meter, fill, slot: null })\n  }\n  statsFullEl.appendChild(fragment)\n  buildStatsMinimalDom()\n  return refs\n}\n\n/**\n * 极简模式的 DOM（CPU / 内存 / 网络三项）：小标签 + sparkline + 大数字。\n *\n * 结构与完整模式一样**只建一次**：每帧只改 path 的 `d`、值文本与档位属性；\n * 重建会让趋势线整条闪一下（与 D49 那条「innerHTML 每秒重建」同型）。\n */\nfunction buildStatsMinimalDom() {\n  if (statsScrollEl === null || statsMinEl !== null) return\n  statsMinEl = document.createElement('div')\n  statsMinEl.className = 'tt_statsMin'\n  const makeItem = (labelText, kind, options = {}) => {\n    const item = document.createElement('span')\n    item.className = 'tt_statsMinItem'\n    item.dataset.kind = kind\n    const label = document.createElement('span')\n    label.className = 'tt_statsMinLabel'\n    label.textContent = labelText\n    item.appendChild(label)\n    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')\n    svg.setAttribute('class', 'tt_statsSpark')\n    svg.setAttribute('viewBox', '0 0 100 16')\n    svg.setAttribute('preserveAspectRatio', 'none')\n    svg.setAttribute('aria-hidden', 'true')\n    /*\n     * 填充面用 SVG 渐变（`currentColor` → 透明）：CSS 的 mask/gradient 作用在 SVG 子元素上\n     * 各家引擎支持不一致（实测 Chromium 里 mask-image 被忽略，面积变成一块实色块），\n     * 而 stop-color=currentColor 会取 SVG 自己的 color（由 CSS 按档位给），换主题也跟着走。\n     */\n    const gradientId = 'tt-spark-fade-' + String(++statsSparkGradientSeq)\n    const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs')\n    const gradient = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient')\n    gradient.setAttribute('id', gradientId)\n    /*\n     * `userSpaceOnUse` + y2=16（= viewBox 高）：渐变锚在**图表高度**上，不锚在路径包围盒上。\n     * 差别在「一条几乎水平的线」上尤其明显：包围盒只有 2~3 个单位高时，objectBoundingBox\n     * 会把 .30 那一档压成一整条实色带（内存 86% 看着就像一根进度条）；锚在行高上，\n     * 填充从线往下逐渐淡出，才读得出「面积」而不是「色块」。\n     */\n    gradient.setAttribute('gradientUnits', 'userSpaceOnUse')\n    gradient.setAttribute('x1', '0')\n    gradient.setAttribute('y1', '0')\n    gradient.setAttribute('x2', '0')\n    gradient.setAttribute('y2', '16')\n    // 中段留一档 .14：CPU/网络常年在半高处，只靠首档会淡到看不见\n    const stops = [['0', '.30'], ['0.55', '.14'], ['1', '0']]\n\n    for (const [offset, opacity] of stops) {\n      const stop = document.createElementNS('http://www.w3.org/2000/svg', 'stop')\n      stop.setAttribute('offset', offset)\n      stop.setAttribute('stop-color', 'currentColor')\n      stop.setAttribute('stop-opacity', opacity)\n      gradient.appendChild(stop)\n    }\n    defs.appendChild(gradient)\n    /*\n     * 第二条渐变：**横向**的「时间流向」（左暗右亮），只给折线用。\n     * 只用不透明度阶梯、色相交给 `currentColor`——越线转橙/红时线、面积、光晕一起变色，\n     * 不必再维护第二套色值（与明细仪表盘同一套做法，见 `dashFlowGradient`）。\n     */\n    const flowId = 'tt-spark-flow-' + String(++statsSparkGradientSeq)\n    const flow = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient')\n    flow.setAttribute('id', flowId)\n    flow.setAttribute('gradientUnits', 'userSpaceOnUse')\n    flow.setAttribute('x1', '0')\n    flow.setAttribute('y1', '0')\n    flow.setAttribute('x2', '100')\n    flow.setAttribute('y2', '0')\n    for (const [offset, opacity] of [['0', '.38'], ['0.55', '.78'], ['1', '1']]) {\n      const stop = document.createElementNS('http://www.w3.org/2000/svg', 'stop')\n      stop.setAttribute('offset', offset)\n      stop.setAttribute('stop-color', 'currentColor')\n      stop.setAttribute('stop-opacity', opacity)\n      flow.appendChild(stop)\n    }\n    defs.appendChild(flow)\n    svg.appendChild(defs)\n    // 先画填充面、再画折线：面在下面不盖线（极简条的「有体积」主要来自这块面积）\n    const area = document.createElementNS('http://www.w3.org/2000/svg', 'path')\n    area.setAttribute('class', 'tt_statsSparkArea')\n    area.setAttribute('fill', 'url(#' + gradientId + ')')\n    svg.appendChild(area)\n    /*\n     * 80% 警戒线：只有 0~100 的两项（CPU / 内存）画——网络那条是字节速率、纵轴随量程走，\n     * 「80%」在它上面没有含义。虚线压得很淡，16px 高的缩略线里它只是「天花板」的暗示。\n     */\n    if (options.limit === true) {\n      const y = String(Number((16 * (1 - STATS_WARN_LIMIT / 100)).toFixed(2)))\n      const limit = document.createElementNS('http://www.w3.org/2000/svg', 'line')\n      limit.setAttribute('class', 'tt_statsSparkLimit')\n      limit.setAttribute('x1', '0')\n      limit.setAttribute('y1', y)\n      limit.setAttribute('x2', '100')\n      limit.setAttribute('y2', y)\n      svg.appendChild(limit)\n    }\n    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')\n    path.setAttribute('class', 'tt_statsSparkLine')\n    path.setAttribute('stroke', 'url(#' + flowId + ')')\n    path.setAttribute('vector-effect', 'non-scaling-stroke')\n    svg.appendChild(path)\n    item.appendChild(svg)\n    const value = document.createElement('span')\n    value.className = 'tt_statsMinValue'\n    item.appendChild(value)\n    statsMinEl.appendChild(item)\n    return { item, area, path, value }\n  }\n  /**\n   * 纯文本格子（无趋势线）：Ping 与 Swap 在极简条里也是「标签 + 一个值」——\n   * 它们没有「这一分钟在涨还是在抖」这层信息（Ping 的抖动在悬停卡片的峰值里，\n   * Swap 是单调量），再画一条 112px 的线只是白占宽度。\n   */\n  const makeTextItem = (labelText, kind) => {\n    const item = document.createElement('span')\n    item.className = 'tt_statsMinItem'\n    item.dataset.kind = kind\n    const label = document.createElement('span')\n    label.className = 'tt_statsMinLabel'\n    label.textContent = labelText\n    item.appendChild(label)\n    const value = document.createElement('span')\n    value.className = 'tt_statsMinValue tt_statsMinText'\n    item.appendChild(value)\n    statsMinEl.appendChild(item)\n    return { item, value }\n  }\n  const cpu = makeItem('CPU', 'cpu', { limit: true })\n  const mem = makeItem(t('meta.mem'), 'mem', { limit: true })\n  const net = makeItem(t('meta.net'), 'net')\n  const ping = makeTextItem('Ping', 'ping')\n  const swap = makeTextItem('Swap', 'swap')\n  ping.item.hidden = true\n  swap.item.hidden = true\n  // 网络的值是「↓下行 ↑上行」两段，分开着色（下行走强调色、上行走成功色）\n  net.value.textContent = ''\n  const down = document.createElement('span')\n  down.className = 'tt_statsMinDown'\n  const up = document.createElement('span')\n  up.className = 'tt_statsMinUp'\n  // 两个方向都没有数据时（macOS 本地 / 采集失败）显示「无」，而不是光秃秃的「↓ ↑」\n  const none = document.createElement('span')\n  none.className = 'tt_statsMinNone'\n  none.hidden = true\n  net.value.appendChild(down)\n  net.value.appendChild(document.createTextNode(' '))\n  net.value.appendChild(up)\n  net.value.appendChild(none)\n  statsMinRefs = { cpu, mem, net, down, up, none, ping, swap }\n  statsScrollEl.appendChild(statsMinEl)\n}\n\n/** 历史里的一帧（趋势线要用的四个字段 + 悬浮卡片算峰值的三项；`null` = 这一帧没有该数据）。 */\nfunction pushStatsHistory(sid, stats) {\n  if (typeof sid !== 'string' || sid === '') return\n  const sample = {\n    cpuPct: statsNum(stats, 'cpuPct'),\n    memPct: statsNum(stats, 'memPct'),\n    rxRate: statsNum(stats, 'rxRate'),\n    txRate: statsNum(stats, 'txRate'),\n    // 2026-11-01 起悬浮卡片要报「近 1 分钟峰值」，所以要额外留三项；趋势线不读它们，\n    // 60 个样本 × 3 个数字，内存代价可以忽略\n    diskPct: statsNum(stats, 'diskPct'),\n    tcpConns: statsNum(stats, 'tcpConns'),\n    tempC: statsNum(stats, 'tempC'),\n    // 悬停卡片的「峰值」：Ping 要看**最差**的一次（抖动才是终端最难用的状态）\n    pingMs: statsNum(stats, 'pingMs'),\n  }\n  const list = statsHistory.get(sid) ?? []\n  list.push(sample)\n  if (list.length > STATS_HISTORY_LEN) list.splice(0, list.length - STATS_HISTORY_LEN)\n  statsHistory.set(sid, list)\n}\n\n/** 极简条的每帧刷新：三张趋势线 + 三个大数字。路径没变就不写 `d`（避免无谓的重绘）。 */\nfunction updateStatsMinimal() {\n  if (statsMinRefs === null) return\n  const tab = activeTab()\n  const raw = tab !== undefined ? tab.stats : null\n  const stats = raw !== null && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}\n  const history = tab !== undefined ? statsHistory.get(tab.sid) ?? [] : []\n  const pctText = (value) => (value === null ? t('list.none') : Math.round(value) + '%')\n  const cpu = statsNum(stats, 'cpuPct')\n  const mem = statsNum(stats, 'memPct')\n  const setPath = (ref, values, options) => {\n    const line = sparklinePath(values, 100, 16, options)\n    const area = sparklineArea(values, 100, 16, options)\n    if (ref.path.getAttribute('d') !== line) ref.path.setAttribute('d', line)\n    if (ref.area.getAttribute('d') !== area) ref.area.setAttribute('d', area)\n  }\n  setPath(statsMinRefs.cpu, history.map((sample) => sample.cpuPct), { min: 0, max: 100 })\n  setPath(statsMinRefs.mem, history.map((sample) => sample.memPct), { min: 0, max: 100 })\n  const netSeries = history.map((sample) => {\n    const values = [sample.rxRate, sample.txRate].filter((value) => value !== null)\n    return values.length === 0 ? null : Math.max(...values)\n  })\n  const peak = netSeries.reduce((max, value) => (value !== null && value > max ? value : max), 0)\n  /*\n   * 网络那条用**平方根刻度**，不是对数（2026-11-01，用户报「这个小的网络图是不是有问题，\n   * 数据没变化」）。对数在 16 单位高的缩略图上把整段压成贴顶的一条平线：量程由\n   * `netScaleCeiling` 的 ×4 阶梯给出（峰值 163 KB/s → 量程 256 KB/s），而\n   * `58K ↔ 163K` 只映射到 1.9 ↔ 0.6 单位——不足 2px 的起伏，看上去就是「没数据」。\n   * 平方根在同一个量程下给出 8.4 ↔ 3.2 单位（≈5px 起伏），既保住了同量级内的波动，\n   * 又不会像线性那样把一次突发以外的部分全压到底——与明细仪表盘的网络图同一个刻度选择，\n   * 理由与实测数字见 `test/stats-bar.test.ts` 里那条 power=0.5 的用例。\n   */\n  setPath(statsMinRefs.net, netSeries, { min: 0, max: netScaleCeiling(peak), power: 0.5 })\n  const setText = (ref, text) => {\n    if (ref.value.textContent !== text) ref.value.textContent = text\n  }\n  setText(statsMinRefs.cpu, pctText(cpu))\n  setText(statsMinRefs.mem, pctText(mem))\n  // 档位只影响配色（内存 82% 黄、≥90 红；CPU 同理，与完整模式的阈值同一份 statsLevel）\n  const level = (value) => statsLevel(value)\n  const setLevel = (ref, value) => {\n    const next = level(value)\n    if (next === '') {\n      if (ref.item.hasAttribute('data-level')) ref.item.removeAttribute('data-level')\n    } else if (ref.item.getAttribute('data-level') !== next) {\n      ref.item.setAttribute('data-level', next)\n    }\n  }\n  setLevel(statsMinRefs.cpu, cpu)\n  setLevel(statsMinRefs.mem, mem)\n  const rx = statsNum(stats, 'rxRate')\n  const tx = statsNum(stats, 'txRate')\n  const hasRates = rx !== null || tx !== null\n  statsMinRefs.down.hidden = !hasRates\n  statsMinRefs.up.hidden = !hasRates\n  statsMinRefs.none.hidden = hasRates\n  if (hasRates) {\n    if (statsMinRefs.down.textContent !== '↓' + statsRateCompact(rx)) statsMinRefs.down.textContent = '↓' + statsRateCompact(rx)\n    if (statsMinRefs.up.textContent !== '↑' + statsRateCompact(tx)) statsMinRefs.up.textContent = '↑' + statsRateCompact(tx)\n  } else {\n    if (statsMinRefs.none.textContent !== t('list.none')) statsMinRefs.none.textContent = t('list.none')\n  }\n  /*\n   * Ping / Swap：与完整条同一套「按机器能力出现」的判据（`seenItems`）与同一套取值\n   * （Ping 取整毫秒 + 手感档位；Swap 是「已用/总量」）。极简条只是少了趋势线。\n   */\n  const pingRef = statsMinRefs.ping\n  const ping = statsNum(stats, 'pingMs')\n  const pingShown = tab !== undefined && tab.seenItems !== undefined && tab.seenItems.ping === true\n  if (pingRef.item.hidden === pingShown) pingRef.item.hidden = !pingShown\n  if (pingShown) {\n    const text = ping === null ? t('list.none') : Math.round(ping) + 'ms'\n    if (pingRef.value.textContent !== text) pingRef.value.textContent = text\n    const tone = ping === null ? '' : ping < 120 ? 'ok' : ping < 300 ? 'warn' : 'danger'\n    if ((pingRef.value.dataset.level ?? '') !== tone) {\n      if (tone === '') delete pingRef.value.dataset.level\n      else pingRef.value.dataset.level = tone\n    }\n  }\n  const swapRef = statsMinRefs.swap\n  const swapShown = tab !== undefined && tab.seenItems !== undefined && tab.seenItems.swap === true\n  if (swapRef.item.hidden === swapShown) swapRef.item.hidden = !swapShown\n  if (swapShown) {\n    const text = statsPair(statsNum(stats, 'swapUsed'), statsNum(stats, 'swapTotal'), t)\n    if (swapRef.value.textContent !== text) swapRef.value.textContent = text\n  }\n}\n\n/* ---------------- 状态条右侧的「负载 / 时钟」（2026-11-01） ---------------- */\n\n/**\n * 条的最右边、▾ 左边的固定一格：**1 分钟负载 + 本地时钟**。\n *\n * 为什么挂在滚动区**外面**：条目区回答的是「这台机器有什么」，负载也属于同一类信息，但它不该\n * 被挤走——放进滚动区，条一窄就滚没了；放外面就一直在。代价是它占固定宽度，所以窄面板下按时钟 →\n * 负载的顺序让位（见 CSS 的 `@container`）。\n *\n * 时钟走自己的 1s 定时器、**不挂 stats 帧**：宿主采样慢的时候（SSH 上 4s 一帧）挂在帧上的时钟\n * 会每 4 秒跳 4 下。\n */\nlet statsExtraEl = null\nlet statsExtraRefs = null\nlet statsClockTimer = null\n\nfunction ensureStatsExtra() {\n  if (statsBarEl === null) return\n  if (statsExtraEl !== null && statsExtraEl.isConnected) return\n  const group = document.createElement('div')\n  group.className = 'tt_statsExtra'\n  const load = document.createElement('span')\n  load.className = 'tt_statsExtraItem tt_statsLoad'\n  load.hidden = true\n  const loadLabel = document.createElement('span')\n  loadLabel.className = 'tt_statsExtraLabel'\n  loadLabel.textContent = t('meta.load')\n  const loadValue = document.createElement('span')\n  loadValue.className = 'tt_statsExtraValue'\n  load.appendChild(loadLabel)\n  load.appendChild(loadValue)\n  const clock = document.createElement('span')\n  clock.className = 'tt_statsExtraItem tt_statsClock'\n  group.appendChild(load)\n  group.appendChild(clock)\n  /*\n   * 插在 ▾ **前面**：那颗按钮固定在条的最右端（不随条目滚动），这一组挨着它——\n   * 平时看上去是「…… 网络 ↓1.2M ↑300K │ 负载 0.15 │ 10:45:23  ▾」。\n   */\n  if (statsExpandEl !== null && statsExpandEl.parentNode === statsBarEl) statsBarEl.insertBefore(group, statsExpandEl)\n  else statsBarEl.appendChild(group)\n  statsExtraEl = group\n  statsExtraRefs = { load, loadValue, clock }\n}\n\n/** 每帧写一次：负载缺失时整格隐藏（Windows 本地没有 loadavg，不显示 0.00）。 */\nfunction updateStatsExtra(tab) {\n  ensureStatsExtra()\n  if (statsExtraRefs === null) return\n  const stats = tab !== undefined && tab.stats !== null && typeof tab.stats === 'object' && !Array.isArray(tab.stats) ? tab.stats : null\n  const load1 = stats === null ? null : statsNum(stats, 'load1')\n  const text = load1 === null ? '' : load1.toFixed(2)\n  if (statsExtraRefs.loadValue.textContent !== text) statsExtraRefs.loadValue.textContent = text\n  const loadHidden = load1 === null\n  if (statsExtraRefs.load.hidden !== loadHidden) statsExtraRefs.load.hidden = loadHidden\n  const now = clockText(new Date())\n  if (statsExtraRefs.clock.textContent !== now) statsExtraRefs.clock.textContent = now\n  // 写完才让位：让位判据读的是真实布局，必须在负载 / 时钟的文本都落进去之后\n  fitStatsBar()\n}\n\n/**\n * 状态条让位：按 `YIELD_ORDER` **一条**阶梯逐级藏，直到条不溢出。\n *\n * 为什么不能只靠横向滚动：溢出时**最后一个值会被切一半**（`↑57.0 KB/`），看上去像坏了；\n * 而状态条是「一眼扫完」的东西，不该要求用户去横滚。\n * 为什么判据是**真实的溢出**而不是算宽度：条目总宽随值变（网络那格有速率才占 23ch，\n * 在线时长会从 `3h2m` 长到 `2w4d7h16m`），同样 1280 宽的面板有时塞得下、有时塞不下。\n * 每帧都从「全显示」重算——窗口变宽 / 切回完整模式要能自动长回来；全部读写都在同一个任务里\n * 完成，浏览器还没 paint，用户看不到中间态。\n * 调用频率是每帧一次（≈1s）外加时钟自己的 1s 复算（见 `tickStatsClock`）。\n */\nfunction fitStatsBar() {\n  if (statsScrollEl === null) return\n  const overflow = () => statsScrollEl.scrollWidth > statsScrollEl.clientWidth + 1\n  const itemRef = (key) => {\n    if (statsItemEls === null) return undefined\n    return statsItemEls.find((ref) => ref.key === key)\n  }\n  for (const key of YIELD_ITEM_KEYS) {\n    const ref = itemRef(key)\n    if (ref !== undefined) ref.item.hidden = false\n  }\n  if (statsExtraEl !== null && statsExtraRefs !== null) {\n    statsExtraEl.hidden = false\n    statsExtraRefs.clock.hidden = false\n  }\n  if (!overflow()) return\n  for (const step of YIELD_ORDER) {\n    if (step === 'clock') {\n      if (statsExtraRefs === null) continue\n      statsExtraRefs.clock.hidden = true\n    } else if (step === 'extra') {\n      if (statsExtraEl === null) continue\n      statsExtraEl.hidden = true\n    } else {\n      const ref = itemRef(step)\n      if (ref === undefined) continue\n      ref.item.hidden = true\n    }\n    if (!overflow()) return\n  }\n}\n\nfunction tickStatsClock() {\n  if (statsExtraRefs === null) return\n  const now = clockText(new Date())\n  if (statsExtraRefs.clock.textContent !== now) statsExtraRefs.clock.textContent = now\n  /*\n   * 让位判据**也要在定时器里重算**：stats 帧可能很稀（SSH 上 4s 一帧），只挂在帧上时，\n   * 一次瞬时布局（刚切回完整模式、值还没填进去）会把某一级按住不放，而后续没有帧来纠正它。\n   * 每秒钟复算一次就能收敛，代价是最多五次布局读取（阶梯每走一级读一次）。\n   */\n  fitStatsBar()\n}\n\nfunction ensureStatsClockTimer() {\n  if (statsClockTimer !== null) return\n  statsClockTimer = setInterval(tickStatsClock, 1000)\n}\n\nfunction stopStatsClockTimer() {\n  if (statsClockTimer === null) return\n  clearInterval(statsClockTimer)\n  statsClockTimer = null\n}\n\n/* ---------------- 状态条条目的悬浮提示（2026-11-01） ---------------- */\n\n/*\n * 条目的悬停卡片：`当前 / 峰值 / 上下文`（用户提议，参考 FinalShell 的服务器状态浮窗）。\n *\n * 为什么不用原生 `title`：它慢（约 1s）、样式不可控、只放得下一行「CPU: 18%」，而这里要\n * 同时说「现在多少 / 刚才最高多少 / 几核」。所以条目改挂 `aria-label`（至少留下一条文本，\n * 辅助技术读得到；这些格子本身不是交互控件），视觉信息交给这张卡片。\n *\n * 卡片**只建一次**、隐藏走 `hidden`（与状态条条目同一条纪律）：每次悬停重建 DOM 会让\n * 卡片在指针下闪一下，也会把 `data-level` 的配色过渡打断。\n */\n\n/** 悬停多久后出现：太短会在指针横扫状态条时连闪（一格只有几十像素宽），太长像卡住。 */\nconst STATS_TIP_DELAY_MS = 140\n\n/** 悬浮卡片（挂在 body 上、锚在状态条下沿）。 */\nlet statsTipEl = null\nlet statsTipRefs = null\n/** 当前展示的条目：键取自 `statsItemSpecs(t)`（极简条映射到同一组键），anchor 用于定位。 */\nlet statsTipKey = null\nlet statsTipAnchor = null\n/** 延迟显示的定时器：指针横扫状态条时要能取消。 */\nlet statsTipTimer = null\n\nfunction statsTipRow() {\n  const row = document.createElement('span')\n  row.className = 'tt_statsTipRow'\n  const label = document.createElement('span')\n  label.className = 'tt_statsTipRowLabel'\n  const value = document.createElement('span')\n  value.className = 'tt_statsTipRowValue'\n  row.appendChild(label)\n  row.appendChild(value)\n  return { row, label, value, cache: { shape: null, parts: [] } }\n}\n\n/**\n * 把一个「可能分段着色」的值写进节点：不传分段就是一个整段文本。\n *\n * 分段只在**形状变了**（有没有分段 / 各段的色调）时重建子节点，其余情况只改文本：卡片每秒\n * 都在刷，每帧重建会让那两段箭头在指针下面闪一下。形状记忆挂在调用方传进来的 `cache` 上，\n * 与节点同生命周期。\n */\nfunction paintStatsTipText(el, text, segments, cache) {\n  const list = Array.isArray(segments) ? segments : []\n  const shape = list.length === 0 ? '' : list.map((part) => part.tone || '').join('|')\n  if (cache.shape !== shape) {\n    cache.shape = shape\n    cache.parts = []\n    el.textContent = ''\n    for (const part of list) {\n      const span = document.createElement('span')\n      // 空色调那一段就是分隔符（网络那两段中间的空格），不必多包一层类名\n      if (part.tone !== '') span.className = 'tt_statsTipPart tt_statsTipPart--' + part.tone\n      el.appendChild(span)\n      cache.parts.push(span)\n    }\n    if (list.length === 0) el.textContent = text\n  }\n  if (list.length === 0) {\n    if (el.textContent !== text) el.textContent = text\n    return\n  }\n  for (let index = 0; index < list.length; index += 1) {\n    const span = cache.parts[index]\n    if (span.textContent !== list[index].text) span.textContent = list[index].text\n  }\n}\n\nfunction ensureStatsTipEl() {\n  if (statsTipEl !== null) {\n    if (statsTipEl.isConnected) return\n    // 被外部移出文档（宿主重渲染 / 手改 DOM）：旧节点连同它的 resize 监听一起扔掉重建，\n    // 不能只新建一颗——那样每重建一次就多挂一个 window 监听\n    window.removeEventListener('resize', positionStatsTip, false)\n    statsTipEl.remove()\n    statsTipEl = null\n    statsTipRefs = null\n  }\n  const tip = document.createElement('div')\n  tip.className = 'tt_statsTip'\n  tip.setAttribute('role', 'tooltip')\n  tip.hidden = true\n  const head = document.createElement('div')\n  head.className = 'tt_statsTipHead'\n  const label = document.createElement('span')\n  label.className = 'tt_statsTipLabel'\n  const value = document.createElement('span')\n  value.className = 'tt_statsTipValue'\n  head.appendChild(label)\n  head.appendChild(value)\n  const meta = document.createElement('div')\n  meta.className = 'tt_statsTipMeta'\n  meta.hidden = true\n  const foot = document.createElement('div')\n  foot.className = 'tt_statsTipFoot'\n  foot.hidden = true\n  tip.appendChild(head)\n  tip.appendChild(meta)\n  tip.appendChild(foot)\n  document.body.appendChild(tip)\n  statsTipRefs = { label, value, valueCache: { shape: null, parts: [] }, meta, foot, rows: [] }\n  statsTipEl = tip\n  window.addEventListener('resize', positionStatsTip, false)\n}\n\n/** 把模型写进卡片：只改真的变了的文本（每帧都会经过这里）。 */\nfunction paintStatsTip(model) {\n  if (statsTipEl === null || statsTipRefs === null) return\n  const refs = statsTipRefs\n  if (refs.label.textContent !== model.label) refs.label.textContent = model.label\n  paintStatsTipText(refs.value, model.value, model.segments, refs.valueCache)\n  const level = typeof model.level === 'string' ? model.level : ''\n  if ((statsTipEl.dataset.level ?? '') !== level) {\n    if (level === '') delete statsTipEl.dataset.level\n    else statsTipEl.dataset.level = level\n  }\n  // 行数随条目变（CPU 两行、在线没有次要行）：池化复用，只增删差额\n  while (refs.rows.length < model.rows.length) {\n    const built = statsTipRow()\n    refs.meta.appendChild(built.row)\n    refs.rows.push(built)\n  }\n  for (let index = refs.rows.length - 1; index >= model.rows.length; index -= 1) {\n    refs.rows[index].row.remove()\n    refs.rows.pop()\n  }\n  for (let index = 0; index < model.rows.length; index += 1) {\n    const target = refs.rows[index]\n    const next = model.rows[index]\n    if (target.label.textContent !== next.label) target.label.textContent = next.label\n    paintStatsTipText(target.value, next.value, next.segments, target.cache)\n  }\n  refs.meta.hidden = model.rows.length === 0\n  if (refs.foot.textContent !== model.foot) refs.foot.textContent = model.foot\n  refs.foot.hidden = model.foot === ''\n}\n\n/**\n * 贴着状态条下沿、居中对齐到条目。\n *\n * 为什么是**下方**而不是图二那样浮在上方：状态条在本面板里顶在终端区最上面（上面紧挨着\n * 标签栏），朝上弹会盖住标签页签；朝下弹正好落在终端区那一片暗底上，与明细仪表盘同一侧。\n *\n * 边界先按**面板**收窄再夹视口（与 `positionStatsDash` 同一个理由：面板通常比视口窄，\n * 只按 innerWidth 夹会让卡片伸到面板外面，压在应用背景上）。\n */\nfunction positionStatsTip() {\n  if (statsTipEl === null || statsTipAnchor === null || statsTipEl.hidden) return\n  const anchor = statsTipAnchor.getBoundingClientRect()\n  const bar = statsBarEl !== null ? statsBarEl.getBoundingClientRect() : anchor\n  // 夹边界的对象是**面板本身**（`.tt_modal`），不是它的全屏背衬（`.tt_modalBackdrop`，\n  // 那是 inset:0）——按背衬夹等于没夹，卡片会伸出面板右缘、压在应用背景上\n  const panelEl = modalEl !== null ? modalEl.querySelector('.tt_modal') : null\n  const panel = panelEl !== null ? panelEl.getBoundingClientRect() : bar\n  const width = statsTipEl.offsetWidth\n  const height = statsTipEl.offsetHeight\n  const minLeft = Math.max(8, panel.left + 8)\n  const maxLeft = Math.min(window.innerWidth - width - 8, panel.right - width - 8)\n  const left = Math.max(minLeft, Math.min(anchor.left + anchor.width / 2 - width / 2, maxLeft))\n  // 视口太矮时兜底贴顶：宁可压住状态条，也不让最后一行掉到视口外\n  const maxTop = Math.max(8, window.innerHeight - height - 8)\n  statsTipEl.style.left = String(Math.round(left)) + 'px'\n  statsTipEl.style.top = String(Math.round(Math.min(bar.bottom + 6, maxTop))) + 'px'\n}\n\n/** 条目 → `statsItemSpecs(t)` 的键（极简条只有 cpu / mem / net 三种，映射到同一组键）。 */\nfunction statsTipKeyFor(item) {\n  if (item.classList.contains('tt_statsMinItem')) {\n    const kind = item.dataset.kind\n    if (kind === 'cpu') return 'cpuPct'\n    if (kind === 'mem') return 'mem'\n    if (kind === 'net') return 'net'\n    return null\n  }\n  if (statsFullEl === null) return null\n  const specs = statsItemSpecs(t)\n  const index = Array.prototype.indexOf.call(statsFullEl.children, item)\n  return index >= 0 && index < specs.length ? specs[index].key : null\n}\n\nfunction showStatsTip(item) {\n  const key = statsTipKeyFor(item)\n  if (key === null) {\n    hideStatsTip()\n    return\n  }\n  statsTipKey = key\n  statsTipAnchor = item\n  ensureStatsTipEl()\n  if (statsTipEl === null) return\n  statsTipEl.hidden = false\n  refreshStatsTip()\n}\n\n/** 卡片跟着本帧刷新（没弹着就是一次 null 判断）。 */\nfunction refreshStatsTip() {\n  if (statsTipEl === null || statsTipKey === null || statsTipAnchor === null) return\n  const tab = activeTab()\n  const stats = tab !== undefined ? tab.stats : null\n  const history = tab !== undefined ? statsHistory.get(tab.sid) ?? [] : []\n  const model = statsTipModel(statsTipKey, stats, history, t)\n  // 这一格根本没有数据（macOS 的温度 / 采集失败的帧）：不弹一张只有「当前 无」的卡片\n  if (model.empty || statsTipAnchor.isConnected !== true) {\n    hideStatsTip()\n    return\n  }\n  paintStatsTip(model)\n  positionStatsTip()\n}\n\nfunction hideStatsTip() {\n  if (statsTipTimer !== null) {\n    clearTimeout(statsTipTimer)\n    statsTipTimer = null\n  }\n  statsTipKey = null\n  statsTipAnchor = null\n  if (statsTipEl !== null) statsTipEl.hidden = true\n}\n\n/** 面板关闭时连元素一起摘掉（`hideStatsTip` 只隐藏）。 */\nfunction destroyStatsTip() {\n  hideStatsTip()\n  if (statsTipEl !== null) {\n    window.removeEventListener('resize', positionStatsTip, false)\n    statsTipEl.remove()\n    statsTipEl = null\n  }\n  statsTipRefs = null\n}\n\n/** 指针进入条目：延迟一下再弹（横扫状态条时不该连闪）。 */\nfunction onStatsPointerOver(event) {\n  const target = event.target\n  if (!(target instanceof Element)) return\n  const item = target.closest('.tt_statsItem, .tt_statsMinItem')\n  if (item === null || item === statsTipAnchor) return\n  if (statsTipTimer !== null) clearTimeout(statsTipTimer)\n  statsTipTimer = setTimeout(() => {\n    statsTipTimer = null\n    showStatsTip(item)\n  }, STATS_TIP_DELAY_MS)\n}\n\n/** 指针离开条目：立即收起；在条目**内部**（标签 ↔ 进度条 ↔ 值）移动不算离开。 */\nfunction onStatsPointerOut(event) {\n  const target = event.target\n  if (!(target instanceof Element)) return\n  const item = target.closest('.tt_statsItem, .tt_statsMinItem')\n  if (item === null) return\n  const next = event.relatedTarget\n  if (next instanceof Node && item.contains(next)) return\n  if (item !== statsTipAnchor) {\n    if (statsTipTimer !== null) {\n      clearTimeout(statsTipTimer)\n      statsTipTimer = null\n    }\n    return\n  }\n  hideStatsTip()\n}\n\n/* ---------------- 明细仪表盘（悬浮卡片，2026-10-31） ---------------- */\n\nconst SVG_NS = 'http://www.w3.org/2000/svg'\n/** 明细图（网络）的 viewBox：宽度按卡片等比拉伸，高度固定 64。 */\nconst DASH_CHART_W = 240\nconst DASH_CHART_H = 64\n\nfunction svgEl(tag, className, attrs) {\n  const node = document.createElementNS(SVG_NS, tag)\n  if (className !== undefined && className !== '') node.setAttribute('class', className)\n  for (const key of Object.keys(attrs ?? {})) node.setAttribute(key, attrs[key])\n  return node\n}\n\n/** 状态条最右端那颗 ▴：展开 / 收起明细仪表盘。 */\nfunction onStatsExpandClick() {\n  if (statsDashEl !== null) closeStatsDash()\n  else openStatsDash()\n}\n\n/**\n * 展开按钮的「三件套」跟着状态走：箭头方向、tooltip、`aria-label`（外加 `aria-expanded`）。\n *\n * 图标不翻方向是用户实际提的第二个问题（原话「展开/折叠面板图标应有变化 ^ 和倒 ^」）：\n * 收起态与展开态画同一个 ▴，看得见的人只能靠「面板开没开」猜这颗按钮现在会做什么。\n * 箭头在**收起态朝上、展开态朝下**——与「点它把下面的卡片翻上来 / 收回去」的方向一致。\n *\n * `innerHTML` 只在状态真的翻转时才重写（其余调用点每帧都可能经过这里，无谓的\n * 重写会把按钮里的 SVG 节点反复建删，也会打断焦点环）。\n */\nfunction applyStatsExpandState(expanded) {\n  if (statsExpandEl === null) return\n  const state = expanded ? 'open' : 'closed'\n  statsExpandEl.setAttribute('aria-expanded', expanded ? 'true' : 'false')\n  // 两个键都写成字面量：i18n 闸门静态扫不到变量拼出来的键\n  const label = expanded ? t('statsDash.close') : t('statsDash.open')\n  if (statsExpandEl.title !== label) statsExpandEl.title = label\n  if (statsExpandEl.getAttribute('aria-label') !== label) statsExpandEl.setAttribute('aria-label', label)\n  if (statsExpandEl.dataset.state !== state) {\n    statsExpandEl.dataset.state = state\n    statsExpandEl.innerHTML = expanded ? ICON_STATS_COLLAPSE : ICON_STATS_EXPAND\n  }\n}\n\nfunction closeStatsDash() {\n  if (statsDashDismiss !== null) {\n    document.removeEventListener('mousedown', statsDashDismiss, true)\n    statsDashDismiss = null\n  }\n  document.removeEventListener('keydown', onStatsDashKey, true)\n  window.removeEventListener('resize', positionStatsDash, false)\n  if (statsDashEl !== null) {\n    statsDashEl.remove()\n    statsDashEl = null\n  }\n  statsDashRefs = null\n  statsDashKey = null\n  applyStatsExpandState(false)\n}\n\n/**\n * Esc 收起明细仪表盘。\n *\n * 必须走**捕获阶段**：面板级的 Esc 是「最小化面板」（onModalKeydown），冒泡阶段收浮层\n * 会被它先吃掉——实测按下 Esc，仪表盘确实关了，但面板同时被最小化，再点 ▴ 就点不到了。\n */\nfunction onStatsDashKey(event) {\n  if (event.key !== 'Escape' || statsDashEl === null) return\n  event.preventDefault()\n  event.stopPropagation()\n  closeStatsDash()\n}\n\n/**\n * 贴着状态条下沿定位；右侧对齐（它是从条的最右端展开的）。\n *\n * 边界是**面板**而不是视口：面板通常比视口窄，只按 `innerWidth` 夹的话卡片会伸出\n * 面板右边缘——那截既没有卡片底（背后是应用背景）又压着终端文字，看起来就是\n * 「文字被盖掉了一块」。所以先按面板宽度收窄，再在面板内右对齐。\n */\nfunction positionStatsDash() {\n  if (statsDashEl === null || statsBarEl === null) return\n  const bar = statsBarEl.getBoundingClientRect()\n  const panel = modalEl !== null ? modalEl.getBoundingClientRect() : bar\n  const maxWidth = Math.max(280, Math.min(720, panel.width - 16, window.innerWidth - 24))\n  if (Math.abs(statsDashEl.offsetWidth - maxWidth) > 1) statsDashEl.style.width = String(Math.round(maxWidth)) + 'px'\n  const width = statsDashEl.offsetWidth\n  // 三 / 两 / 一列：窄卡片上固定三列会横向溢出（CSS 侧按 data-cols 切模板）\n  const cols = width >= 600 ? '3' : width >= 400 ? '2' : '1'\n  if (statsDashEl.dataset.cols !== cols) statsDashEl.dataset.cols = cols\n  const minLeft = Math.max(8, panel.left + 8)\n  const maxLeft = Math.min(window.innerWidth - width - 8, panel.right - width - 8)\n  const left = Math.max(minLeft, Math.min(bar.right - width, maxLeft))\n  statsDashEl.style.top = String(Math.round(bar.bottom + 6)) + 'px'\n  statsDashEl.style.left = String(Math.round(left)) + 'px'\n}\n\nfunction openStatsDash() {\n  if (modalEl === null || statsBarEl === null || statsBarEl.hidden) return\n  closeStatsDash()\n  // 两张浮层锚在同一根条上，同时开只会互相压住：开仪表盘就收起悬停卡片\n  hideStatsTip()\n  const pop = document.createElement('div')\n  pop.className = 'tt_statsDash'\n  pop.setAttribute('role', 'dialog')\n  pop.setAttribute('aria-label', t('statsDash.title'))\n  const refs = { cores: null, net: null, procs: null }\n  pop.appendChild(buildCoresCard(refs))\n  pop.appendChild(buildNetCard(refs))\n  pop.appendChild(buildProcsCard(refs))\n  document.body.appendChild(pop)\n  statsDashEl = pop\n  statsDashRefs = refs\n  positionStatsDash()\n  applyStatsExpandState(true)\n  updateStatsDash()\n  const dismiss = (event) => {\n    if (statsDashEl === null) return\n    if (pop.contains(event.target)) return\n    // 点状态条本身不算「点外面」：那颗 ▴ 要能把面板关掉（否则会先关再被自己打开）\n    if (statsBarEl !== null && statsBarEl.contains(event.target)) return\n    closeStatsDash()\n  }\n  statsDashDismiss = dismiss\n  setTimeout(() => document.addEventListener('mousedown', dismiss, true), 0)\n  document.addEventListener('keydown', onStatsDashKey, true)\n  window.addEventListener('resize', positionStatsDash, false)\n}\n\n/** 卡片的公共外壳：标题 + 右上角状态 + 主体 + 脚注。 */\nfunction buildDashCard(refs, kind, titleText, metaText) {\n  const card = document.createElement('div')\n  card.className = 'tt_statsDashCard'\n  card.dataset.card = kind\n  const head = document.createElement('div')\n  head.className = 'tt_statsDashHead'\n  const title = document.createElement('span')\n  title.className = 'tt_statsDashTitle'\n  title.textContent = titleText\n  const meta = document.createElement('span')\n  meta.className = 'tt_statsDashMeta'\n  meta.textContent = metaText\n  head.appendChild(title)\n  head.appendChild(meta)\n  card.appendChild(head)\n  const body = document.createElement('div')\n  body.className = 'tt_statsDashBody'\n  card.appendChild(body)\n  const empty = document.createElement('div')\n  empty.className = 'tt_statsDashEmpty'\n  empty.hidden = true\n  card.appendChild(empty)\n  const foot = document.createElement('div')\n  foot.className = 'tt_statsDashFoot'\n  card.appendChild(foot)\n  return { card, head, title, meta, body, empty, foot }\n}\n\n/**\n * 面积的纵向褪色渐变（顶端不透明 → 底部全透明）。`stops` 由调用方给：\n * CPU 折线要「极其淡的一抹底色」，网络那块面积大得多，同样的透明度已经读得出分量。\n *\n * `gradientUnits=\"userSpaceOnUse\"` 是必须的：默认的 `objectBoundingBox` 会跟着每帧变化的\n * 路径外框重算，曲线一低整条渐变就被拉伸，看起来像在呼吸。\n */\nfunction dashFadeGradient(id, stops) {\n  const gradient = svgEl('linearGradient', 'tt_statsDashFade', { id, gradientUnits: 'userSpaceOnUse', x1: '0', y1: '0', x2: '0', y2: String(DASH_CHART_H) })\n  for (const [offset, opacity] of stops) {\n    gradient.appendChild(svgEl('stop', '', { offset, 'stop-opacity': opacity }))\n  }\n  return gradient\n}\n\n/**\n * 折线的**横向**「时间流向」渐变：左端（过去）只给 34% 不透明度，右端（最新一帧）给满。\n *\n * 只用不透明度阶梯、色相交给 `currentColor`，理由有二：\n *   ① 深色卡片上「暗」本来就等于「更透」，同一色相 34%→100% 读出来就是「过去 → 现在」，\n *      右端天然更亮，视线会被带到最新的一帧；\n *   ② 告警态只改一个 `color`（见 CSS 的 `[data-alert]`），折线、光晕、面积三处一起换色，\n *      不必在 JS 里维护第二套色值（客户端半体的配色来源闸门也不允许写字面量）。\n * 光晕用的 `currentColor` 同理：它取的是元素自己的 `color`，与渐变末端同源。\n *\n * @param {string} id 渐变 id（同一文档里多张卡片不能撞）\n * @param {string} [hue] `rx` / `tx` 时按网络那一对色写死；CPU 折线不传（跟着告警态走）\n */\nfunction dashFlowGradient(id, hue) {\n  const gradient = svgEl('linearGradient', 'tt_statsDashFlow', { id, gradientUnits: 'userSpaceOnUse', x1: '0', y1: '0', x2: String(DASH_CHART_W), y2: '0' })\n  if (hue !== undefined && hue !== '') gradient.dataset.hue = hue\n  for (const [offset, opacity] of [['0', '.34'], ['0.55', '.76'], ['1', '1']]) {\n    gradient.appendChild(svgEl('stop', '', { offset, 'stop-opacity': opacity }))\n  }\n  return gradient\n}\n\nfunction buildCoresCard(refs) {\n  const shell = buildDashCard(refs, 'cores', t('statsDash.cores'), '')\n  shell.body.className = 'tt_statsDashBody tt_statsDashCores'\n  // 标题 + 档位（「正常 / 偏高 / 过载」）贴在一起：这档说的是本卡片的每核柱，\n  // 原来右对齐飘到网络卡片左边，读起来像是在说网络\n  shell.head.className = 'tt_statsDashHead tt_statsDashHead--tight'\n  /*\n   * 80% 警戒线：柱状图没有 Y 轴刻度，光看高低分不出「一半高」是 50% 还是 80%。\n   * 位置取 `STATS_WARN_LIMIT`——必须与「柱子变橙」的那一档是同一个数，否则会出现\n   * 「过了虚线却还是绿的」这种自相矛盾的画面。它是 `position: absolute` 的，\n   * 不参与 flex 布局，也不吃鼠标事件。\n   */\n  const guide = document.createElement('span')\n  guide.className = 'tt_statsDashGuide'\n  // 位置取 `STATS_WARN_LIMIT`：这条虚线就是柱子变橙的那一档，不能各写一个数\n  guide.style.bottom = String(STATS_WARN_LIMIT) + '%'\n  shell.body.appendChild(guide)\n  shell.empty.textContent = t('statsDash.noCores')\n  shell.empty.title = t('statsDash.noCoresHint')\n  refs.cores = { ...shell, bars: [], guide }\n  return shell.card\n}\n\nfunction buildNetCard(refs) {\n  const shell = buildDashCard(refs, 'net', t('statsDash.net'), t('statsDash.lastMin'))\n  /*\n   * 图例：两条线的色相本来就挨着（蓝 / 青）又都带光晕，交叉的地方根本认不出谁是谁。\n   * 分法有两层——**结构上**下行实线、上行虚线（不只靠颜色），再把图例贴在同一行的中间，\n   * 色条与曲线同色同虚实，一眼对得上。\n   * 图例是纯装饰（`aria-hidden`）：数字与 ↓/↑ 已经在脚注里，屏幕阅读器不用再念一遍。\n   */\n  const legend = document.createElement('span')\n  legend.className = 'tt_statsDashLegend'\n  legend.setAttribute('aria-hidden', 'true')\n  for (const kind of ['down', 'up']) {\n    const key = document.createElement('span')\n    key.className = 'tt_statsDashKey'\n    key.dataset.kind = kind\n    key.textContent = kind === 'down' ? '↓' : '↑'\n    legend.appendChild(key)\n  }\n  shell.head.insertBefore(legend, shell.meta)\n  const svg = svgEl('svg', 'tt_statsDashChart', { viewBox: '0 0 ' + String(DASH_CHART_W) + ' ' + String(DASH_CHART_H), preserveAspectRatio: 'none', 'aria-hidden': 'true', 'data-series': 'net' })\n  const seq = ++statsSparkGradientSeq\n  const fadeId = 'tt-dash-fade-' + String(seq)\n  const rxFlowId = 'tt-dash-flow-rx-' + String(seq)\n  const txFlowId = 'tt-dash-flow-tx-' + String(seq)\n  const defs = svgEl('defs', '', {})\n  /*\n   * 面积从 .40 收到 .30（2026-11-01）：这块面积占满 96px 高的整张卡片，同样一片底色\n   * 在视觉上比 CPU 那条 64px 的折线重得多——「网络图太沉、CPU 太飘」就是这么来的。\n   * 两条折线各配一条自己的「时间流向」渐变（`data-hue` 定色，见 CSS）。\n   */\n  defs.appendChild(dashFadeGradient(fadeId, [['0', '.30'], ['0.5', '.10'], ['1', '0']]))\n  defs.appendChild(dashFlowGradient(rxFlowId, 'rx'))\n  defs.appendChild(dashFlowGradient(txFlowId, 'tx'))\n  svg.appendChild(defs)\n  const area = svgEl('path', 'tt_statsDashArea', { fill: 'url(#' + fadeId + ')' })\n  const rxLine = svgEl('path', 'tt_statsDashLine', { 'data-kind': 'rx', stroke: 'url(#' + rxFlowId + ')', 'vector-effect': 'non-scaling-stroke' })\n  const txLine = svgEl('path', 'tt_statsDashLine', { 'data-kind': 'tx', stroke: 'url(#' + txFlowId + ')', 'vector-effect': 'non-scaling-stroke' })\n  svg.appendChild(area)\n  /*\n   * 两条参考横线（1/3、2/3 高）：纯视觉刻度，不标数值——数值在脚注里给峰值。\n   * 顺序是「面积 → 参考线 → 折线」：压在面积**里面**会被那块渐变盖掉（面积自上而下\n   * 由深到无），放在折线之前又保证曲线永远在网格之上。\n   * 取 1/3、2/3 而不是 1/4、3/4：隔壁 CPU 卡片有一条 80% 的警戒虚线，两条线高度太近时\n   * 看上去像一根贯穿两张卡片的虚线。\n   */\n  for (const ratio of [1 / 3, 2 / 3]) {\n    svg.appendChild(svgEl('line', 'tt_statsDashGrid', { x1: '0', y1: String(DASH_CHART_H * ratio), x2: String(DASH_CHART_W), y2: String(DASH_CHART_H * ratio) }))\n  }\n  // 下行最后画（压在上面）：它是主序列——更粗、发光、底下还垫着面积\n  svg.appendChild(txLine)\n  svg.appendChild(rxLine)\n  shell.body.className = 'tt_statsDashBody tt_statsDashChartWrap'\n  shell.body.appendChild(svg)\n  shell.empty.textContent = t('statsDash.netNone')\n  refs.net = { ...shell, svg, area, rxLine, txLine }\n  return shell.card\n}\n\nfunction buildProcsCard(refs) {\n  const shell = buildDashCard(refs, 'procs', t('statsDash.procs'), '')\n  /*\n   * 列头拆成两格、且**可点**（切排序），宽度取与数据行同一对变量\n   * （`--tt-proc-cpu-w` / `--tt-proc-mem-w`）：原先是一整串「CPU / 内存」右对齐，\n   * 斜杠的位置与下面两列的间距对不上，读起来是散的。\n   *\n   * 用 `<button>` 而不是给 span 绑 click：键盘能 Tab 到、能按空格/回车触发（这是本包\n   * 唯一一个「改了就会重排整张卡片」的控件，不该只服务鼠标）。类名刻意不带 `btn`——\n   * 它不是宿主 Button 原语的一档，而是一个贴在列头上的文本控件（client-style-spec\n   * 的按钮族只识别类名带 btn 的那些）。\n   */\n  shell.meta.className = 'tt_statsDashMeta tt_statsDashCols'\n  shell.meta.textContent = ''\n  const labels = {}\n  for (const key of ['cpu', 'mem']) {\n    const label = document.createElement('button')\n    label.type = 'button'\n    label.className = 'tt_statsDashSort'\n    label.dataset.sort = key\n    label.addEventListener('click', () => onProcsSortClick(key))\n    shell.meta.appendChild(label)\n    labels[key] = label\n  }\n  shell.body.className = 'tt_statsDashBody tt_statsDashProcs'\n  shell.empty.textContent = t('statsDash.noProcs')\n  shell.empty.title = t('statsDash.noProcsHint')\n  refs.procs = { ...shell, rows: [], labels, signature: '', sortKey: '' }\n  applyProcsSortLabels(refs.procs)\n  return shell.card\n}\n\n/**\n * 把当前排序状态写进列头与脚注：活跃列显示方向箭头（▼ 降序 / ▲ 升序），另一列不带箭头；\n * 脚注跟着说「按内存 升序 · 5 秒刷新」。\n *\n * 只改文本与 `data-active`，不重建节点（列头节点在卡片生命周期里是常驻的）。\n */\nfunction applyProcsSortLabels(ref) {\n  if (ref === null || ref === undefined) return\n  const mark = statsDashSort.dir === 'desc' ? ' ▼' : ' ▲'\n  for (const key of ['cpu', 'mem']) {\n    const label = ref.labels[key]\n    if (label === undefined) continue\n    const active = statsDashSort.key === key\n    // i18n 键写成字面量（闸门静态扫不到变量拼出来的键）\n    const name = key === 'cpu' ? t('statsDash.colCpu') : t('statsDash.colMem')\n    const text = active ? name + mark : name\n    if (label.textContent !== text) label.textContent = text\n    if (active) {\n      if (label.dataset.active !== 'true') label.dataset.active = 'true'\n      label.setAttribute('aria-pressed', 'true')\n    } else {\n      if (label.hasAttribute('data-active')) label.removeAttribute('data-active')\n      label.setAttribute('aria-pressed', 'false')\n    }\n  }\n  // i18n 键写成字面量：同上\n  const keyText = statsDashSort.key === 'cpu' ? t('statsDash.colCpu') : t('statsDash.colMem')\n  const dirText = statsDashSort.dir === 'desc' ? t('statsDash.sortDesc') : t('statsDash.sortAsc')\n  const foot = t('statsDash.procsFoot', { key: keyText, dir: dirText })\n  if (ref.foot.textContent !== foot) ref.foot.textContent = foot\n}\n\n/** 点列头：同列翻方向、换列回到降序；然后立刻重画一帧（不等下一个 stats 帧）。 */\nfunction onProcsSortClick(key) {\n  const next = nextProcSort(statsDashSort, key)\n  if (next.key === statsDashSort.key && next.dir === statsDashSort.dir) return\n  statsDashSort = next\n  if (statsDashRefs !== null) applyProcsSortLabels(statsDashRefs.procs)\n  // 签名清掉：同一帧数据也要重画（否则 `statsDashKey` 没变会直接 return）\n  statsDashKey = null\n  updateStatsDash()\n}\n\n/**\n * 量宽函数（给 `truncateMiddle` 用）：把元素当前的字体抓进一个离屏 canvas，\n * 之后按字符量宽度。字体串变了（主题 / 缩放 / 用户改字号）就重建。\n *\n * 为什么不用「字符数」硬算：终端等宽字体里中文与英文都是 1ch，但**比例字体下的回退**\n * （CJK 名字走 PingFang）宽度并不等宽；`measureText` 是唯一不会算错的量法。\n * canvas 不可用（极老的 WebView）时返回 null，调用方退回 CSS 省略号。\n */\nlet dashMeasure = null\nfunction dashTextMeasure(el) {\n  if (typeof document === 'undefined' || document.createElement === undefined) return null\n  const style = getComputedStyle(el)\n  const font = style.fontStyle + ' ' + style.fontWeight + ' ' + style.fontSize + ' ' + style.fontFamily\n  if (dashMeasure === null || dashMeasure.font !== font) {\n    const ctx = document.createElement('canvas').getContext('2d')\n    if (ctx === null || ctx === undefined) return null\n    ctx.font = font\n    dashMeasure = { font, ctx }\n  }\n  const ctx = dashMeasure.ctx\n  return (text) => ctx.measureText(text).width\n}\n\n/** 只有仪表盘开着时才跑：关着就没有额外 DOM 工作。 */\nfunction updateStatsDash() {\n  if (statsDashEl === null || statsDashRefs === null) return\n  const tab = activeTab()\n  if (tab === undefined) {\n    closeStatsDash()\n    return\n  }\n  // 跟着每帧重新锚一次：面板宽度变化 / 浏览器窗口缩放 / 标签条重排都会让旧坐标失效\n  positionStatsDash()\n  const key = tab.sid + ':' + String(tab.statsAt || 0)\n  if (key === statsDashKey) return\n  statsDashKey = key\n  const raw = tab.stats\n  const stats = raw !== null && typeof raw === 'object' && !Array.isArray(raw) ? raw : {}\n  updateCoresCard(statsDashRefs.cores, stats)\n  updateNetCard(statsDashRefs.net, tab)\n  updateProcsCard(statsDashRefs.procs, stats)\n}\n\n/**\n * 每核柱：柱高是该核本帧的占用，档位色 80/90（`statsLevel`），标题报**最差那一核**的档位\n * （16 核里有一核烧到 95%，平均值会把它摊平）。\n *\n * 为什么**不**在这一格里再画一条总量折线（2026-11-01 试过，同日撤回）：曲线要 64px、\n * 柱子只能压到 24px，而 60 秒窗口刚打开时大半是空的——用户看到的是「一条贴在右边缘的\n * 短折线」加「一排很矮的柱子」，两个都看不清。这一格只做一件事：哪一核在顶。\n */\nfunction updateCoresCard(ref, stats) {\n  const cores = Array.isArray(stats.cpuCores) ? stats.cpuCores.filter((value) => typeof value === 'number' && Number.isFinite(value)) : []\n  const has = cores.length > 0\n  ref.empty.hidden = has\n  ref.body.hidden = !has\n  if (!has) {\n    ref.meta.textContent = ''\n    ref.meta.removeAttribute('data-level')\n    ref.foot.textContent = ''\n    return\n  }\n  // 核心数变了才重建柱状（热插拔 / 从「无数据」恢复）\n  if (ref.bars.length !== cores.length) {\n    // 只清子节点、保留 body 本身：父级宽度与 flex 布局不会在这一帧抖动\n    while (ref.body.firstChild !== null) ref.body.removeChild(ref.body.firstChild)\n    ref.bars = cores.map((_value, index) => {\n      const bar = document.createElement('span')\n      bar.className = 'tt_statsDashCore'\n      bar.dataset.index = String(index + 1)\n      const fill = document.createElement('span')\n      fill.className = 'tt_statsDashCoreFill'\n      bar.appendChild(fill)\n      ref.body.appendChild(bar)\n      return { bar, fill, value: null, level: null }\n    })\n    // 警戒线绝对定位、不参与布局，清场时会跟着被删掉——放回**最后**，让它画在柱子之上\n    // （叠在下面的话，只有柱子之间那 3px 的缝看得见，等于没有）\n    if (ref.guide !== undefined && ref.guide !== null) ref.body.appendChild(ref.guide)\n  }\n  for (let index = 0; index < cores.length; index += 1) {\n    const barRef = ref.bars[index]\n    const pct = cores[index]\n    if (barRef.value !== pct) {\n      barRef.value = pct\n      barRef.fill.style.height = String(Math.max(0, Math.min(100, pct)).toFixed(1)) + '%'\n      const tip = t('statsDash.coreTip', { index: index + 1, pct: Math.round(pct) })\n      if (barRef.bar.getAttribute('title') !== tip) barRef.bar.setAttribute('title', tip)\n    }\n    const level = statsLevel(pct)\n    if (barRef.level !== level) {\n      barRef.level = level\n      if (level === '') barRef.bar.removeAttribute('data-level')\n      else barRef.bar.setAttribute('data-level', level)\n    }\n  }\n  const level = coresLevel(cores)\n  if (level === '') ref.meta.removeAttribute('data-level')\n  else ref.meta.setAttribute('data-level', level)\n  // 三个键都写成字面量：i18n 闸门静态扫不到变量拼出来的键\n  ref.meta.textContent = level === 'danger' ? t('statsDash.critical') : level === 'warn' ? t('statsDash.busy') : t('statsDash.normal')\n  const avg = Math.round((cores.reduce((sum, value) => sum + value, 0) / cores.length) * 10) / 10\n  ref.foot.textContent = t('statsDash.coresFoot', { cores: cores.length, pct: String(Math.round(avg)) })\n}\n\nfunction updateNetCard(ref, tab) {\n  const history = statsHistory.get(tab.sid) ?? []\n  /*\n   * 横轴固定成「最近 60 秒」：新采到的点从右边进来，左边还没攒到的位置留空。\n   * 直接把 5 个采样拉伸到整幅宽会假装「这一分钟都有数据」——刚打开的两秒和\n   * 攒满的一分钟看起来一模一样，正好骗人。\n   */\n  const pad = Math.max(0, STATS_HISTORY_LEN - history.length)\n  const rx = new Array(pad).fill(null).concat(history.map((sample) => sample.rxRate))\n  const tx = new Array(pad).fill(null).concat(history.map((sample) => sample.txRate))\n  const has = rx.some((value) => value !== null) || tx.some((value) => value !== null)\n  ref.empty.hidden = has\n  ref.body.hidden = !has\n  if (!has) {\n    ref.foot.textContent = ''\n    return\n  }\n  let peak = 0\n  for (const value of rx) if (value !== null && value > peak) peak = value\n  for (const value of tx) if (value !== null && value > peak) peak = value\n  /*\n   * Y 轴：**1-2-5 量程 + 15% 顶部余量 + 平方根刻度**。\n   *\n   *   - 量程：`chartCeiling(peak)` 按 1-2-5 台阶取（不是逐帧线性跟随），峰值永远落在\n   *     量程之内 → 尖刺不会顶到边框；台阶也让「量程」不会每秒自己微调（曲线不会抖）；\n   *   - 刻度用 sqrt 而不是线性：线性下「一次 9.8 MB/s 的突发 + 一分钟 1.2 MB/s 的常态」\n   *     会把常态压成贴底的一条平线，看不出任何起伏；\n   *   - 也不用对数：对数在**同一个数量级**里几乎不动——实测 58 KB/s 与 163 KB/s 在\n   *     256 KB/s 量程的对数轴上只差 8% 高度，日常波动全被抹平。0.5 次幂是这两者的折中：\n   *     同量级内保留起伏（同样两个值占 32% 高度），跨数量级的突发也不会把常态压没。\n   */\n  const ceiling = chartCeiling(peak)\n  const options = { min: 0, max: ceiling, power: 0.5 }\n  const areaPath = sparklineArea(rx, DASH_CHART_W, DASH_CHART_H, options)\n  const rxPath = sparklinePath(rx, DASH_CHART_W, DASH_CHART_H, options)\n  const txPath = sparklinePath(tx, DASH_CHART_W, DASH_CHART_H, options)\n  if (ref.area.getAttribute('d') !== areaPath) ref.area.setAttribute('d', areaPath)\n  if (ref.rxLine.getAttribute('d') !== rxPath) ref.rxLine.setAttribute('d', rxPath)\n  if (ref.txLine.getAttribute('d') !== txPath) ref.txLine.setAttribute('d', txPath)\n  const last = history.length > 0 ? history[history.length - 1] : null\n  const rxNow = last !== null && last.rxRate !== null ? last.rxRate : 0\n  const txNow = last !== null && last.txRate !== null ? last.txRate : 0\n  ref.foot.textContent = t('statsDash.netFoot', { rx: statsRateCompact(rxNow), tx: statsRateCompact(txNow), peak: statsRateCompact(peak) })\n}\n\nfunction updateProcsCard(ref, stats) {\n  const rows = procRows(stats.procs, 5, statsDashSort)\n  const has = rows.length > 0\n  ref.empty.hidden = has\n  ref.body.hidden = !has\n  ref.foot.hidden = !has\n  if (!has) {\n    ref.signature = ''\n    return\n  }\n  /*\n   * 行**顺序**变了也要重建（不只是行数）：`ps` 每 5 秒才刷新一次，而排序键可以随时切换，\n   * 若只在行数变化时重建，切到「按内存」或升序后列表会保持旧顺序、值与行对不上。\n   * 签名用 pid + 文件名：同值排序稳定，顺序没变时仍然走「只改文本」的快路径。\n   */\n  const signature = rows.map((row) => String(row.pid) + ':' + row.name).join('|')\n  if (ref.signature !== signature) {\n    ref.signature = signature\n    for (const row of ref.rows) row.line.remove()\n    ref.rows = rows.map(() => {\n      const line = document.createElement('div')\n      line.className = 'tt_statsDashProc'\n      const cmd = document.createElement('span')\n      cmd.className = 'tt_statsDashProcCmd'\n      const cpu = document.createElement('span')\n      cpu.className = 'tt_statsDashProcCpu'\n      const mem = document.createElement('span')\n      mem.className = 'tt_statsDashProcMem'\n      line.appendChild(cmd)\n      line.appendChild(cpu)\n      line.appendChild(mem)\n      ref.body.appendChild(line)\n      return { line, cmd, cpu, mem, level: null, name: '', shown: '' }\n    })\n  }\n  /*\n   * 名字列宽（每帧读一次，5 行的容器很便宜）：用它算「能放几个字符」，做**首尾截断**——\n   * 一串 `Framework Helper (Renderer) / (GPU)` 的前缀完全相同，CSS 的尾部省略号会把它们\n   * 变成同一个 `Framew…`，认不出是哪一个。\n   */\n  const nameWidth = ref.rows.length > 0 ? ref.rows[0].cmd.clientWidth : 0\n  const measure = nameWidth > 0 ? dashTextMeasure(ref.rows[0].cmd) : null\n  for (let index = 0; index < rows.length; index += 1) {\n    const item = rows[index]\n    const rowRef = ref.rows[index]\n    // 卡片里只放可执行文件名（macOS 的 comm 是完整路径，直接显示只能看见 `/Applications/G…`）；\n    // 完整路径与 pid 留在 title 里\n    let nameText = item.name\n    if (measure !== null) nameText = truncateMiddle(nameText, nameWidth, measure)\n    if (rowRef.name !== item.name || rowRef.width !== nameWidth || rowRef.shown !== nameText) {\n      rowRef.name = item.name\n      rowRef.width = nameWidth\n      rowRef.shown = nameText\n      if (rowRef.cmd.textContent !== nameText) rowRef.cmd.textContent = nameText\n    }\n    const tip = item.cmd + (item.pid > 0 ? ' · pid ' + String(item.pid) : '')\n    if (rowRef.cmd.getAttribute('title') !== tip) rowRef.cmd.setAttribute('title', tip)\n    const cpuText = item.cpuPct.toFixed(1) + '%'\n    if (rowRef.cpu.textContent !== cpuText) rowRef.cpu.textContent = cpuText\n    const memText = item.memPct.toFixed(1) + '%'\n    if (rowRef.mem.textContent !== memText) rowRef.mem.textContent = memText\n    if (rowRef.level !== item.level) {\n      rowRef.level = item.level\n      if (item.level === '') rowRef.cpu.removeAttribute('data-level')\n      else rowRef.cpu.setAttribute('data-level', item.level)\n    }\n  }\n}\n\n/**\n * 把一帧数据写进已建好的条目——**只有真的变了才碰 DOM**（文本 / 进度宽度 / 档位 / title）。\n *\n * title 用 `setAttribute` 写：不再是拼字符串的 HTML 属性，值里出现 `\"` `<` 也不会破坏结构。\n * 最小值守卫：宿主清洗 + `statsItemValues` 兜底之后 pct 只可能是 0~100，这里仍夹一次，\n * 免得第三方实现塞进来的越界值把进度条拉出容器。\n */\nfunction updateStatsItems(refs, tab) {\n  const values = statsItemValues(tab !== undefined ? tab.stats : null, t)\n  for (let index = 0; index < refs.length; index += 1) {\n    const ref = refs[index]\n    const next = values[index]\n    if (next === undefined) continue\n    // 槽位本身也只在变的时候写：固定槽位是「更新不改布局」的根，写错/漏写都等于没修\n    if (ref.slot !== next.slot) {\n      ref.slot = next.slot\n      ref.value.style.minWidth = next.slot > 0 ? next.slot + 'ch' : ''\n    }\n    if (ref.value.textContent !== next.value) ref.value.textContent = next.value\n    // 取值档位（目前只有 Ping）：绿=跟手 / 橙=偏高 / 红=卡顿；其余条目是空串（中性白）\n    const tone = typeof next.tone === 'string' ? next.tone : ''\n    if ((ref.value.dataset.level ?? '') !== tone) {\n      if (tone === '') delete ref.value.dataset.level\n      else ref.value.dataset.level = tone\n    }\n    /*\n     * 可选指标（温度 / Ping / Swap）：这个会话**从来没报过**就整格不画。\n     * 不是「这一帧没有就藏」——那会在传感器偶发读失败时每秒闪一次。\n     * 分隔线不用管：它是后一格画的，藏掉这一格后「左邻 │ 右邻」照样成立（见 CSS 注释）。\n     */\n    if (OPTIONAL_ITEM_KEYS.has(ref.key)) {\n      const hidden = tab === undefined || tab.seenItems === undefined || tab.seenItems[ref.key] !== true\n      if (ref.item.hidden !== hidden) ref.item.hidden = hidden\n    }\n    // 悬停信息走自绘卡片（stats-tip.js），`title` 会让原生 tooltip 叠成两层——这里只留 aria-label\n    if (ref.item.getAttribute('aria-label') !== next.summary) ref.item.setAttribute('aria-label', next.summary)\n    if (ref.fill !== null && ref.meter !== null) {\n      const width = next.pct === null ? '0%' : Math.max(0, Math.min(100, next.pct)).toFixed(1) + '%'\n      if (ref.fill.style.width !== width) ref.fill.style.width = width\n      const level = statsLevel(next.pct)\n      if (ref.meter.dataset.level !== level) ref.meter.dataset.level = level\n    }\n  }\n}\n\n/** 条目引用随状态条 DOM 一起作废（面板重建 / 关闭 / 隐藏清空时都要调用）。 */\nfunction discardStatsItems() {\n  statsItemEls = null\n  statsRenderKey = null\n}\n\n/** 状态条可见性：面板开着、没最小化、开关开、活动标签有新鲜数据。 */\nfunction statsBarVisible() {\n  if (modalEl === null || minimized || !statsEnabledCache || statsStyleCache === 'off') return false\n  const tab = activeTab()\n  if (tab === undefined || tab.embedded === true || tab.exited === true) return false\n  if (tab.stats === null || tab.stats === undefined) return false\n  return statsFrameFresh(tab.statsAt)\n}\n\n/**\n * 状态条显隐切换后的尺寸重算：条高改变了终端可用高度（.tt_term 的 top 偏移），\n * 不重跑 fit 就会行数错位 / 底部被裁。复用 switchTab 同一条路径（fit + sendResize）。\n */\nfunction refitActiveTab() {\n  if (minimized) return // 最小化时容器不可见：fit 会算出退化尺寸并可能 sendResize（0.19.0）\n  const tab = activeTab()\n  if (tab === undefined || tab.embedded === true || tab.fit === null) return\n  try {\n    tab.fit.fit()\n  } catch {\n    return // 容器还没布局（隐藏标签/面板正在收）\n  }\n  // sendResize 里的 proposeDimensions 在终端已 dispose 时可能抛：绝不让它冒泡\n  try {\n    if (tab.spawned && !tab.exited) sendResize(tab)\n  } catch {\n    /* 忽略：尺寸同步失败不该影响状态条显隐 */\n  }\n}\n\n/**\n * 重画状态条（对外入口）。整体兜底：任何意外都退回「不显示」——绝不能留下\n * 半截偏移（.tt_body[data-stats] 加上了但条没出来）把终端顶歪或让面板抛崩。\n */\nfunction applyStatsBar() {\n  try {\n    applyStatsBarInner()\n  } catch (error) {\n    console.warn('[dsh-tty] 状态条渲染失败（已收起）: ' + (error instanceof Error ? error.message : String(error)))\n    try {\n      if (statsBarEl !== null) {\n        statsBarEl.hidden = true\n        statsBarEl.textContent = ''\n      }\n      // 内容被清空 = 之前建的条目全不在文档里了：引用与数据签名必须一起作废，\n      // 否则下一次显示会往游离节点上写，状态条看着永远空着\n      forgetStatsDom()\n      if (bodyEl !== null) delete bodyEl.dataset.stats\n    } catch {\n      /* 连兜底都失败：静默，至少不再抛 */\n    }\n  }\n}\n\n/** 重画状态条；只有「显隐翻转」时才需要 fit（数据每秒刷新不该反复抖动终端）。 */\nfunction applyStatsBarInner() {\n  if (bodyEl === null || statsBarEl === null) return\n  // 头部按钮独立于条的显隐：条藏起来时它还得能把人捞回来\n  syncStatsToggle()\n  const visible = statsBarVisible()\n  const changed = (bodyEl.dataset.stats !== undefined) !== visible\n  if (!visible) {\n    closeStatsDash()\n    hideStatsTip()\n    if (changed) delete bodyEl.dataset.stats\n    statsBarEl.hidden = true\n    stopStatsClockTimer()\n    // 隐藏时把条目一起丢掉（省 DOM）：下次显示重建外壳与条目，也就自然拿到了新标签的数据\n    if (statsItemEls !== null) {\n      statsBarEl.textContent = ''\n      forgetStatsDom()\n    }\n    if (changed) refitActiveTab()\n    return\n  }\n  statsBarEl.hidden = false\n  if (statsItemEls === null) statsItemEls = buildStatsBarDom()\n  syncStatsStyleDom()\n  const tab = activeTab()\n  /*\n   * 同一条数据不重复渲染：1s 陈旧检测定时器也走这里，但它的职责只是「数据停了就收起」。\n   * 原先每次调用都重写整条 innerHTML —— 于是状态条每秒被重建两次（stats 帧一次 +\n   * 定时器一次），这正是「定期闪动」的第二个放大器。\n   */\n  const key = tab === undefined ? '' : tab.sid + ':' + String(tab.statsAt || 0)\n  if (key !== statsRenderKey) {\n    statsRenderKey = key\n    updateStatsItems(statsItemEls, tab)\n    updateStatsMinimal()\n    // 让位在 `updateStatsExtra` 末尾统一做：两种呈现的 DOM 都写完之后再按一条阶梯裁决\n    updateStatsExtra(tab)\n  }\n  // 时钟自己走 1s 定时器（宿主帧慢时挂在帧上会「几秒跳几下」）\n  ensureStatsClockTimer()\n  if (changed) {\n    bodyEl.dataset.stats = ''\n    refitActiveTab()\n  }\n  // 仪表盘 / 悬浮提示开着时跟着每帧刷新（关着就是一次 null 判断）\n  refreshStatsTip()\n  updateStatsDash()\n}\n\n/**\n * 把「完整 / 极简」的呈现切到当前偏好：只切两个容器的 `hidden`，两边的 DOM 都不销毁\n * （切回来时趋势线与固定槽位立刻还在，不用等下一帧重新长出来）。\n */\nfunction syncStatsStyleDom() {\n  const minimal = statsStyleCache === 'minimal'\n  if (statsFullEl !== null) statsFullEl.hidden = minimal\n  if (statsMinEl !== null) statsMinEl.hidden = !minimal\n  // 条高由 CSS 变量按这个属性切（极简 36px / 完整 24px）：终端 top 偏移与退出条共用它\n  if (bodyEl !== null) {\n    const next = minimal ? 'minimal' : 'full'\n    if (bodyEl.dataset.statsStyle !== next) bodyEl.dataset.statsStyle = next\n  }\n}\n\n/**\n * 头部那颗三档循环按钮：图标与文案跟**当前**档位走（不是「点它会发生什么」），\n * 这样用户不点开也知道现在处在哪一档。\n */\nfunction syncStatsToggle() {\n  if (statsToggleEl === null) return\n  // 配置层把整条关掉时按钮没有意义（点了也不会采），跟着藏起来——但本地 off 不藏，\n  // 否则用户就再也点不回来了。\n  statsToggleEl.hidden = !statsEnabledCache\n  if (statsToggleMode !== statsStyleCache) {\n    statsToggleMode = statsStyleCache\n    // 三个键都写成字面量：i18n 闸门静态扫不到变量拼的键，会报成死键\n    if (statsStyleCache === 'minimal') {\n      statsToggleEl.innerHTML = ICON_STATS_MINIMAL\n      statsToggleEl.title = t('stats.minimalTitle')\n      statsToggleEl.setAttribute('aria-label', t('stats.minimalTitle'))\n    } else if (statsStyleCache === 'off') {\n      statsToggleEl.innerHTML = ICON_STATS_OFF\n      statsToggleEl.title = t('stats.offTitle')\n      statsToggleEl.setAttribute('aria-label', t('stats.offTitle'))\n    } else {\n      statsToggleEl.innerHTML = ICON_STATS_FULL\n      statsToggleEl.title = t('stats.fullTitle')\n      statsToggleEl.setAttribute('aria-label', t('stats.fullTitle'))\n    }\n  }\n  const pressed = statsStyleCache === 'off' ? 'false' : 'true'\n  if (statsToggleEl.getAttribute('aria-pressed') !== pressed) statsToggleEl.setAttribute('aria-pressed', pressed)\n}\n\n/** 陈旧检测：采集端静默停止（无 /proc、exec 被拒、配置关闭）时前端要自己收起。 */\nfunction ensureStatsStaleTimer() {\n  if (statsStaleTimer !== null) return\n  statsStaleTimer = setInterval(() => applyStatsBar(), 1000)\n}\n\nfunction stopStatsStaleTimer() {\n  if (statsStaleTimer === null) return\n  clearInterval(statsStaleTimer)\n  statsStaleTimer = null\n}\n\n/** 需要订阅的 sid：只有可见标签才采（最小化/嵌入/已退出/开关关闭都不采）。 */\nfunction desiredStatsSid() {\n  if (modalEl === null || minimized || !statsEnabledCache || statsStyleCache === 'off') return null\n  const tab = activeTab()\n  if (tab === undefined || tab.embedded === true || tab.exited === true) return null\n  return tab.sid\n}\n\n/**\n * 订阅对齐（幂等）：把宿主的采集器开关对齐到「当前可见标签」。tab 切换、面板\n * 开合/最小化、开关热生效、断线重连（statsSubSid 置 null 后由 ready 重新对齐）\n * 都调这里；退订后宿主侧会停表并关掉远端 exec channel。\n */\nfunction syncStatsSubscription() {\n  const want = desiredStatsSid()\n  if (want === statsSubSid) return\n  if (statsSubSid !== null) sendFrame({ t: 'statsOff', sid: statsSubSid })\n  statsSubSid = want\n  if (want !== null) sendFrame({ t: 'statsOn', sid: want })\n}\n\n/**\n * 会话就绪后补发订阅。新标签的 statsOn 是在 spawn 帧之前发的（switchTab 早于\n * spawnTab），宿主那边会话还没登记，会被按「未知 sid」静默忽略；所以 ready 之后\n * 必须再对齐一次（attach / 断线重连同理）。宿主侧订阅是 Set 语义，重复 statsOn\n * 幂等，不会重复启动采集。\n */\nfunction resubscribeStats(sid) {\n  if (sid !== desiredStatsSid()) {\n    syncStatsSubscription()\n    return\n  }\n  if (statsSubSid !== null && statsSubSid !== sid) sendFrame({ t: 'statsOff', sid: statsSubSid })\n  statsSubSid = sid\n  sendFrame({ t: 'statsOn', sid })\n}\n\n/* ---------- 退出提示条（D96 / issue #7①②） ---------- */\n\n/**\n * 当前标签该在退出提示条上说什么（没有就 null）。\n *\n * 两态：\n *   - `released`：D97（#7④）里「AI 显式释放了这条会话、而这恰好是你正在看的标签」——先提示，\n *     切走或点「收起」再收标签（后台的标签当场就收，不进这里）；\n *   - `exited`  ：会话自己跑完 / 停在只读保留里——标签留着、输出可读可复制。\n *\n * 嵌入终端（dsh-docker 抽屉里那块）不走这条：它没有面板的顶部条，退出态仍由遮罩 +\n * 「点击重新执行」表达（`showTabOverlay` 里那条 `embedded` 分支）。\n */\nfunction exitBarState() {\n  const tab = activeTab()\n  if (tab === undefined || tab.embedded === true) return null\n  if (tab.releasePending === true) return { kind: 'released', tab }\n  if (tab.exited === true) return { kind: 'exited', tab }\n  return null\n}\n\n/**\n * 重画退出提示条（幂等）。与服务器状态条同一套几何机制：条子绝对定位在 `.tt_body`\n * 顶部，显隐只把 `.tt_term` 的 top 往下推，所以**只有显隐翻转时**才需要重跑 fit\n * （数据没变时反复 fit 会让终端抖动）。\n */\nfunction applyExitBar() {\n  if (bodyEl === null || exitBarEl === null) return\n  const state = exitBarState()\n  const visible = state !== null\n  const changed = (bodyEl.dataset.exited !== undefined) !== visible\n  if (!visible) {\n    exitBarEl.hidden = true\n    exitBarEl.textContent = ''\n    exitBarRenderKey = ''\n    if (changed) {\n      delete bodyEl.dataset.exited\n      refitActiveTab()\n    }\n    return\n  }\n  exitBarEl.hidden = false\n  renderExitBar(state)\n  if (changed) {\n    bodyEl.dataset.exited = ''\n    refitActiveTab()\n  }\n}\n\n/** 退出提示条的内容（签名不变就不重画：重建会把刚聚焦的按钮、正在读的文本顶掉）。 */\nfunction renderExitBar(state) {\n  const { kind, tab } = state\n  const detail = typeof tab.exitDetail === 'string' ? tab.exitDetail : ''\n  const key = kind + ':' + tab.sid + ':' + detail\n  if (key === exitBarRenderKey) return\n  exitBarRenderKey = key\n  exitBarEl.textContent = ''\n\n  const text = document.createElement('span')\n  text.className = 'tt_exitBarText'\n  text.textContent = kind === 'released'\n    ? t('status.aiEnded')\n    : detail === '' ? t('status.exited') : t('status.exitedWith', { detail })\n  if (kind === 'released') text.title = t('hint.aiEndedTab')\n  exitBarEl.appendChild(text)\n\n  const spacer = document.createElement('span')\n  spacer.className = 'tt_exitBarSpacer'\n  exitBarEl.appendChild(spacer)\n\n  if (kind === 'released') {\n    // 「收起」= 关掉这个标签：会话已经没了，标签只是留给你把最后一眼看完\n    addExitBarButton(t('btn.dismiss'), t('btn.dismissTitle'), () => {\n      closeTab(tab.sid, { silent: true })\n    })\n    return\n  }\n  /*\n   * 「重新打开」对所有面板标签都给（与旧遮罩的「点击重新打开」同一个覆盖面）：\n   * `respawnTab` 拿标签自己的 spawnSpec 重开一条，普通本地标签就是新开一个 shell。\n   * ⚠️ 判据**不能**用 `isRerunnableSpec`：那个判据是给「断线重连 / 宿主重启后要不要自动\n   * 重跑」用的，普通本地标签（`{t:'spawn', cwd}`）在里面是 false——用它会让本地标签的\n   * 「重新打开」凭空消失（预览场景 `exited` 当场抓到过这一条）。\n   */\n  if (tab.spawnSpec === null || typeof tab.spawnSpec !== 'object') return\n  /*\n   * AI 开的标签上「重新打开」**接不回**那条会话：`adoptAgentSessions` 给的 spawnSpec 是\n   * 占位本地终端（{t:'spawn',cwd}），点了只会新开一个本地 shell。文案如实写，不留一个\n   * 看起来能恢复、实际换了一条的按钮。\n   */\n  const agentOwned = tab.agentOwned === true\n  addExitBarButton(\n    agentOwned ? t('btn.newLocalTerminal') : t('btn.reopenSession'),\n    agentOwned ? t('hint.reopenAgentLocal') : t('hint.reopenWithSpec'),\n    () => respawnTab(tab.sid),\n  )\n}\n\n/** 提示条上的按钮：与面板其它次要按钮同一族（尺寸 / 圆角 / 四态由 .tt_toolBtn 基类给）。 */\nfunction addExitBarButton(label, title, onClick) {\n  const btn = document.createElement('button')\n  btn.type = 'button'\n  btn.className = 'tt_toolBtn tt_exitBarBtn'\n  btn.textContent = label\n  if (typeof title === 'string' && title !== '') btn.title = title\n  btn.addEventListener('click', onClick)\n  exitBarEl.appendChild(btn)\n}\n\nfunction activeTab() {\n  return activeSid !== null ? tabs.get(activeSid) : undefined\n}\n\n/**\n * 当前 DSH 会话的工作目录（sessions 客户端服务快照）——新开的标签就落在这里，\n * 而不是宿主的启动目录。0.1.6 起列表快照没有 current 字段，取法见 current-session.js\n * （改看 retainedBy.mainView，官方 dsh-client-ui-session 与本地 codegraph 同一判据）。\n */\nfunction currentCwd() {\n  try {\n    return currentSessionCwd(sessionsService?.list?.getSnapshot?.())\n  } catch {\n    return undefined\n  }\n}\n\n/**\n * 持久（tmux）标签的自愈：tmux 只重画可见屏，外层 xterm 的缓冲行数正常应\n * 恰好等于视口行数；一旦超出（字体加载后收缩、标签切换的连接栏显隐、窗口\n * 尺寸变化等把多出的行推进 scrollback）→ reset 清掉残 scrollback 后发\n * refresh 帧请宿主 refresh-client 重画。非持久标签不干预。\n */\nfunction settleNow(tab) {\n  if (tab.term === null || tab.exited) return\n  try {\n    if (tab.term.buffer.active.length <= tab.term.rows) return\n  } catch {\n    return\n  }\n  tab.term.reset()\n  sendFrame({ t: 'refresh', sid: tab.sid })\n}\n\nlet settleTimer = null\nfunction scheduleSettle(delay) {\n  if (settleTimer !== null) clearTimeout(settleTimer)\n  settleTimer = setTimeout(() => {\n    settleTimer = null\n    const tab = activeTab()\n    if (tab !== undefined) settleNow(tab)\n  }, delay ?? 200)\n}\n\n/**\n * 持久化安全化（0.19.0）：SSH 明文凭证（password/passphrase）不落浏览器存储\n * ——sessionStorage['dsh-tty:tabs'] 与 localStorage['dsh-tty:persist-specs']\n * 同源脚本可读。只作用于持久化副本：`env:` 引用不是明文，保留；明文剥掉并\n * 打 `credsStripped` 标记，恢复 / 重开时在终端提示重新输入。内存里的\n * spawnSpec 保持原值，本次会话的连接 / respawn 不受影响。\n */\nconst SENSITIVE_SPEC_FIELDS = ['password', 'passphrase']\nfunction persistSafeSpec(spec) {\n  if (spec === null || typeof spec !== 'object' || spec.t !== 'ssh') return spec\n  let stripped = spec.credsStripped === true\n  const next = { ...spec }\n  for (const field of SENSITIVE_SPEC_FIELDS) {\n    const value = next[field]\n    if (typeof value === 'string' && value !== '' && !value.startsWith('env:')) {\n      delete next[field]\n      stripped = true\n    }\n  }\n  if (stripped) next.credsStripped = true\n  return next\n}\n\n/** 标签列表持久化（sessionStorage，随浏览器标签页生命周期）：只存未退出的标签。\n *  载荷带版本号 v（0.19.0）：结构升级时按版本迁移或丢弃，旧数据不再按新语义误读；\n *  写入失败（配额溢出等）不再静默——至少留下 console 警告。 */\nconst PERSIST_VERSION = 1\nfunction persistTabs() {\n  try {\n    const data = [...tabs.values()]\n      .filter((tab) => !tab.exited && tab.embedded !== true) // 嵌入会话不进标签持久化\n      .map((tab) => ({ sid: tab.sid, spawnSpec: persistSafeSpec(tab.spawnSpec), label: tab.label }))\n    if (data.length === 0 || modalEl === null) sessionStorage.removeItem(PERSIST_KEY)\n    else sessionStorage.setItem(PERSIST_KEY, JSON.stringify({ v: PERSIST_VERSION, tabs: data }))\n    // 持久规格独立留存：exit 帧（自然退出/回收器回收/宿主重启）不淘汰规格——\n    // 那正是需要恢复的场景；规格只随「标签被主动关闭」（closeTab）淘汰。\n    // 恢复时按规格 respawn：tmux 会话存活则接回原现场，已消失则新开 shell\n    syncPersistSpecStore([...tabs.values()].filter((tab) => tab.embedded !== true).map((tab) => ({ spawnSpec: persistSafeSpec(tab.spawnSpec), label: tab.label })))\n  } catch (error) {\n    // 隐私模式存储不可用属正常；QuotaExceededError 等会被静默丢标签，必须留痕\n    console.warn('[dsh-tty] 标签持久化失败（本次刷新后标签列表可能丢失）: ' + (error instanceof Error ? error.message : String(error)))\n  }\n}\n\n/**\n * 持久标签规格（localStorage，跨浏览器标签页/窗口存活）：sessionStorage 只\n * 有同一个浏览器标签页能看到，dsh 重启自动打开的新窗口读不到——持久化的\n * 「宿主重启后恢复」就断在这一环。规格跨窗口共享，恢复前经宿主 sessions\n * 帧的 tmux 会话名清单确认仍存活（已关闭/已消失的规格自动淘汰）。\n */\nconst PERSIST_SPEC_KEY = 'dsh-tty:persist-specs'\n\nfunction syncPersistSpecStore(data) {\n  try {\n    const specs = data\n      .filter((tab) => isPersistentSpec(tab.spawnSpec))\n      .map((tab) => ({ spawnSpec: tab.spawnSpec, label: tab.label }))\n    if (specs.length === 0) localStorage.removeItem(PERSIST_SPEC_KEY)\n    else localStorage.setItem(PERSIST_SPEC_KEY, JSON.stringify(specs))\n  } catch {\n    /* 存储不可用：静默跳过 */\n  }\n}\n\n/** 读取跨窗口的持久标签规格（结构不合法的条目丢弃）。 */\nfunction loadPersistSpecs() {\n  try {\n    const raw = localStorage.getItem(PERSIST_SPEC_KEY)\n    if (raw === null) return []\n    const parsed = JSON.parse(raw)\n    if (!Array.isArray(parsed)) return []\n    return parsed.filter((item) => item !== null && typeof item === 'object' && isPersistentSpec(item.spawnSpec))\n  } catch {\n    return []\n  }\n}\n\n/** 读取持久化标签（页面刷新后重开面板用）；结构不合法的条目直接丢弃。\n *  兼容两种载荷：v1 对象（{v, tabs}）与历史数组（读取后随下次 persistTabs 升级）。 */\nfunction loadPersistedTabs() {\n  try {\n    const raw = sessionStorage.getItem(PERSIST_KEY)\n    if (raw === null) return []\n    const parsed = JSON.parse(raw)\n    if (Array.isArray(parsed)) return parsed.filter((item) => item !== null && typeof item === 'object' && typeof item.sid === 'string' && item.sid !== '' && item.spawnSpec !== null && typeof item.spawnSpec === 'object')\n    if (parsed !== null && typeof parsed === 'object' && parsed.v === PERSIST_VERSION && Array.isArray(parsed.tabs)) {\n      return parsed.tabs.filter((item) => item !== null && typeof item === 'object' && typeof item.sid === 'string' && item.sid !== '' && item.spawnSpec !== null && typeof item.spawnSpec === 'object')\n    }\n    // 未知版本：结构可能已不兼容，按「丢弃」处理而不是猜\n    return []\n  } catch {\n    return []\n  }\n}\n\n/**\n * 等待某一类型的第一帧（独立监听，主 onmessage 同时照常处理）；\n * 超时返回 null（宿主不支持该帧 / 网络异常）。\n * socket 引用在进入时就捕获（0.19.0）：等待期间发生 connect()（先 close 旧\n * socket 再新建）时，监听器清理必须对着当次实例——此前清理读模块级 socket\n * 变量，旧监听器留在已关闭的 socket 上且必然 resolve(null)，恢复流程误判\n * 「宿主一个会话都没有」，可重跑标签被 restoreTabAsNew 双开。\n */\nfunction waitFrame(type, timeoutMs) {\n  const ws = socket\n  return new Promise((resolve) => {\n    let timer = null\n    const onMsg = (event) => {\n      let msg\n      try {\n        msg = JSON.parse(event.data)\n      } catch {\n        return\n      }\n      if (msg.t !== type) return\n      if (timer !== null) clearTimeout(timer)\n      ws.removeEventListener('message', onMsg)\n      // 连接已被换掉：旧 socket 上的帧不再可信，按超时处理让调用方重新评估\n      resolve(ws === socket ? msg : null)\n    }\n    timer = setTimeout(() => {\n      ws.removeEventListener('message', onMsg)\n      resolve(null)\n    }, timeoutMs)\n    ws.addEventListener('message', onMsg)\n  })\n}\n\n/** 尺寸探测用的宿主元素：普通标签是 termEl，嵌入终端是它自己的挂载容器。 */\nfunction sizeHostEl(tab) {\n  if (tab === undefined) return null\n  if (tab.embedded === true) {\n    return tab.controller !== undefined && tab.controller !== null ? tab.controller.hostEl : null\n  }\n  return tab.termEl\n}\n\n/**\n * 算一次**可以发给 PTY** 的尺寸（D79）。\n *\n * 三种「不算可见」的情况一律返回 `undefined`，调用方就别发：别的标签正亮着\n * （`display:none`）、面板最小化、元素根本没进 DOM（agent 开的标签刻意不 switchTab）。\n * 探测结果本身也可能是垃圾（游离元素给 NaN、隐藏容器给 2×1），一并由\n * `usableFitSize` 挡掉——**绝不能把退化值当尺寸发出去**：宿主会把 `NaN`→JSON `null`\n * 夹成下限，后台标签的 PTY 于是变成 2×2，长任务输出按 2 列折行且永不重排。\n */\nfunction probeFitSize(tab) {\n  if (tab === undefined || tab.fit === null || tab.fit === undefined) return undefined\n  let dims\n  try {\n    dims = tab.fit.proposeDimensions()\n  } catch {\n    return undefined // 终端已 dispose 等\n  }\n  const el = sizeHostEl(tab)\n  return usableFitSize(dims, el === null || el === undefined ? null : { width: el.clientWidth, height: el.clientHeight })\n}\n\nfunction sendResize(tab) {\n  if (tab === undefined || tab.fit === undefined) return\n  const dims = probeFitSize(tab)\n  if (dims === undefined) return // D79：不可见 / 退化的尺寸不发，保留 PTY 上一次有效尺寸\n  tab.lastDims = dims\n  sendFrame({ t: 'resize', sid: tab.sid, cols: dims.cols, rows: dims.rows })\n}\n\n/**\n * 终端区尺寸变化（窗口缩放、挂载位开合）后的重新 fit。\n *\n * 不能只调 fit 就完事：xterm 在 rows 变化时会按自己的规则挪视口，用户看到的就是\n * 「开个面板，终端里的文字被往上顶了」。这里按用户当时的意图锚定视口——\n * 本来就贴着底部（在看最新输出）就继续贴底；翻在历史里就锁住原来那几行不跳。\n */\nfunction refitTerminal(tab) {\n  if (tab === undefined || tab.fit === undefined) return\n  const term = tab.term\n  const buffer = term !== null && term.buffer !== undefined ? term.buffer.active : null\n  const anchor = buffer == null ? null : { atBottom: buffer.viewportY >= buffer.baseY, line: buffer.viewportY }\n  try {\n    tab.fit.fit()\n  } catch {\n    return // 容器还没布局（面板最小化等）：交给下一次\n  }\n  if (anchor !== null) {\n    try {\n      if (anchor.atBottom) term.scrollToBottom()\n      else term.scrollToLine(Math.min(anchor.line, term.buffer.active.baseY))\n    } catch {\n      /* 极端时序下 term 可能已 dispose：忽略 */\n    }\n  }\n  if (!tab.exited) sendResize(tab)\n}\n\n/**\n * 终端区遮罩：空串清除，否则渲染成「图标 + 主文案 + 副文案」的动作卡片\n * （连接错误 / 断线重连中两种语义；嵌入终端的退出态仍走这里）。\n *\n * ⚠️ **面板标签的退出态不再铺满遮罩**（D96 / issue #7①）：那层 `inset:0` + 半透明底 +\n * 模糊 + 整块可点，把 AI 跑出来的结果压在下面（用户上报：得去 F12 把 `.tt_overlay`\n * 藏掉才看得清），而且它整块吃点击——连选中复制都做不到。面板标签的退出态改由顶部\n * 提示条表达（`applyExitBar`），输出照常可读、可滚、可复制。\n *\n * 这条守卫把「不许再给面板标签画退出遮罩」变成结构性约束：调用点即使照旧传 'exited'，\n * 也只会把遮罩清空。嵌入终端（`tab.embedded`）维持原样——它挂在消费方（dsh-docker\n * 抽屉）的容器里，没有面板的顶部条，退出态只有这块遮罩能承载「点击重新执行」。\n * 回归：`test/exit-overlay.test.ts` 钉住本分支与顶部条的存在。\n */\nfunction showTabOverlay(tab, text, hint, kind) {\n  if (tab.overlayEl === null || tab.overlayEl === undefined) return\n  const el = tab.overlayEl\n  const level = kind === 'error' || kind === 'info' ? kind : 'exited'\n  if (level === 'exited' && tab.embedded !== true) {\n    el.textContent = ''\n    return\n  }\n  if (text === '' || text === undefined) {\n    el.textContent = ''\n    return\n  }\n  el.innerHTML = '<div class=\"tt_overlayCard\" data-kind=\"' + level + '\">' +\n    '<span class=\"tt_overlayIcon\">' + (level === 'error' ? ICON_STOP : level === 'info' ? ICON_REFRESH : ICON_POWER) + '</span>' +\n    '<span class=\"tt_overlayText\"><span class=\"tt_overlayMain\"></span>' +\n    (hint === undefined || hint === '' ? '' : '<span class=\"tt_overlayHint\"></span>') +\n    '</span></div>'\n  el.querySelector('.tt_overlayMain').textContent = text\n  if (hint !== undefined && hint !== '') el.querySelector('.tt_overlayHint').textContent = hint\n}\n\n/**\n * 读取宿主主题变量。**必须在声明令牌的元素上读**：宿主把 alias 令牌声明在 body 上\n * （如 `--dsw-alias-bg-base`，明暗两档都挂在 body / `body[data-ds-dark-theme]` 上），\n * 而自定义属性只向**下**继承\n * ——在 `document.documentElement`（html）上永远取不到，读它只会一直拿到兜底值\n * （本包的终端强调色因此长期是 #7c9cff，主题给的 #4176e6 从没生效过）。\n * 本包的 --tt-* 声明在 `:where(html, body)` 上，从 body 也读得到。\n *\n * @param {string} name 自定义属性名（含 `--`）。\n * @param {string} [fallback] 取不到时的返回值；**不许传颜色字面量**（client-lint 检查十六）。\n * @returns {string}\n */\nfunction cssVar(name, fallback = '') {\n  try {\n    const value = getComputedStyle(document.body).getPropertyValue(name).trim()\n    return value !== '' ? value : fallback\n  } catch {\n    return fallback\n  }\n}\n\nfunction createTerminal(tab) {\n  // 终端底色固定深色（与主流终端一致），强调色跟随宿主皮肤（--tt-accent 登记在 tty.css 的令牌块）\n  const accent = cssVar('--tt-accent')\n  /*\n   * xterm 配色：值全部登记在 tty.css 的 --tt-term-* / --tt-an-* 定义位（域调色板只在一处登记）。\n   * 这里**逐个赋值**而不是写成一个对象字面量：`{ k: v }` 块会被内联 CSS 的扫描口径当成一条声明，\n   * `black:` / `red:` / `white:` 这些 xterm 键名会落进「值」里被当成具名色（**那个误报已修**：\n   * scanColorLiterals 现在会掩掉键位，scripts/test/client-design-tokens.test.ts 有用例）。\n   * 保留逐个赋值是因为每个键的取值各自带一行出处，改哪一项就不用在大对象里数位置。\n   *\n   * @type {Record<string, string>}\n   */\n  const theme = {}\n  theme.background = cssVar('--tt-term-bg')\n  theme.foreground = cssVar('--tt-term-fg')\n  theme.cursor = accent\n  theme.cursorAccent = cssVar('--tt-term-cursor-accent')\n  theme.selectionBackground = cssVar('--tt-term-selection')\n  theme.black = cssVar('--tt-an-black')\n  theme.red = cssVar('--tt-an-red')\n  theme.green = cssVar('--tt-an-green')\n  theme.yellow = cssVar('--tt-an-yellow')\n  theme.blue = cssVar('--tt-an-blue')\n  theme.magenta = cssVar('--tt-an-magenta')\n  theme.cyan = cssVar('--tt-an-cyan')\n  theme.white = cssVar('--tt-an-white')\n  theme.brightBlack = cssVar('--tt-an-bright-black')\n  theme.brightRed = cssVar('--tt-an-bright-red')\n  theme.brightGreen = cssVar('--tt-an-bright-green')\n  theme.brightYellow = cssVar('--tt-an-bright-yellow')\n  theme.brightBlue = cssVar('--tt-an-bright-blue')\n  theme.brightMagenta = cssVar('--tt-an-bright-magenta')\n  theme.brightCyan = cssVar('--tt-an-bright-cyan')\n  theme.brightWhite = cssVar('--tt-an-bright-white')\n  const term = new Terminal({\n    // 外观（0.34.0 起可配）：缓存来自 /api/dsh-tty/config，默认值 = 0.33 的硬编码值\n    cursorBlink: terminalLookCache.cursorBlink,\n    cursorStyle: terminalLookCache.cursorStyle,\n    cursorInactiveStyle: 'outline',\n    fontSize: terminalLookCache.fontSize,\n    fontFamily: terminalFontFamilyValue(terminalLookCache.fontFamily),\n    fontWeight: 400,\n    fontWeightBold: 600,\n    lineHeight: terminalLookCache.lineHeight,\n    scrollback: 5000,\n    convertEol: false,\n    // 搜索高亮装饰（SearchAddon decorations）依赖提案 API\n    allowProposedApi: true,\n    theme,\n  })\n  const fit = new FitAddon()\n  const search = new SearchAddon()\n  term.loadAddon(fit)\n  term.loadAddon(search)\n  term.loadAddon(new WebLinksAddon())\n\n  const termEl = document.createElement('div')\n  termEl.className = 'tt_term'\n  const overlayEl = document.createElement('div')\n  overlayEl.className = 'tt_overlay'\n  overlayEl.addEventListener('click', () => {\n    overlayEl.textContent = ''\n    respawnTab(tab.sid)\n  })\n  // 键盘可达（0.19.0）：退出/错误浮层此前 div+click，键盘用户重开不了会话\n  overlayEl.setAttribute('role', 'button')\n  overlayEl.setAttribute('aria-label', t('btn.reopenSession'))\n  overlayEl.tabIndex = 0\n  overlayEl.addEventListener('keydown', (event) => {\n    if (event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar') {\n      event.preventDefault()\n      overlayEl.textContent = ''\n      respawnTab(tab.sid)\n    }\n  })\n  termEl.appendChild(overlayEl)\n\n  term.open(termEl)\n  try {\n    fit.fit()\n  } catch {\n    /* 容器尚未布局完成时忽略 */\n  }\n  // WebGL 渲染器：高吞吐输出（build 日志）性能质变；上下文丢失（多标签\n  // 超出浏览器 WebGL 上下文配额等）时释放本 addon，xterm 自动回退 DOM 渲染器\n  try {\n    const webgl = new WebglAddon()\n    webgl.onContextLoss(() => {\n      try {\n        webgl.dispose()\n      } catch {\n        /* 已释放 */\n      }\n    })\n    term.loadAddon(webgl)\n  } catch {\n    /* WebGL 不可用：保持 DOM 渲染器 */\n  }\n\n  term.onData((data) => {\n    sendFrame({ t: 'input', sid: tab.sid, d: data })\n    // 用户自己动手了：旧徽标作废（否则修好之后那枚「命令失败」会一直挂在那儿）\n    if (assistHints.delete(tab.sid)) syncAssistBadge()\n  })\n  /*\n   * 光标外观的最终话语权在配置项（0.34.0）：zle 之类每画一次提示符都会发\n   * `?12l` / `\\e[6 q` 把 cursorBlink、cursorStyle 写掉（xterm 里这两个各只有一个\n   * 变量，见 terminalLookDrift 的注释），所以每批输出解析完纠回一次。\n   */\n  term.onWriteParsed(() => enforceTerminalLook(term))\n  // 持久（tmux）标签尺寸自愈：SSH↔本地标签切换会改变终端区高度（连接栏\n  // 显隐），xterm 收缩的瞬间多出的行被推进 scrollback——幽灵滚动条 + 视口\n  // 停在顶部。onResize 时检测缓冲超出视口即 reset + refresh 重画\n  term.onResize(() => {\n    if (isPersistentSpec(tab.spawnSpec)) scheduleSettle(200)\n  })\n  term.attachCustomKeyEventHandler((event) => {\n    // 嵌入式终端没有搜索框（搜索是 tty 面板头部的 UI），Ctrl+F 交还给浏览器\n    if (tab.embedded === true) return true\n    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'f') {\n      event.preventDefault()\n      toggleSearch()\n      return false\n    }\n    return true\n  })\n\n  tab.term = term\n  tab.fit = fit\n  tab.search = search\n  tab.termEl = termEl\n  tab.overlayEl = overlayEl\n}\n\n/**\n * 新建标签页。spawnSpec 为创建帧的可变部分（本地 {t:'spawn',cwd} / SSH\n * {t:'ssh',...}），随标签保存以便 respawn 复用；label 为标签标题（SSH 标签\n * 传连接名或 user@host，缺省显示「终端 N」）。未指定 spawnSpec 时（默认本地\n * 终端），持久化开启则默认由 tmux 托管。\n */\n/**\n * 同一个「连接 + 命令」的复用键。\n *\n * 键必须**稳定**：不能直接 `JSON.stringify(spec)`——键顺序不同就会漏判，而从 sessionStorage\n * 恢复的 spec 与现场构造的 spec 顺序未必一致。所以按固定字段列表取值。\n */\nfunction specReuseKey(spec) {\n  if (spec === null || typeof spec !== 'object') return ''\n  // `hidden` 参与复用键（0.30.0）：隐藏过的标签与普通标签**不是**同一个规格——否则点\n  // 「新建本地终端」会复用那条被用户藏起来的标签，等于把 AI 的可见性换来换去。\n  const fields = ['t', 'name', 'host', 'port', 'username', 'command', 'cwd', 'persist', 'persistName', 'hidden']\n  return fields.map((field) => field + '=' + String(spec[field] ?? '')).join('\\u0000')\n}\n\n/** 找一个与 spec 同「连接 + 命令」且**还活着**的标签（复用它，而不是再堆一个重复的）。 */\nfunction findReusableTab(spec) {\n  const key = specReuseKey(spec)\n  if (key === '') return null\n  for (const tab of tabs.values()) {\n    if (tab.exited === true) continue\n    if (tab.embedded === true) continue\n    if (specReuseKey(tab.spawnSpec) === key) return tab\n  }\n  return null\n}\n\nfunction addTab(spawnSpec, label) {\n  const sid = newSid()\n  const tab = {\n    sid,\n    term: null,\n    fit: null,\n    search: null,\n    termEl: null,\n    overlayEl: null,\n    exited: false,\n    spawned: false,\n    spawnSpec: spawnSpec ?? defaultLocalSpec(),\n    label,\n  }\n  createTerminal(tab)\n  tabs.set(sid, tab)\n  tabCounter += 1\n  renderTabbar()\n  switchTab(sid, { user: true })\n  spawnTab(tab)\n  persistTabs()\n  return tab\n}\n\n/**\n * 采纳 agent 开的会话（0.20.0，tty_open）。\n *\n * 设计前提：agent 开的终端**必须对用户可见可接管**（不做隐形会话——D06 那类\n * 僵尸会话正是隐形会话的产物：用户不知道机器上跑着什么）。宿主在 agent 开关\n * 会话后推一帧 sessions，这里把还没有本地标签的 agent 会话建成标签并 attach。\n *\n * 与 restoreTab 的区别：那个走 sessionStorage 里的已知 sid，这个是**被通知**的\n * 新 sid（宿主侧已存在，attach 即接回现场），所以 spawnSpec 用一个占位（本地\n * spawn），标签标记 agentOwned 供 UI 区分。\n */\nfunction adoptAgentSessions(list) {\n  if (!Array.isArray(list)) return\n  for (const entry of list) {\n    if (entry === null || typeof entry !== 'object') continue\n    if (entry.owner !== 'agent') continue // 只采纳 agent 开的\n    // D77：只读保留（进程已退出）的会话不建标签——它没有活着的 PTY 可 attach，\n    // 建出来只会立刻收到「不能再接回终端」的错误浮层。那种会话的输出归 AI 侧\n    // 的 tty_capture 读；用户要接着用就自己重开一条。\n    if (entry.exited === true) continue\n    const sid = typeof entry.sid === 'string' ? entry.sid : ''\n    if (sid === '') continue\n    if (tabs.has(sid)) continue // 已经在本地有标签（用户已接管过）\n    const tab = {\n      sid,\n      term: null,\n      fit: null,\n      search: null,\n      termEl: null,\n      overlayEl: null,\n      exited: false,\n      spawned: false,\n      agentOwned: true,\n      spawnSpec: { t: 'spawn', cwd: typeof entry.cwd === 'string' ? entry.cwd : currentCwd() },\n      label: 'agent' + (entry.kind === 'ssh' && typeof entry.target === 'string' && entry.target !== '' ? ' · ' + entry.target : ''),\n    }\n    createTerminal(tab)\n    tabs.set(sid, tab)\n    tabCounter += 1\n    renderTabbar()\n    // 刻意不 switchTab：面板可能没打开（bodyEl 为 null），且 agent 开的终端\n    // 不该抢用户当前的焦点——它在后台待着，用户点标签才切过去。\n    if (panelVisible() && tab.termEl !== null && bodyEl !== null && activeSid === null) {\n      switchTab(sid)\n    }\n    sendFrame({ t: 'attach', sid })\n    persistTabsForAgent()\n  }\n}\n\n/** 面板当前是否可见（modalEl 存在且未最小化）——决定采纳 agent 标签时能否切过去。 */\nfunction panelVisible() {\n  return modalEl !== null && minimized !== true\n}\n\n/** agent 标签也要能在页面刷新后恢复（与普通标签同样的持久化）。 */\nfunction persistTabsForAgent() {\n  try {\n    persistTabs()\n  } catch {\n    /* 持久化失败不影响会话 */\n  }\n}\n\n/**\n * 同步「agent 开的会话」标签集合：宿主推来的清单里 owner=agent 且本地没有的\n * 建标签；本地有、宿主已不在的 agent 标签标记退出（用户可手动关掉）。\n */\n/**\n * 同步「agent 开的会话」标签集合（D97 / issue #7④：**标签生命周期 = 会话生命周期**）。\n *\n * 宿主 `sessions` 帧里三种状态各有归宿（判据在纯模块 `session-live.js`）：\n *   - **活着**（在表里、没退出）→ 不动；\n *   - **只读保留**（`exited: true`，D77：输出还能读）→ 标成已退出，标签留着（不遮罩）；\n *   - **表里没有**（agent 显式释放 `tty_close` / `tty_run` 收尾，或上限淘汰 / 宿主重启）\n *     → 标签跟着关。用户的标签不归这条规则管（`agentOwned` 才收）。\n *\n * 台阶（只有一种情况不给当场收）：被释放的那条**正是你此刻在看的标签**——先把它标成\n * `releasePending`，等你在顶部提示条上点「收起」或切走时再收（`switchTab` / 退出提示条）。\n * 后台的标签一律立即收走：这正是「AI 跑完一批命令，面板里留一堆死标签」的来源。\n */\nfunction syncAgentTabs(list) {\n  adoptAgentSessions(list)\n  if (!Array.isArray(list)) return\n  /*\n   * 先把「AI 开的」这个标记认领回来：页面刷新后从 sessionStorage 恢复的 agent 标签只带\n   * sid 与占位规格，`agentOwned` 丢了