essage 的 ready 分支），保证重连后宿主的位最终与标签一致。\n */\nfunction setTabHiddenFromAgent(sid, hidden) {\n  const tab = tabs.get(sid)\n  if (tab === undefined || tab.embedded === true) return\n  if (hidden === true && !canHideFromAgent(tab)) return\n  const next = hidden === true\n  if (isHiddenFromAgentSpec(tab.spawnSpec) === next) return\n  tab.spawnSpec = withHiddenFromAgent(tab.spawnSpec, next)\n  sendFrame({ t: 'hidden', sid, hidden: next })\n  persistTabs()\n  renderTabbar()\n  syncTabOverflow()\n}\n\n/**\n * 标签标题的显示文本（「对 AI 不可见」的标记在这里统一加，标签栏与「⋯」列表共用一处）。\n *\n * 标记用**一个字形**而不是 i18n 文案：标签栏宽度是稀缺资源（标签多了会溢出，见 D89/D90），\n * 而「对 AI 不可见」这句话留给 `title` 提示与右键菜单（那里放得下整句）。🙈 取「看不见」\n * 的意思——与状态点（连接态）分开表达，不把「隐私」塞进连接状态那个点里。\n */\nconst HIDDEN_TAB_GLYPH = '🙈'\nfunction tabDisplayLabel(sid) {\n  const tab = tabs.get(sid)\n  const base = tab === undefined ? '' : (tab.label || t('panel.tabLabel', { n: tabCounterLabel(sid) }))\n  if (tab === undefined || !isHiddenFromAgentSpec(tab.spawnSpec)) return base\n  return `${HIDDEN_TAB_GLYPH} ${base}`\n}\n\n/**\n * 持久标签在宿主侧已结束（宿主重启/保活超时）时的恢复：换新 sid 按原\n * spawnSpec（含原 persistName）重新 spawn —— 宿主 `tmux new-session -A` 按\n * 同名接回原会话现场；非持久标签不走这里（维持丢弃语义）。\n */\nfunction restoreTabAsNew(saved) {\n  const tab = {\n    sid: newSid(),\n    term: null,\n    fit: null,\n    search: null,\n    termEl: null,\n    overlayEl: null,\n    exited: false,\n    spawned: false,\n    spawnSpec: saved.spawnSpec,\n    label: typeof saved.label === 'string' ? saved.label : undefined,\n  }\n  createTerminal(tab)\n  tabs.set(tab.sid, tab)\n  tabCounter += 1\n  renderTabbar()\n  switchTab(tab.sid)\n  spawnTab(tab)\n}\n\n/** 退出后重开：换新 sid 重新 spawn（保留标签位，复用原 spawnSpec/label）。 */\nfunction respawnTab(oldSid) {\n  const old = tabs.get(oldSid)\n  if (old === undefined) return\n  if (old.embedded === true) {\n    // 嵌入终端没有「标签位」概念：原地重建，DOM 仍挂在调用方的容器里\n    respawnEmbedded(old)\n    return\n  }\n  const spawnSpec = old.spawnSpec\n  const label = old.label\n  sendFrame({ t: 'kill', sid: oldSid }) // D77：同上——重开等于放弃旧的只读保留会话，顺手释放\n  if (old.term !== null) {\n    try {\n      old.term.dispose()\n    } catch {\n      /* 忽略 */\n    }\n  }\n  if (old.termEl !== null) old.termEl.remove()\n  tabs.delete(oldSid)\n  const tab = { sid: newSid(), term: null, fit: null, search: null, termEl: null, overlayEl: null, exited: false, spawned: false, spawnSpec, label }\n  createTerminal(tab)\n  tabs.set(tab.sid, tab)\n  renderTabbar()\n  switchTab(tab.sid, { user: true })\n  spawnTab(tab)\n  persistTabs()\n}\n\n/**\n * 关掉一个标签。\n *\n * `options.silent`（#7④）：宿主**已经退役**了这条会话时用——那种情况下标签是本地残留的\n * 影子，再发 `kill` 只会打在一个已出表的 sid 上（宿主侧是个空操作）。默认为 false，\n * 也就是照 D77 的约定把「用户在面板里关标签 = 显式释放」告诉宿主，让只读保留的屏与\n * 缓冲立刻释放，而不是等上限淘汰。\n */\nfunction closeTab(sid, options) {\n  const tab = tabs.get(sid)\n  if (tab === undefined) return\n  const silent = options?.silent === true\n  // 挂载位归属这个标签：标签都没了，面板不能再留着——收起态的面板 DOM 还在，\n  // 里面的 SFTP 在途传输 / docker 轮询会继续对着已经关掉的连接干活，而且它的\n  // 归属标签永远回不来（切不回这个标签），等于一块看不见的僵尸面板。\n  if (dockPane !== null && dockPane.ownerKey === sid) teardownDockPane(true)\n  // D77：已退出的标签在宿主侧**仍挂着只读保留的会话**，关标签要把这件事告诉宿主、\n  // 让它立刻释放（屏与缓冲）；宿主那边到点也会自己收。旧行为之所以跳过：那时宿主\n  // 已经删了会话，kill 只会换来一个错误帧。\n  if (!silent) sendFrame({ t: 'kill', sid })\n  tabs.delete(sid)\n  statsHistory.delete(sid)\n  // 标签右键菜单描述的就是某个标签 / 某几个标签的条数：标签一关就作废（里面的批量行\n  // 会照着过期的名单关人），一律收掉\n  closeTabContextMenu()\n  // 会话没了，它的失败徽标也没什么可解释的了（浮层若正开着先收起）\n  if (assistMenuSid === sid) closeAssistMenu()\n  assistHints.delete(sid)\n  syncAssistBadge()\n  embeddedSids.delete(sid) // 兜底：嵌入终端正常走 disposeEmbedded，这里防漏\n  // 彻底移除：dispose xterm 实例并把 termEl（含错误/退出浮层）从面板拿走，\n  // 否则被关闭标签的幽灵 DOM 会叠在其它标签上\n  if (tab.term !== null) {\n    try {\n      tab.term.dispose()\n    } catch {\n      /* 忽略 */\n    }\n  }\n  if (tab.termEl !== null) tab.termEl.remove()\n  if (activeSid === sid) {\n    activeSid = null\n    // 只在普通标签里选邻居（0.19.0）：tabs 里还装着 dsh-docker 等挂进来的\n    // 嵌入会话，`[...keys()].pop()` 会选中它——标签栏没有它、普通终端全\n    // display:none（