stats) : null\n          tab.statsAt = Date.now()\n          /*\n           * 可选指标（温度 / Ping / Swap）按**会话**记一次「这台机器报过没有」（2026-11-01）：\n           * macOS / Windows 本地没有温度传感器、本地会话没有网络对端、没配 swap 的机器没有交换\n           * 分区——这些格子会永远是「无」，白占状态条的宽度（条上每个字符都是抢来的）。\n           * 判据是「这个会话**曾经**报过」，不是「这一帧有没有」：传感器偶发读失败不该让格子每秒闪一下。\n           */\n          const seenItems = tab.seenItems ?? (tab.seenItems = {})\n          if (statsNum(tab.stats, 'tempC') !== null) seenItems.tempC = true\n          if (statsNum(tab.stats, 'pingMs') !== null) seenItems.ping = true\n          if ((statsNum(tab.stats, 'swapTotal') ?? 0) > 0) seenItems.swap = true\n          // 趋势线历史（极简模式）：坏帧也记一帧「缺口」，不补值——线断开比假装平滑诚实\n          pushStatsHistory(sid, stats)\n          if (sid === activeSid) applyStatsBar()\n        }\n      } catch (error) {\n        console.warn('[dsh-tty] stats 帧处理失败（已忽略）: ' + (error instanceof Error ? error.message : String(error)))\n      }\n    } else if (msg.t === 'hint') {\n      /*\n       * AI 辅助（0.24.0）：宿主只在开关打开时推这帧，这里再判一次配置缓存——卡片刚关掉、\n       * 帧还在路上时不该再摆出一枚点了会报 403 的徽标。\n       */\n      if (!assistEnabledCache) return\n      if (msg.kind !== 'failure' || typeof sid !== 'string' || sid === '') return\n      assistHints.set(sid, {\n        exitCode: typeof msg.exitCode === 'number' ? msg.exitCode : null,\n        at: typeof msg.at === 'number' ? msg.at : Date.now(),\n        dismissed: false,\n        busy: false,\n        answer: null,\n        command: '',\n        error: null,\n      })\n      if (sid === activeSid) syncAssistBadge()\n    } else if (msg.t === 'error') {\n      setTabStatus(sid, t('status.error', { message: String(msg.m ?? '') }), 'error')\n      if (typeof sid === 'string') {\n        const tab = tabs.get(sid)\n        if (tab !== undefined) {\n          if (!tab.live) tab.errored = true // spawn/attach 失败：连接栏状态点转错误色\n          renderConnbar()\n          refreshTabDot(sid)\n          showTabOverlay(tab, t('status.errored'), t('status.retryHint', { message: String(msg.m ?? '') }), 'error')\n        }\n      } else {\n        showBodyOverlay(t('btn.clickRetry'))\n      }\n    }\n  }\n  socket.onclose = () => {\n    connecting = false\n    if (intentionalClose) return\n    setPanelStatus(t('status.disconnectedReconnecting'), 'error')\n    // 不再把未退出标签标记为 exited：会话在宿主保活，重连后 attach 恢复\n    for (const tab of tabs.values()) {\n      if (!tab.exited) showTabOverlay(tab, t('status.disconnected'), t('status.reconnecting'), 'info')\n    }\n    scheduleReconnect()\n  }\n  socket.onerror = () => {\n    /* onclose 会跟随触发 */\n  }\n}\n\nfunction showBodyOverlay(text) {\n  if (bodyOverlayEl === null) return\n  bodyOverlayEl.textContent = text\n}\n\n/**\n * 让终端面板**可见**：没有就创建，最小化中就恢复。\n *\n * 别把这里退回成 `if (modalEl === null) openModal()`：**最小化不是关闭**——`modalEl` 还在，\n * 于是内容会被加进一个隐藏的弹窗，消费方（dsh-docker 卡片上的「终端」按钮）看到的是\n * 「点了没反应」。`openModal()` 自己已经处理了「最小化中 → restoreModal()」，缺的只是有人叫它。\n * 实测复现：开一个 exec 标签 → 再开一个终端标签 → 最小化 → 再点 exec，毫无反应。\n */\nfunction ensureModalVisible() {\n  if (modalEl === null || minimized) openModal()\n}\n\n/**\n * 就地提权（免重启）用的能力名：与宿主侧 `CAP_PROXY_COMMAND.env` **必须一致**（宿主按它查表）。\n */\nconst ELEVATE_CAPABILITY = 'DSH_TTY_ALLOW_PROXY_COMMAND'\n\n/**\n * 授权时刻 → 固定格式 `YYYY-MM-DD HH:mm:ss`（本地时区）。\n *\n * 刻意不用 `toLocaleString()`：它给 `2026/9/26 22:37:30` 这种斜杠 + 不补零的形状，既不好扫读、\n * 也跟宿主日志里的 ISO 时刻对不上（这两处迟早要被对着看）。\n *\n * 为什么 docker 有一份、这里又写一份：仓规硬规矩 1 明令**插件之间不许互相 import**（`kit` 是\n * 宿主半体库，入口 import 了 `node:*`），能在浏览器侧共享的通道只有宿主服务本身。所以这段\n * 十几行的纯格式化在两侧各留一份，而不是为此建共享包。\n */\nfunction formatGrantedAt(seconds) {\n  const date = new Date(Number(seconds) * 1000)\n  if (Number.isNaN(date.getTime())) return String(seconds)\n  const pad = (value) => String(value).padStart(2, '0')\n  return `${String(date.getFullYear())}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`\n}\n\n/**\n * 剪贴板能力探测（0.19.0）：`navigator.clipboard` 在非 secure context（如\n * `http://<局域网IP>:3080`）下是 undefined——直接取属性/调用会抛 TypeError\n * （localhost 自测发现不了）。当前只服务「AI 辅助」浮层里的「复制答案」，\n * 终端自己的复制 / 粘贴走 xterm 的浏览器原生通路（选中后 Cmd+C / Ctrl+Shift+C、\n * Cmd+V / Ctrl+V），面板头部不再提供这两个按钮。\n */\nfunction clipboardAvailable() {\n  return typeof navigator !== 'undefined' && navigator.clipboard !== undefined && typeof navigator.clipboard.writeText === 'function'\n}\n\n/** 复制一段文本（写剪贴板，失败落到隐藏 textarea + execCommand）。 */\nasync function copyTerminalText(text) {\n  if (clipboardAvailable()) {\n    try {\n      await navigator.clipboard.writeText(text)\n      return true\n    } catch {\n      /* 权限被拒等：落到降级 */\n    }\n  }\n  const textarea = document.createElement('textarea')\n  textarea.value = text\n  textarea.style.position = 'fixed'\n  textarea.style.opacity = '0'\n  document.body.appendChild(textarea)\n  textarea.select()\n  let ok = false\n  try {\n    ok = document.execCommand('copy')\n  } catch {\n    ok = false\n  }\n  textarea.remove()\n  if (!ok) setStatus(t('error.copyFailed'), 'error')\n  return ok\n}\n\nfunction openModal() {\n  if (modalEl !== null) {\n    // 已在运行：最小化中则从悬浮条恢复，否则保持现状\n    if (minimized) restoreModal()\n    return\n  }\n  ensureStyle()\n\n  modalEl = document.createElement('div')\n  modalEl.className = 'tt_modalBackdrop'\n  modalEl.innerHTML =\n    '<div class=\"tt_modal\">' +\n    // 两行头部：标签行（图标 + 标签区 + 状态 + 工具/窗口按钮）+ SSH 连接栏\n    '<div class=\"tt_header\">' +\n    '<span class=\"tt_titleIcon\">' + TERMINAL_ICON + '</span>' +\n    // 标签区外壳（D89）：.tt_tabs 是 overflow-x:auto 的滚动容器，「+」只能在它**外面**\n    // （挂进去就成了滚动内容，跟着标签一起滚走）；外壳则负责吃掉剩余宽度，于是标签不多时\n    // 「+」还能紧贴最后一个标签，只有标签栏排满时才被顶到右端\n    '<div class=\"tt_tabbar\">' +\n    '<div class=\"tt_tabs\"></div>' +\n    // 标签栏溢出时才出现的「⋯」标签列表入口（显隐由 syncTabOverflow 维护；\n    // 注意 .tt_tabMore 的 display 是作者样式，必须自己写 [hidden] 兜底）。\n    // 它排在「+」**前面**：紧挨标签区右缘——被裁掉的那些标签就在那一侧，\n    // 而「+」是面板级动作，让它跟右边那排工具按钮待在一起。\n    '<button type=\"button\" class=\"tt_tabMore\" hidden></button>' +\n    '<button type=\"button\" class=\"tt_tabAdd\"></button>' +\n    '</div>' +\n    '<div class=\"tt_status\"><span class=\"tt_statusDot\"></span><span class=\"tt_statusText\">' + t('status.initializing') + '</span></div>' +\n    '<input class=\"tt_searchInput\" style=\"display:' + SEARCH_CLOSED_DISPLAY + '\" placeholder=\"' + t('placeholder.search') + '\" />' +\n    '<span class=\"tt_toolGroup\">' +\n    '<button class=\"tt_toolBtn tt_iconBtn\" data-act=\"stats\" title=\"' + t('stats.fullTitle') + '\">' + ICON_STATS_FULL + '</button>' +\n    '<button class=\"tt_toolBtn tt_iconBtn\" data-act=\"search\" title=\"' + t('btn.searchTitle') + '\">' + ICON_SEARCH + '</button>' +\n    '<button class=\"tt_toolBtn tt_iconBtn\" data-act=\"clear\" title=\"' + t('btn.clearTitle') + '\">' + ICON_CLEAR + '</button>' +\n    '</span>' +\n    '<span class=\"tt_winGroup\">' +\n    '<button class=\"tt_min\" title=\"' + t('btn.minimizeTitle') + '\">' + ICON_MIN + '</button>' +\n    '<button class=\"tt_close\" title=\"' + t('btn.closePanelTitle') + '\">' + ICON_CLOSE + '</button>' +\n    '</span>' +\n    '</div>' +\n    // 连接栏：左侧连接状态，右侧 SFTP / 扩展按钮；本地终端时隐藏（renderConnbar 控制）\n    '<div class=\"tt_connbar\" data-hidden><div class=\"tt_connArea\"><span class=\"tt_connDot\"></span><span class=\"tt_connTarget tt_connTargetOpen\" role=\"button\" tabindex=\"0\">—</span><span class=\"tt_connBadge\"></span><span class=\"tt_connBadge tt_connJump\"></span></div><div class=\"tt_connActions\"></div></div>' +\n    // 终端区与「右侧挂载位」并排：其他插件（如 dsh-docker）经 ttyPanel.mountPane\n    // 把界面挂进 .tt_work，终端保持可见——这是从 SSH 连接栏打开容器面板的主路径\n    '<div class=\"tt_work\">' +\n    // 状态条（0.17.0）与终端容器同级：绝对定位在 body 顶部，显隐只改 .tt_term 的\n    // top 偏移——不能塞进 .tt_term 里，否则 FitAddon 会把条高算进行数\n    '<div class=\"tt_body\"><div class=\"tt_statsBar\" hidden><div class=\"tt_statsScroll\"></div><button type=\"button\" class=\"tt_statsExpand\" data-act=\"stats-expand\" data-state=\"closed\" aria-expanded=\"false\" title=\"' + t('statsDash.open') + '\" aria-label=\"' + t('statsDash.open') + '\">' + ICON_STATS_EXPAND + '</button></div><div class=\"tt_exitBar\" hidden></div><button type=\"button\" class=\"tt_assistBadge\" hidden><span class=\"tt_assistDot\"></span><span class=\"tt_assistBadgeText\"></span></button><div class=\"tt_overlay\"></div></div>' +\n    '</div>' +\n    '</div>'\n  document.body.appendChild(modalEl)\n\n  statusChipEl = modalEl.querySelector('.tt_status')\n  statusEl = modalEl.querySelector('.tt_statusText')\n  statusDotEl = modalEl.querySelector('.tt_statusDot')\n  tabbarEl = modalEl.querySelector('.tt_tabs')\n  /*\n   * 「+」新建按钮（D89）：**不能挂进 `.tt_tabs`**——那是个 overflow-x:auto 的横向滚动\n   * 容器，挂进去它就成了滚动内容的一部分：标签一多就被推着走，甚至整颗滚出可视区\n   * （想新建得先把标签栏滚到底）。它是滚动容器的兄弟，位置由外壳 `.tt_tabbar` 决定：\n   * `.tt_tabs` 是 `flex: 0 1 auto`（不撑满），所以标签不多时「+」紧贴最后一个标签，\n   * 只有标签栏排满时才被顶到标签区右端（那时它也必须**停在可视区内**）。\n   * 这里接线一次即可——renderTabbar 每次重建的是标签，不再重建它。\n   */\n  const tabAddEl = modalEl.querySelector('.tt_tabAdd')\n  if (tabAddEl !== null) {\n    tabAddEl.title = t('btn.newTab')\n    tabAddEl.innerHTML = ICON_PLUS\n    tabAddEl.addEventListener('click', () => {\n      openAddMenu(tabAddEl)\n    })\n  }\n  tabMoreEl = modalEl.querySelector('.tt_tabMore')\n  if (tabMoreEl !== null) {\n    tabMoreEl.innerHTML = ICON_MORE\n    tabMoreEl.title = t('btn.tabList')\n    tabMoreEl.addEventListener('click', () => {\n      openTabListMenu(tabMoreEl)\n    })\n  }\n  // 标签栏溢出（0.23.0）：滚动条已隐藏，改由两侧渐隐提示；滚轮纵向 delta 手动换轴\n  tabbarEl.addEventListener('scroll', syncTabOverflow)\n  tabbarEl.addEventListener('wheel', onTabbarWheel, { passive: false })\n  // 批量关标签（0.29.0）：右键 = 以这个标签为参照（关闭其他 / 左侧 / 右侧），中键 = 直接关。\n  // 监听挂在外壳上做委托：`.tt_tab` 是每次 renderTabbar 重建的\n  tabbarEl.addEventListener('contextmenu', onTabbarContextMenu)\n  tabbarEl.addEventListener('auxclick', onTabbarAuxClick)\n  connbarEl = modalEl.querySelector('.tt_connbar')\n  connDotEl = modalEl.querySelector('.tt_connDot')\n  connTargetEl = modalEl.querySelector('.tt_connTarget')\n  connBadgeEl = modalEl.querySelector('.tt_connBadge')\n  connJumpBadgeEl = modalEl.querySelector('.tt_connJump')\n  connActionsEl = modalEl.querySelector('.tt_connActions')\n  // 左侧地址 = 「连接详情」的入口：鼠标点、键盘 Enter / 空格都能开（它是 role=button 的 span，\n  // 不是真按钮——真按钮会带宿主的按钮内边距，撑变这枚输入框形状的胶囊）。\n  const onConnTargetActivate = (event) => {\n    if (event.type === 'keydown' && event.key !== 'Enter' && event.key !== ' ') return\n    const tab = activeTab()\n    if (tab === undefined) return\n    event.preventDefault()\n    openConnDetailPopover(connTargetEl, tab)\n  }\n  connTargetEl.addEventListener('click', onConnTargetActivate)\n  connTargetEl.addEventListener('keydown', onConnTargetActivate)\n  workEl = modalEl.querySelector('.tt_work')\n  bodyEl = modalEl.querySelector('.tt_body')\n  statsBarEl = modalEl.querySelector('.tt_statsBar')\n  statsScrollEl = modalEl.querySelector('.tt_statsScroll')\n  bindStatsScrollEvents(statsScrollEl)\n  statsExpandEl = modalEl.querySelector('.tt_statsExpand')\n  if (statsExpandEl !== null) statsExpandEl.addEventListener('click', onStatsExpandClick)\n  statsToggleEl = modalEl.querySelector('[data-act=stats]')\n  if (statsToggleEl !== null) statsToggleEl.addEventListener('click', onStatsToggleClick)\n  exitBarEl = modalEl.querySelector('.tt_exitBar')\n  exitBarRenderKey = ''\n  // 新面板 = 新的（空的）状态条节点：上一份条目引用与数据签名一起作废，下次显示重建\n  discardStatsItems()\n  statsSubSid = null\n  ensureStatsStaleTimer()\n  bodyOverlayEl = modalEl.querySelector('.tt_body > .tt_overlay')\n  /*\n   * 失败徽标（0.24.0）：由 hint 帧点亮，点它才去问模型。节点每个面板一枚（不随标签走），\n   * 显隐由 syncAssistBadge 按**活动标签**裁决。\n   */\n  assistBadgeEl = modalEl.querySelector('.tt_assistBadge')\n  if (assistBadgeEl !== null) {\n    assistBadgeEl.addEventListener('click', () => {\n      if (assistBadgeEl !== null) openAssistMenu(assistBadgeEl)\n    })\n  }\n  closeAssistMenu()\n  syncAssistBadge()\n  searchInputEl = modalEl.querySelector('.tt_searchInput')\n\n  bodyOverlayEl.addEventListener('click', () => {\n    bodyOverlayEl.textContent = ''\n    connect()\n  })\n  const searchBtn = modalEl.querySelector('[data-act=search]')\n  // 开合与按下态都在 setSearchOpen 里（它自己会聚焦，这里不再补一次）\n  searchBtn.addEventListener('click', () => {\n    toggleSearch()\n  })\n  searchInputEl.addEventListener('keydown', (event) => {\n    if (event.key === 'Enter') {\n      event.preventDefault()\n      doSearch(event.shiftKey)\n    } else if (event.key === 'Escape') {\n      // 只收起搜索框：阻断冒泡，避免文档级 Esc 处理器把整个面板最小化\n      event.stopPropagation()\n      setSearchOpen(false)\n    }\n  })\n  modalEl.querySelector('[data-act=clear]').addEventListener('click', () => {\n    const tab = activeTab()\n    if (tab !== undefined && tab.term !== null) tab.term.clear()\n  })\n  modalEl.querySelector('.tt_min').addEventListener('click', () => {\n    minimizeModal()\n  })\n  // ✕ 是破坏性动作（结束全部会话）：有活会话时先问一句（issue #8），见 requestClosePanel\n  modalEl.querySelector('.tt_close').addEventListener('click', () => {\n    requestClosePanel()\n  })\n  // 点空白处 = 最小化而不是关闭：会话保活，随时从悬浮条恢复。\n  // 确认层开着时不生效——那时用户面对的是一个待回答的问题，不该被顺手最小化掉。\n  modalEl.addEventListener('mousedown', (event) => {\n    if (confirmEl !== null) return\n    if (event.target === modalEl) minimizeModal()\n  })\n  document.addEventListener('keydown', onModalKeydown)\n\n  resizeObserver = new ResizeObserver(() => {\n    if (minimized) return // display:none 下 fit 尺寸无意义，恢复时统一重算\n    // 面板变窄/变矮时 dock 也要跟着收（否则会把终端挤到没有位置）\n    applyDockGeometry()\n    refitTerminal(activeTab())\n    // 面板变窄会让标签栏从「不溢出」变成「溢出」（反之亦然）：渐隐与「⋯」入口都要重算。\n    // 这条不能只挂在 scroll 上——宽度变化根本不产生 scroll 事件。\n    syncTabOverflow()\n  })\n  resizeObserver.observe(bodyEl)\n\n  // 首帧渲染：标签区的「+」要立即可见；连接栏按当前标签决定显隐\n  renderTabbar()\n  renderConnbar()\n\n  // 连接可能已经因为嵌入终端而存在：复用它，并把面板自己的标签/恢复流程补上\n  if (socket !== null && socket.readyState === WebSocket.OPEN) void afterSocketOpen()\n  else connect()\n}\n\n/** 右下角悬浮条：展示会话数 / 连接状态，点击恢复窗口。 */\n/** 悬浮条上的「运行中 / 总数」：关标签、会话退出、宿主推 agent 会话时都要跟着更新。 */\nfunction refreshDockCount() {\n  if (dockCountEl === null) return\n  const running = [...tabs.values()].filter((tab) => !tab.exited).length\n  dockCountEl.textContent = tabs.size > 0 ? '· ' + running + '/' + tabs.size : ''\n}\n\nfunction buildDock() {\n  dockEl = document.createElement('div')\n  dockEl.className = 'tt_dock'\n  dockEl.title = t('btn.restoreDock')\n  dockEl.innerHTML =\n    '<span class=\"tt_dockTitle\">' + TERMINAL_ICON + '<span>' + t('panel.title') + '</span><span class=\"tt_dockCount\"></span></span>' +\n    '<span class=\"tt_dockStatus\"></span>' +\n    '<span class=\"tt_dockDot\"></span>' +\n    '<button class=\"tt_dockClose\" title=\"' + t('btn.closePanelTitle') + '\">' + ICON_CLOSE_SM + '</button>'\n  dockCountEl = dockEl.querySelector('.tt_dockCount')\n  dockStatusEl = dockEl.querySelector('.tt_dockStatus')\n  dockDotEl = dockEl.querySelector('.tt_dockDot')\n  refreshDockCount()\n  // 快照当前状态（此后 setStatus 会持续同步）\n  if (statusEl !== null) dockStatusEl.textContent = statusEl.textContent\n  if (statusDotEl !== null) dockDotEl.dataset.state = statusDotEl.dataset.state ?? ''\n  dockEl.addEventListener('click', (event) => {\n    if (event.target.closest('.tt_dockClose') !== null) {\n      event.stopPropagation()\n      requestClosePanel()\n      return\n    }\n    restoreModal()\n  })\n  document.body.appendChild(dockEl)\n}\n\n/** 最小化：隐藏弹窗但保留 DOM / WebSocket / xterm 缓冲；状态合并进侧边栏入口。 */\nfunction minimizeModal() {\n  if (modalEl === null || minimized) return\n  closeAddMenu()\n  closeTabListMenu()\n  closeAssistMenu()\n  closeSshDialog()\n  // SFTP 不关（0.19.0）：挂载位 pane 随面板显隐走（挂载位契约「面板最小化 /\n  // 恢复跟着走，消费者不需要做任何事」），收起态的 SFTP 浮层藏起、恢复时放回\n  // ——最小化只是想看别的窗口，不该把在途传输取消掉（远端留半截文件）\n  minimized = true\n  if (sftpDialogEl !== null) sftpDialogEl.style.display = 'none'\n  // 收起面板也收起搜索框（开合与放大镜按下态一起走 setSearchOpen，别手动改 display）\n  setSearchOpen(false)\n  modalEl.dataset.minimized = ''\n  // 最小化 = 没有可见终端：退订（宿主侧停表、关远端 exec channel），收起状态条，\n  // 陈旧检测定时器一并停（0.19.0：此前只在 closeModal 停，最小化期间空转）\n  stopStatsStaleTimer()\n  syncStatsSubscription()\n  applyStatsB