 setModelCatalog({ groups: [], loading: false, failed: true })\n  }\n  React.useEffect(() => {\n    if (open && !loaded) {\n      setLoaded(true)\n      void load()\n      void loadShellOptions()\n      void loadModelCatalog()\n    }\n  }, [open])\n\n  const set = (key, value) => setForm((current) => {\n    const next = { ...(current || {}), [key]: value }\n    formRef.current = next\n    return next\n  })\n  /**\n   * 表单 → 保存 payload。**也是「脏不脏」的比较口径**：只有这些键会被写进去，所以授权到达后的\n   * 自动保存只在**干净**表单下做——保存是整表提交，脏表单里自动保存会静默写入用户没打算提交的编辑。\n   * `save()` 与脏检查共用这一份，避免两处各拼一遍「要提交哪些键」（那正是漂的种子）。\n   */\n  /*\n   * 快照里**不是配置项**的键（宿主会以「未知配置项」拒绝）：派生的授权状态、宿主平台、shell\n   * 集成的可注入性。\n   *\n   * D91 起这张表是**否定清单**，其余键**默认提交**。原先写的是肯定清单（一个一个列要提交的\n   * 键），代价就是**新增 volatile 字段必须记得回来补**——`assistEnabled` 正是这么漏的：宿主\n   * 侧压根没收到它，卡片上「保存后又弹回去」。否定清单漏一个的后果是宿主**响亮地**报\n   * 「未知配置项: X」，而不是静默丢掉一个字段。\n   *\n   * 但「响亮」只在**有人点保存**时才响亮：单测与 CI 都不拿整份快照回提交，所以漏登记的派生\n   * 字段会让卡片**每一次保存**都 400 而闸门全绿（`shellIntegrationSupported` 就这么漏过一次）。\n   * 现算的守卫在 `test/config-roundtrip.test.ts` 的「整份快照回提交必须 200」那条——它直接\n   * 读本文件的这份清单，两边不可能各写一份。\n   */\n  const NON_CONFIG_KEYS = new Set(['toolsRegistered', 'platform', 'shellIntegrationSupported', 'allowProxyCommandGranted', 'allowProxyCommandGrantSource', 'allowProxyCommandGrantedAt'])\n  const toPayload = (source) => {\n    const body = {}\n    for (const [key, value] of Object.entries(source || {})) {\n      if (NON_CONFIG_KEYS.has(key)) continue\n      // 空串照常提交：`assistProvider` / `assistModel` 的**空串是「清空路由」这个真实意图**；\n      // 而 shell / term / cwd 那一类由宿主侧丢弃空串（normalizePatch 里逐个判过），提交了也无害\n      if (value === undefined) continue\n      body[key] = value\n    }\n    body.sshHosts = Array.isArray(source?.sshHosts) ? source.sshHosts : []\n    body.tunnels = Array.isArray(source?.tunnels) ? source.tunnels : []\n    // sftpLimits：对象整体提交（宿主按字段校验；0 = 不限）\n    if (source?.sftpLimits && typeof source.sftpLimits === 'object') {\n      body.sftpLimits = {\n        maxDownloadMb: Number(source.sftpLimits.maxDownloadMb) || 0,\n        maxUploadMb: Number(source.sftpLimits.maxUploadMb) || 0,\n        maxUploadFiles: Number(source.sftpLimits.maxUploadFiles) || 0,\n      }\n    }\n    return body\n  }\n  formRef.current = form\n  /** sftpLimits 单项更新（函数式合并，避免连续编辑覆盖）。 */\n  const setSftpLimit = (key, value) => setForm((current) => ({\n    ...(current || {}),\n    sftpLimits: { ...((current?.sftpLimits) ?? {}), [key]: value },\n  }))\n  const [editing, setEditing] = React.useState(null)\n  const [editForm, setEditForm] = React.useState(null)\n  const [editError, setEditError] = React.useState('')\n  /**\n   * 编辑表单里的凭据引用候选（连接簿在用的 `env:` 名字 ∪ 凭据存储里的名字）：\n   * 进入编辑时拉一次，与连接对话框的引用选择器**同一份候选**（见 credentialRefCandidates）。\n   * `null` = 还没问到（这一行先不显形，免得先闪一下\"零候选\"再换成输入框）。\n   */\n  const [credNames, setCredNames] = React.useState(null)\n  /** 引用选择器展开在哪一行（'' = 不收）；筛选框内容与「再点覆盖」的确认态跟着它走。 */\n  const [credPicker, setCredPicker] = React.useState('')\n  const [credFilter, setCredFilter] = React.useState('')\n  const [credConfirm, setCredConfirm] = React.useState('')\n  const credConfirmTimer = React.useRef(null)\n  /** 「应用时存入凭据存储」：默认勾选（宿主提供 remote.credentials 时），与对话框同款默认。 */\n  const [credRemember, setCredRemember] = React.useState(false)\n  const [credStatus, setCredStatus] = React.useState({ text: '', kind: '' })\n  const [credClearable, setCredClearable] = React.useState(false)\n  /** 编辑表单里的试连结果（测的是**尚未应用**的填写，对话框「试连」同款）。 */\n  const [editProbe, setEditProbe] = React.useState({ running: false, ok: false, text: '' })\n  /** 连接簿条目「测试」状态：{ [name]: { running:boolean, ok?:boolean, text:string } }。 */\n  const [probeStates, setProbeStates] = React.useState({})\n  /** 隧道实时状态（卡片展开期间 2s 轮询 /api/dsh-tty/tunnels）。 */\n  const [tunnelStatus, setTunnelStatus] = React.useState([])\n  const [tunnelDraft, setTunnelDraft] = React.useState({ direction: 'local', localPort: '', remoteHost: '', remotePort: '', localTargetPort: '', bookName: '' })\n  /**\n   * 正在编辑的隧道**原始 name**（null = 新