                  ],\n                }),\n              ] }),\n        ],\n      }) : null,\n    ],\n  })\n}\n\n\n    exports.inject = ['slots', 'sessions']\n\n    /**\n     * DSH ≥0.1.6-alpha.2 的行配置 key：`<bundle 包名>#<行 id>`，行 id 取自 bundle 的\n     * cordis.patch.yml。独立安装时 bundle 是本包，装全家桶时是 @hyzyn/dsh-all —— 两个都注册，\n     * 未命中的那个只是躺在 ledger 里，不会渲染。\n     */\n    const ROW_CONFIG_KEYS = [\n      '@hyzyn/dsh-tty#tty',\n      '@hyzyn/dsh-all#tty',\n    ]\n    exports.apply = (ctx) => {\n      installI18n(ctx)\n      sessionsService = ctx.sessions\n      /*\n       * 官方凭据引用的浏览器侧命名空间（可选）。\n       *\n       * **必须同时声明 `remote.credentials`**：命名空间不是 `remote` 上的普通属性，而是网关\n       * 安装的**独立服务**（`remoteServiceKey(ns)` = `remote.<ns>`，见 dsh-api-gateway）——\n       * 只声明 `remote` 时 `remote.credentials` 就是 undefined（实测踩过：界面会把锅甩给宿主，\n       * 显示\"宿主未提供凭据服务\"，其实是自己的依赖没声明）。\n       *\n       * 用 `ctx.inject` 而不是静态 `exports.inject`：没装 / 老宿主上回调不触发，插件照常加载，\n       * 对话框那一行自己降级。\n       */\n      ctx.inject(['remote', 'remote.credentials'], (remoteCtx) => {\n        // 两种取值都试一遍：命名空间是**独立服务**（`remote.credentials`），网关同时把它挂在\n        // `remote` 上供消费方嵌套访问（官方设置卡片用的是 `ctx.remote.credentials.*`）。\n        credentialsRemote = remoteCtx.remote?.credentials ?? remoteCtx['remote.credentials'] ?? null\n        return () => { credentialsRemote = null }\n      })\n      // 侧栏入口先按可见挂载（与旧行为一致），config 确认禁用后由闸门收起；\n      // 运行期显隐由 syncSshHostsCache（各处 config 拉取/保存共用出口）驱动\n      let entryMounted = false\n      let unmountEntry = () => {}\n      entryGate = {\n        set(visible) {\n          if (visible === entryMounted) return\n          entryMounted = visible\n          if (visible) {\n            unmountEntry = mountSidebarEntry()\n            return\n          }\n          unmountEntry()\n          unmountEntry = () => {}\n          // 禁用瞬间的终端面板一起收掉：存量 WS 已被服务端关闭，面板留着只会不停重连失败\n          closeModal()\n          renderConnbar()\n        },\n      }\n      setEntryVisible(true)\n      // 挂载时拉一次 config：预热连接簿缓存 + 驱动入口显隐（失败静默，各入口打开时会再拉）\n      void refreshSshHosts()\n      /*\n       * 设置面：0.2.0-rc.1 起挂 `plugins.bundle.config`——key 是 **bundle 包名**，管理器的插件\n       * 详情页把它渲染在「说明」正下方；`plugins.row.config` 是 per-row 的「>」子页。\n       *\n       * 两条硬约束（第一条踩过坑，见下）：\n       *   ① `plugins.bundle.config` 的 key 是**共享命名空间**：同一个 key 只能有一个注册者，\n       *      重复注册**直接抛错**（`keyed slot ... already has an entry`），而客户端 `apply`\n       *      抛错 = 整个插件起不来（实测：把 `@hyzyn/dsh-all` 也挂上时，八个插件抢同一个 key，\n       *      启动页直接变「Failed to load plugins」）（D158）。聚合包 `@hyzyn/dsh-all` 是所有插件共用的\n       *      bundle，**不能**挂 bundle.config —— 它没有内联位，设置面走它自己的 row 入口。\n       *   ② 内联位可用时，**本包自己的** bundle 不再注册 row 槽（同一份表单两个入口会让人以为\n       *      有两套设置）；聚合包那份 row 入口**保留**（那是它在聚合安装下的唯一入口）。旧宿主\n       *      （bundle 槽不存在，0.1.6 线）回退注册全部 row 槽，功能一点不减。\n       * 就绪顺序不敏感：任一侧先到都收敛到「内联优先」（后到的本包 row 注册会被撤掉）。\n       */\n      const AGGREGATE_BUNDLE = '@hyzyn/dsh-all'\n      const BUNDLE_NAMES = [...new Set(ROW_CONFIG_KEYS.map((key) => key.split('#')[0]))]\n      const OWN_BUNDLE = BUNDLE_NAMES.find((name) => name !== AGGREGATE_BUNDLE)\n      let bundleConfigLive = false\n      const disposeOwnRowConfigs = []\n      if (OWN_BUNDLE !== undefined) {\n        ctx.slots.inject('plugins.bundle.config', () => {\n          bundleConfigLive = true\n          while (disposeOwnRowConfigs.length > 0) {\n            const disposeRow = disposeOwnRowConfigs.pop()\n            if (typeof disposeRow === 'function') disposeRow()\n          }\n          return ctx.slots.register({\n            name: 'plugins.bundle.config',\n            key: OWN_BUNDLE,\n          }, TtySettingsCard)\n        })\n      }\n      for (const key of ROW_CONFIG_KEYS) {\n        ctx.slots.inject('plugins.row.config', () => {\n          const own = key.split('#')[0] === OWN_BUNDLE\n          if (own && bundleConfigLive) return undefined\n          const disposeRow = ctx.slots.register({\n            name: 'plugins.row.config',\n            key,\n          }, TtySettingsCard)\n          if (own) disposeOwnRowConfigs.push(disposeRow)\n          return disposeRow\n        })\n      }\n      // DSH ≥0.1.6：设置里与「通用设置」平级的「插件配置」页（子 slot 由\n      // @hyzyn/dsh-kit-settings 声明）。不传 view，卡片走各自原有的可折叠形态。\n      ctx.slots.inject('settings.kit.item', () => ctx.slots.register({\n        name: 'settings.kit.item',\n        id: 'tty',\n        order: 80,\n        label: () => t('card.name'),\n      }, TtySettingsCard))\n      // DSH ≤0.1.5：设置 → 插件 的「插件配置」标签页，keyed 插槽按 settings 命名空间派发。\n      ctx.slots.inject('settings.plugin.item', () => ctx.slots.register({\n        name: 'settings.plugin.item',\n        // settings.plugin.item 是 keyed 插槽：key 必须是该卡片所编辑的 settings 命名空间\n        key: 'tty',\n        order: 100,\n      }, TtySettingsCard))\n      // 连接栏按钮注册点：其他插件（如 dsh-docker）经 ctx.inject(['ttyConnbar'])\n      // 注册上下文按钮；内置动作也走同一通道，tty 不感知具体插件\n      const disposeConnbar = ctx.provide('ttyConnbar', {\n        /** 契约版本：1 = addAction + requestRender（payload 见 README「客户端服务契约」）。 */\n        version: 1,\n        addAction: registerConnbarAction,\n        requestRender() {\n          renderConnbar()\n        },\n      })\n      // 终端服务（0.14.0 起）：其他插件（如 dsh-docker）可以「跑一条命令拿一个终端」，\n      // 用于 `docker exec -it <容器> sh` 这类交互式进入。两个入口：\n      //   open  —— 在 tty 面板里新开一个标签（会弹面板，命令标签随之持久化重跑）\n      //   mount —— 把终端挂进调用方自己的容器（就地嵌入，不弹面板、不进标签栏）\n      // 契约见 README「客户端服务契约」；消费方应按 version 校验后再用。\n      const disposeTerminal = ctx.provide('ttyTerminal', {\n        /** 契约版本：1 = open；2 = 增加 mount（就地嵌入）；3 = open 默认复用同连接同命令的标签。 */\n        version: 3,\n        /**\n         * 新开标签并执行命令。options：\n         *   command（必填，单行）· book（连接簿条目名，走 SSH）·\n         *   spec（内联 SSH 字段，走 SSH）· label（标签名）· cwd（本地标签工作目录）·\n         *   reuse（默认 true：同「连接 + 命令」已有活标签就聚焦它，不再新开）\n         * 三者互斥：book > spec > 本地。返回被打开或被复用的标签。\n         */\n        open(options) {\n          // 插件禁用时不提供终端能力（服务端 WS 闸门也会拒绝 spawn）\n          if (!entryVisible) return\n          const command = normalizeTerminalCommand(options)\n          const spawnSpec = buildTerminalSpec(options, command)\n          const label = typeof options?.label === 'string' && options.label !== '' ? options.label : undefined\n          ensureStyle()\n          /*\n           * 复用：同一个「连接 + 命令」再开一次 = **聚焦已有标签**，不再堆一个重复的。\n           *\n           * 动机是实测：容器卡片「终端」按钮连点几下就冒出三个一模一样的 exec 标签，而每个\n           * 标签各占一个会话名额——并发上限被白白吃光，接着满屏都是「会话数已达上限」。\n           * 真想要并列两个同样的会话，传 `reuse: false` 显式声明。\n           */\n          if (options?.reuse !== false) {\n            const existing = findReusableTab(spawnSpec)\n            if (existing !== null) {\n              ensureModalVisible()\n              switchTab(existing.sid, { user: true })\n              return existing\n            }\n          }\n          // 最小化中也要恢复（否则标签加进隐藏的弹窗里，用户看到\"点了没反应\"）\n          ensureModalVisible()\n          return addTab(spawnSpec, label)\n        },\n        /**\n         * 把终端挂进 hostEl（就地嵌入，0.15.0）。options 与 open 相同，额外：\n         * hostEl 需是 HTMLElement（挂载点，建议 position:relative、有确定尺寸）。\n         * 返回 dispose()：调用方在收起自己的容器时调用，结束会话并卸载 DOM。\n         * 嵌入终端与面板标签共用连接，但 tty 面板关闭不会波及它。\n         */\n        mount(hostEl, options) {\n          if (!entryVisible) return () => {}\n          return mountTerminal(hostEl, options)\n        },\n      })\n      // 面板内挂载位（0.16.0）：其他插件在终端面板右侧挂一块自己的界面（dsh-docker\n      // 的容器面板就走这里），终端保持可见。契约见 README「客户端服务契约」。\n      const disposePanel = ctx.provide('ttyPanel', {\n        /** 契约版本：2 = 增加 minimize()（1 = mountPane + isOpen）。 */\n        version: 2,\n        /** 面板是否正开着（最小化不算）：调用方据此决定挂进来还是走自己的弹窗。 */\n        isOpen() {\n          return modalEl !== null && !minimized\n        },\n        /**\n         * 挂一块 pane（同一时刻只有一个，返回的 handle 见函数注释）。\n         *\n         * `options.ownerSid`（0.18.4，可选）：这块 pane 归属哪个标签——默认当前活动\n         * 标签；切换标签时归属别的标签的 pane 会**收起**（DOM 与你 render 的树都保活，\n         * 切回来即恢复），传 `null` 表示不隶属任何标签（永远可见）。\n         */\n        mountPane(options) {\n          return mountDockPane(options)\n        },\n        /**\n         * 最小化整个终端面板：弹窗藏起来，但 DOM / WebSocket / xterm 缓冲全保留、会话继续\n         * 跑；恢复靠侧边栏「终端」入口（那上面会挂徽标与状态点）。\n         *\n         * 消费方用它「把舞台让出去」——典型是 dsh-docker 把日志交给会话之后，自动折起终端\n         * 让用户看到会话，而不是对着一个盖住会话的弹窗猜「点了没有反应」。\n         *\n         * @returns 调用之后面板是否处于最小化态（没开、已最小化、或状态不允许时返回 false，\n         *   调用方据此决定要不要把指引写进提示文案）。\n         */\n        minimize() {\n          minimizeModal()\n          return modalEl !== null && minimized\n        },\n      })\n      return () => {\n        entryGate = null\n        entryVisible = false\n        unmountEntry()\n        disposePanel()\n        disposeTerminal()\n        disposeConnbar()\n        closeModal()\n      }\n    }\n    return exports\n  },\n})\n"
    },
    {
      "path": "packages/kit/src/tier-gate.ts",
      "content": "/**\n * 插件工具的**会话权限档位闸**（tier gate）。\n *\n * ## 这一层要解决的问题\n *\n * DSH 会话有权限档位菜单（仅可查看 / 工作区内修改 / 完全权限 / Auto review），它只约束宿主\n * 自带的 bash / fs 工具；本仓插件的 agent 工具（`tty_*` / `sftp_*` / `tunnel_*` / `docker_*`）\n * 完全不受档位约束——`tty_run` / `tty_send` 是**无沙箱**的任意命令执行面，模型用它跑 bash 被\n * 沙箱拒绝的同一条命令会直接生效。本模块把档位接进插件工具：**每次调用**解析会话的有效档位\n * （`sandbox/mode` × `approval/policy` 两个会话旋钮），按「分类表 × 档位」矩阵决定 放行 / 询问 /\n * 拒绝。方案与运行时证据见 `docs/permission-tier-plan.md`（仓内路径，随包发布后不保证可点）。\n *\n * ## 两层的分工（与 capability.ts 的关系）\n *\n * `allowMutations` / `allowExec` / `allowProxyCommand`（capability.ts）管**注册不注册**：宿主级、\n * 启动期判定、带外授权、持久生效。本模块管**已注册的这一次调用放不放行**：逐调用、会话级、\n * 随档位即时变。双层并存，先注册后闸——谁也不取代谁。\n *\n * ## 约定\n *\n * 1. **只读旋钮，不读档位名**：preset 键名（`readOnly` 之类）是部署配置不是契约；唯一读名字的\n *    地方是 auto 检测（`permissionPresets.current(session) === 'auto'`），服务缺了就按矩阵走。\n * 2. **完全权限档零询问**（`decideTierCall` 的硬分支）：该档的审批策略是 `never`，此时返回\n *    `ask` 会被宿主确定性拒绝——不是保守，是把工具问死的事故。\n * 3. **服务未组合 = 不闸**（与今天的现状一致），但 `attachTierGate` 会打一行启动审计；\n *    调用期解析**抛错**同样按现状放行并打告警——档位闸宁可退化成现状，不砖掉工具面。\n *    这两条边界都写进了各包 README 的安全假设。\n * 4. **监听器永不 claim `allow`**：要么 `next()` 透传，要么返回 `deny` / `ask`。插件只是\n *    拦截人，不是放行人——auto review 等同瀑布的其它监听者不会被插件短路。\n * 5. **deny / ask 的文案**：模型要能分清「档位拒绝」（本模块）与「审批拒绝」（宿主\n *    `serviceAsk`）与「静态能力未授权」（capability.ts 的 400 文案）。ask 不由插件记审计——\n *    `approval/asked` + `approval/decided` 成对落会话日志是宿主的职责。\n * 6. **分类表归插件**：kit 不知道工具名；`classify` 由插件传入，返回 `undefined`（名单外）=\n *    放行 + 每工具名一条告警。名单对账由各包守卫测试从注册处现算（漏分类 → 测试红）。\n */\nimport type { Context } from '@deepseek-ai/cordis'\n\n/** 工具的风险类：`read` 纯读；`write` 有界变更；`exec` 无界命令面（本机或远程 shell、监听端口）。 */\nexport type TierClass = 'read' | 'write' | 'exec'\n\n/** 会话沙箱档（`@deepseek-ai/dsh-sandbox` 的 `SandboxMode`，结构化重声明——kit 不依赖宿主包）。 */\nexport type TierMode = 'read-only' | 'workspace-write' | 'danger-full-access'\n\n/** 会话审批策略（`@deepseek-ai/dsh-user-approval` 的 `ApprovalPolicy`）。 */\nexport type TierPolicy = 'ask' | 'never'\n\n/** 档位闸依赖的两个宿主服务各自是否已组合。 */\nexport interface TierServices {\n  sandboxPolicy: boolean\n  approval: boolean\n}\n\n/** 一次调用解析出的会话档位。 */\nexport interface TierContext {\n  mode: TierMode\n  policy: TierPolicy\n  /** Auto review（实验）档：宿主的模型预审已在逐调用审查，插件让位（等同 allow）。 */\n  auto: boolean\n  services: TierServices\n}\n\n/** 档位闸对一次调用的决定。 */\nexport type TierDecision =\n  | { action: 'allow' }\n  | { action: 'deny'; reason: string }\n  | { action: 'ask'; reason: string }\n\n/**\n * 档位的用户可见名。取自部署客户端的 i18n（`preset.readOnly` / `preset.workspaceWrite` /\n * `preset.fullAccess`，见方案 §1），只进 ask / deny 文案，不参与判定。\n */\nconst MODE_LABEL: Record<TierMode, string> = {\n  'read-only': '仅可查看',\n  'workspace-write': '工作区内修改',\n  'danger-full-access': '完全权限',\n}\n\n/**\n * 档位闸捕获的宿主服务（结构化形状——kit 不依赖宿主包）。\n *\n * 为什么是**捕获的引用**而不是每次 `ctx.get`：cordis 的服务读取有 inject 守卫——插件作用域\n * 对未声明 inject 的**已注册服务**调 `ctx.get(name)` 直接抛\n * `cannot get property \"<name>\" without inject`（2026-10-07 真机实测）。宿主侧的合法可选读取\n * 通道是 `ctx.inject(['<名>'], cb)`（'tools' / 'credentials' 的既有先例）：服务存在时回调收到\n * 一个以服务名为属性的上下文，缺失时回调不触发。`attachTierGate` 用三条 inject 把服务实例\n * 捕获进 `TierServicesSnapshot`，逐次调用只用捕获的引用——不再碰 `ctx.get`。\n */\nexport interface TierServicesSnapshot {\n  sandbox?: { resolve?(request?: { session?: unknown }): { mode?: unknown } | undefined }\n  approval?: { overrideOf?(session: unknown): unknown; config?: { policy?: unknown } }\n  /** 纯可选：只在 auto review 档检测用，缺了 = auto 恒 false，矩阵照走。 */\n  presets?: { current?(session: unknown): unknown }\n}\n\n/**\n * 读一次会话的有效档位。**每次调用都要重新读**：档位是会话级旋钮（会话事件折叠），用户切档后\n * 下一个调用就要按新档走，没有任何缓存的位置。快照里的服务引用由 `attachTierGate` 在宿主\n * 组合期捕获一次，引用本身不换——会话状态在服务内部，拿引用读到的就是实时值。\n *\n * @param snapshot - 捕获的宿主服务；缺谁 `services` 里就报谁（`sandbox` 缺 = 整闸不生效）。\n * @param session - 调用方 agent 的会话（`exec.agent.session`）。`undefined`（agentless）取**严侧**：\n *   无会话即无审批通道（宿主 `serviceAsk` 对 agentless 一律拒绝），policy 视作 `never`。\n */\nexport function resolveSessionTier(snapshot: TierServicesSnapshot, session: unknown): TierContext {\n  const { sandbox, approval, presets } = snapshot\n  const services: TierServices = { sandboxPolicy: sandbox !== undefined, approval: approval !== undefined }\n\n  let mode: TierMode = 'read-only'\n  if (sandbox !== undefined && typeof sandbox.resolve === 'function') {\n    const resolved = sandbox.resolve(session === undefined ? {} : { session })\n    if (\n      resolved?.mode === 'read-only' ||\n      resolved?.mode === 'workspace-write' ||\n      resolved?.mode === 'danger-full-access'\n    ) {\n      mode = resolved.mode\n    }\n    // 解析出词汇表之外的值 = 宿主方言我们不认识：按最严档处理（宁严勿松——比宿主严永远合法，\n    // 比宿主松违反本层的存在理由）。\n  }\n\n  let policy: TierPolicy\n  if (session === undefined) {\n    policy = 'never'\n  } else {\n    let override: unknown\n    if (approval !== undefined && typeof approval.overrideOf === 'function') {\n      try {\n        override = approval.overrideOf(session)\n      } catch {\n        override = undefined\n      }\n    }\n    const configured = approval?.config?.policy\n    const raw = override ?? configured\n    policy = raw === 'never' ? 'never' : 'ask'\n    // 词汇表之外的策略值按 'ask' 落：ask 在宿主侧永远 fail-closed，不会比宿主松。\n  }\n\n  let auto = false\n  if (session !== undefined && presets !== undefined && typeof presets.current === 'function') {\n    try {\n      auto = presets.current(session) === 'auto'\n    } catch {\n      auto = false\n    }\n  }\n\n  return { mode, policy, auto, services }\n}\n\n/**\n * 决策矩阵本体（方案 §2.2，纯函数）。唯一判定处——行为上的任何改动都只应该发生在这里。\n */\nexport function decideTierCall(tier: TierContext, cls: TierClass, tool: string): TierDecision {\n  if (!tier.services.sandboxPolicy) return { action: 'allow' }\n  if (tier.auto) return { action: 'allow' }\n  if (tier.mode === 'danger-full-access') return { action: 'allow' }\n  if (cls === 'read') return { action: 'allow' }\n  if (tier.policy === 'ask') {\n    return { action: 'ask', reason: tierAskReason({ tool, mode: tier.mode }) }\n  }\n  return { action: 'deny', reason: tierDenialReason({ tool, mode: tier.mode, policy: tier.policy, cls }) }\n}\n\n/** ask 的 reason（给人看的一句话；工具调用的参数已由宿主挂在弹窗上，这里不重复）。 */\nexport function tierAskReason(input: { tool: string; mode: TierMode }): string {\n  return `${input.tool}：当前会话权限档位为「${MODE_LABEL[input.mode]}」，执行前需要你确认（只允许这一次）。`\n}\n\n/** deny 的 reason（档位拒绝那一支；审批拒绝的措辞归宿主）。 */\nexport function tierDenialReason(input: {\n  tool: string\n  mode: TierMode\n  policy: TierPolicy\n  /** `exec` 类补一条 bash 指路（它走沙箱与升级通道，是被沙箱约束的合法替身）。 */\n  cls?: TierClass\n}): string {\n  const head =\n    `当前会话权限档位为「${MODE_LABEL[input.mode]}」` +\n    (input.policy === 'never' ? '且无人值守（审批策略 never）' : '') +\n    `：${input.tool} 被拒绝。`\n  const tail = `要执行这类操作，请用户调整会话权限档位。`\n  const bash = input.cls === 'exec' ? '若是纯非交互命令，可改用 bash 工具（受沙箱约束的执行通道）。' : ''\n  return `${head}${tail}${bash}`\n}\n\n/** 启动审计行：服务组合是宿主装配期事实，attach 与每次捕获到新服务时各打一行。 */\nexport function tierGateStartupLine(services: TierServices): string {\n  if (services.sandboxPolicy && services.approval) return 'tier-gate: active'\n  return (\n    `tier-gate: services absent (sandboxPolicy=${services.sandboxPolicy} approval=${services.approval}), ` +\n    'per-call gate disabled'\n  )\n}\n\n/** `attachTierGate` 的选项。 */\nexport interface TierGateOptions {\n  /** 插件 id，用于日志前缀 `[dsh-<pkg>]`。 */\n  pkg: string\n  /** 本插件 agent 工具的名单前缀（如 `['tty_', 'sftp_', 'tunnel_']`）；名单外一个都不碰。 */\n  prefixes: readonly string[]\n  /**\n   * 工具 → 风险类。返回 `undefined` 表示名单外：放行 + 每工具名一条告警（对账由守卫测试兜底，\n   * 运行期不许因为漏分类就拦死工具）。\n   */\n  classify(tool: string, args: unknown): TierClass | undefined\n  /** 日志出口（缺省 `console.log`，带 `[dsh-<pkg>]` 前缀）。 */\n  log?(message: string): void\n}\n\n/**\n * 在插件作用域上挂 `tools/pre-execute` 监听并返回注销函数。**与工具注册同生命周期**：\n * 插件禁用热生效时随工具一起撤下（tty 进 `activeDisposers`、docker 进 `toolDisposers`）。\n *\n * 服务读取走 **`ctx.inject(['<名>'], cb)`**（可选服务的宿主合法通道，'tools' / 'credentials'\n * 先例）：服务存在时回调把实例捕获进快照、缺失时回调不触发——闸随捕获进度自动从「不闸」\n * 切到「生效」，每次状态变化打一行审计。为什么不用 `ctx.get`：cordis 对插件作用域读未声明\n * inject 的已注册服务直接抛（`without inject`，2026-10-07 真机实测），详见\n * `TierServicesSnapshot` 的注释。\n *\n * `ctx.on` 对插件作用域可达的先例是 codegraph 的 `session/event` 收集器；若宿主某代不可达，\n * 打一行审计后返回空注销函数——退化成现状，不抛错。attach 本身**全程不抛**，插件 apply\n * 不能被闸门带下去。\n */\nexport function attachTierGate(ctx: Context, options: TierGateOptions): () => void {\n  const log = options.log ?? ((message: string) => {\n    console.log(`[dsh-${options.pkg}] ${message}`)\n  })\n  const snapshot: TierServicesSnapshot = {}\n  const flags = (): TierServices => ({ sandboxPolicy: snapshot.sandbox !== undefined, approval: snapshot.approval !== undefined })\n  log(tierGateStartupLine(flags()))\n\n  const disposers: Array<() => void> = []\n  const injectable = ctx as unknown as {\n    inject?(names: readonly string[], callback: (serviceCtx: unknown) => void): unknown\n  }\n  if (typeof injectable.inject === 'function') {\n    const bind = (service: string, key: 'sandbox' | 'approval' | 'presets'): void => {\n      try {\n        const dispose = injectable.inject!([service], (serviceCtx: unknown) => {\n          const svc = (serviceCtx as Record<string, unknown>)[service]\n          if (svc === undefined || svc === null) return\n          snapshot[key] = svc as never\n          log(`tier-gate: ${service} composed`)\n          log(tierGateStartupLine(flags()))\n        })\n        if (typeof dispose === 'function') disposers.push(dispose as () => void)\n      } catch (error) {\n        log(`tier-gate: inject ${service} 失败（${error instanceof Error ? error.message : String(error)}），按服务未组合处理`)\n      }\n    }\n    bind('sandboxPolicy', 'sandbox')\n    bind('approval', 'approval')\n    bind('permissionPresets', 'presets')\n  } else {\n    log('tier-gate: ctx.inject 不可用，档位服务无法捕获，per-call gate disabled')\n  }\n\n  const warnedUnclassified = new Set<string>()\n  const listener = (exec: unknown, next: () => unknown): unknown => {\n    const call = exec as { name?: unknown; args?: unknown; agent?: { session?: unknown } } | undefined\n    const name = typeof call?.name === 'string' ? call.name : undefined\n    if (name === undefined || !options.prefixes.some((prefix) => name.startsWith(prefix))) return next()\n\n    let cls: TierClass | undefined\n    try {\n      cls = options.classify(name, call?.args)\n    } catch {\n      cls = undefined\n    }\n    if (cls === undefined) {\n      if (!warnedUnclassified.has(name)) {\n        warnedUnclassified.add(name)\n        log(`tier-gate: 工具 ${name} 不在分类表里，按现状放行（分类表对账的守卫测试会红）`)\n      }\n      return next()\n    }\n\n    let tier: TierContext\n    try {\n      tier = resolveSessionTier(snapshot, call?.agent?.session)\n    } catch (error) {\n      log(`tier-gate: 档位解析失败（${error instanceof Error ? error.message : String(error)}），按现状放行`)\n      return next()\n    }\n\n    const decision = decideTierCall(tier, cls, name)\n    if (decision.action === 'allow') return next()\n    if (decision.action === 'deny') {\n      log(`tier-gate: deny tool=${name} mode=${tier.mode} policy=${tier.policy}`)\n      return { kind: 'deny', reason: decision.reason }\n    }\n    return { kind: 'ask', reason: decision.reason }\n  }\n\n  const owner = ctx as unknown as { on?(name: string, listener: unknown): unknown }\n  if (typeof owner.on !== 'function') {\n    log('tier-gate: ctx.on 不可用，逐调用闸未挂载')\n    return () => {}\n  }\n  const dispose = owner.on('tools/pre-execute', listener)\n  disposers.push(typeof dispose === 'function' ? (dispose as () => void) : () => {})\n  return () => {\n    for (const fn of disposers.splice(0)) {\n      try {\n        fn()\n      } catch {\n        /* 已注销 */\n      }\n    }\n  }\n}\n"
